static int session_scalar_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    expression = unwrap_parenthesized_expression(expression);
    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL) {
        return MYLITE_OK;
    }

    switch (expression->kind) {
    case MYLITE_SQL_AST_DATABASE_FUNCTION:
    case MYLITE_SQL_AST_SCHEMA_FUNCTION:
        if (database->session.has_selected_schema) {
            out_cell->value = database->session.selected_schema;
        }
        return MYLITE_OK;
    case MYLITE_SQL_AST_USER_FUNCTION:
    case MYLITE_SQL_AST_SESSION_USER_FUNCTION:
    case MYLITE_SQL_AST_SYSTEM_USER_FUNCTION:
        out_cell->value = database->session.client_user_identity;
        return MYLITE_OK;
    case MYLITE_SQL_AST_CURRENT_USER_FUNCTION:
        out_cell->value = database->session.current_user_identity;
        return MYLITE_OK;
    case MYLITE_SQL_AST_CURRENT_ROLE_FUNCTION:
        out_cell->value = "NONE";
        return MYLITE_OK;
    case MYLITE_SQL_AST_CONNECTION_ID_FUNCTION: {
        int written = snprintf(
            out_cell->integer_text,
            sizeof(out_cell->integer_text),
            "%" PRIu64,
            database->session.connection_id
        );
        if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
            set_runtime_error(database, "failed to format CONNECTION_ID() value");
            return MYLITE_ERROR;
        }
        out_cell->value = out_cell->integer_text;
        return MYLITE_OK;
    }
    case MYLITE_SQL_AST_VERSION_FUNCTION:
        out_cell->value = mylite_version();
        return MYLITE_OK;
    case MYLITE_SQL_AST_PI_FUNCTION:
        out_cell->value = scalar_pi_text;
        return MYLITE_OK;
    case MYLITE_SQL_AST_RAND_FUNCTION:
        return rand_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_RAND_SEED_UNSUPPORTED:
        set_unsupported_error(database, "RAND(seed) is not supported");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_CURRENT_TIMESTAMP_VALUE:
        return current_timestamp_scalar_value(database, out_cell);
    case MYLITE_SQL_AST_CURRENT_TIMESTAMP_ARGUMENT_COUNT_ERROR:
        set_native_function_parameter_count_error(database, "CURRENT_TIMESTAMP");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_LENGTH_FUNCTION:
    case MYLITE_SQL_AST_OCTET_LENGTH_FUNCTION:
    case MYLITE_SQL_AST_BIT_LENGTH_FUNCTION:
    case MYLITE_SQL_AST_CHAR_LENGTH_FUNCTION:
    case MYLITE_SQL_AST_CHARACTER_LENGTH_FUNCTION:
        return string_length_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_LOWER_FUNCTION:
    case MYLITE_SQL_AST_LCASE_FUNCTION:
    case MYLITE_SQL_AST_UPPER_FUNCTION:
    case MYLITE_SQL_AST_UCASE_FUNCTION:
        return string_case_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_ROW_COUNT_FUNCTION: {
        int written = snprintf(
            out_cell->integer_text,
            sizeof(out_cell->integer_text),
            "%" PRId64,
            database->session.previous_row_count
        );
        if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
            set_runtime_error(database, "failed to format ROW_COUNT() value");
            return MYLITE_ERROR;
        }
        out_cell->value = out_cell->integer_text;
        return MYLITE_OK;
    }
    case MYLITE_SQL_AST_FOUND_ROWS_FUNCTION: {
        int written = snprintf(
            out_cell->integer_text,
            sizeof(out_cell->integer_text),
            "%" PRIu64,
            database->session.found_rows
        );
        if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
            set_runtime_error(database, "failed to format FOUND_ROWS() value");
            return MYLITE_ERROR;
        }
        out_cell->value = out_cell->integer_text;
        return MYLITE_OK;
    }
    case MYLITE_SQL_AST_LAST_INSERT_ID_FUNCTION: {
        int written = snprintf(
            out_cell->integer_text,
            sizeof(out_cell->integer_text),
            "%" PRIu64,
            database->session.last_insert_id
        );
        if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
            set_runtime_error(database, "failed to format LAST_INSERT_ID() value");
            return MYLITE_ERROR;
        }
        out_cell->value = out_cell->integer_text;
        return MYLITE_OK;
    }
    case MYLITE_SQL_AST_LITERAL:
        return literal_projection_value(database, expression, out_cell);
    case MYLITE_SQL_AST_UNARY_EXPRESSION:
        return session_unary_scalar_value(database, expression, out_cell);
    case MYLITE_SQL_AST_BINARY_EXPRESSION:
        return session_binary_scalar_value(database, expression, out_cell);
    case MYLITE_SQL_AST_MOD_FUNCTION:
        return scalar_arithmetic_value(database, expression, out_cell);
    case MYLITE_SQL_AST_ABS_FUNCTION:
        return abs_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_SIGN_FUNCTION:
        return sign_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_CEIL_FUNCTION:
    case MYLITE_SQL_AST_CEILING_FUNCTION:
    case MYLITE_SQL_AST_FLOOR_FUNCTION:
    case MYLITE_SQL_AST_ROUND_FUNCTION:
        return rounding_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_SQRT_FUNCTION:
        return sqrt_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_DEGREES_FUNCTION:
    case MYLITE_SQL_AST_RADIANS_FUNCTION:
        return angle_conversion_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_ACOS_FUNCTION:
    case MYLITE_SQL_AST_ASIN_FUNCTION:
        return inverse_trig_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_ATAN_FUNCTION:
    case MYLITE_SQL_AST_ATAN2_FUNCTION:
        return atan_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_EXP_FUNCTION:
        return exp_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_LN_FUNCTION:
    case MYLITE_SQL_AST_LOG_FUNCTION:
    case MYLITE_SQL_AST_LOG10_FUNCTION:
    case MYLITE_SQL_AST_LOG2_FUNCTION:
        return logarithm_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_POW_FUNCTION:
    case MYLITE_SQL_AST_POWER_FUNCTION:
        return power_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_BIN_FUNCTION:
    case MYLITE_SQL_AST_OCT_FUNCTION:
        return base_conversion_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_CONV_FUNCTION:
        return conv_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_BIT_COUNT_FUNCTION:
        return bit_count_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_CAST_BINARY_EXPRESSION:
        return cast_binary_value(database, expression, out_cell);
    case MYLITE_SQL_AST_DATE_ADD_FUNCTION:
        return date_add_second_value(database, expression, out_cell);
    case MYLITE_SQL_AST_DATE_FORMAT_ARGUMENT_COUNT_ERROR:
        set_native_function_parameter_count_error(database, "DATE_FORMAT");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_LOWER_ARGUMENT_COUNT_ERROR:
        set_native_function_parameter_count_error(database, "LOWER");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_LCASE_ARGUMENT_COUNT_ERROR:
        set_native_function_parameter_count_error(database, "LCASE");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_UPPER_ARGUMENT_COUNT_ERROR:
        set_native_function_parameter_count_error(database, "UPPER");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_UCASE_ARGUMENT_COUNT_ERROR:
        set_native_function_parameter_count_error(database, "UCASE");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_DATE_FORMAT_FUNCTION:
        return date_format_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_FIELD_ARGUMENT_COUNT_ERROR:
        set_native_function_parameter_count_error(database, "FIELD");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_FIELD_FUNCTION:
        return field_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_IF_FUNCTION:
        return if_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_IFNULL_FUNCTION:
        return ifnull_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_COALESCE_FUNCTION:
        return coalesce_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_NULLIF_FUNCTION:
        return nullif_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_ISNULL_FUNCTION:
        return isnull_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_SEARCHED_CASE_EXPRESSION:
    case MYLITE_SQL_AST_SIMPLE_CASE_EXPRESSION:
        return case_expression_value(database, expression, out_cell);
    case MYLITE_SQL_AST_SCALAR_SUBQUERY:
        return scalar_subquery_value(database, expression, out_cell);
    case MYLITE_SQL_AST_SYSTEM_VARIABLE:
        return system_variable_value(database, expression, out_cell);
    default:
        return MYLITE_OK;
    }
}

static int rand_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL || expression->kind != MYLITE_SQL_AST_RAND_FUNCTION ||
        mylite_sql_ast_node_child_count(expression) != 0U) {
        set_unsupported_error(database, "RAND() supports only zero arguments");
        return MYLITE_ERROR;
    }

    rc = format_double_text(
        database,
        random_unit_double(),
        "RAND",
        out_cell->double_text,
        sizeof(out_cell->double_text)
    );
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->double_text;
    }
    return rc;
}

static double random_unit_double(void) {
    uint64_t random_bits = 0U;

    sqlite3_randomness((int)sizeof(random_bits), &random_bits);
    random_bits >>= rand_double_discard_bits;
    return ldexp((double)random_bits, -rand_double_value_bits);
}

static int current_timestamp_scalar_value(
    struct mylite_db *database,
    struct session_scalar_cell *out_cell
) {
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    rc = format_current_timestamp_text(
        database,
        out_cell->datetime_text,
        sizeof(out_cell->datetime_text)
    );
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->datetime_text;
    }
    return rc;
}

static int string_length_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    enum planned_string_length_function_kind function_kind = PLANNED_STRING_LENGTH_FUNCTION_NONE;
    struct session_scalar_cell argument_cell = {0};
    char *owned_text = NULL;
    const char *text = NULL;
    size_t text_length = 0U;
    size_t character_count = 0U;
    uint64_t result = 0U;
    bool is_null = false;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    expression = unwrap_parenthesized_expression(expression);
    function_kind = expression == NULL ? PLANNED_STRING_LENGTH_FUNCTION_NONE
                                       : string_length_function_kind(expression->kind);
    if (function_kind == PLANNED_STRING_LENGTH_FUNCTION_NONE ||
        mylite_sql_ast_node_child_count(expression) != 1U) {
        set_unsupported_error(database, "string length functions support exactly one argument");
        return MYLITE_ERROR;
    }

    rc = evaluate_string_length_scalar_argument(
        database,
        child_at(expression, 0U),
        &argument_cell,
        &owned_text,
        &text,
        &text_length,
        &is_null
    );
    if (rc != MYLITE_OK || is_null) {
        free(owned_text);
        session_scalar_cell_deinit(&argument_cell);
        return rc;
    }

    if (function_kind == PLANNED_STRING_LENGTH_FUNCTION_CHARACTER) {
        rc = validate_utf8_text(text, text_length, &character_count);
        if (rc != MYLITE_OK) {
            set_runtime_error(database, "invalid UTF-8 value in string length function");
            free(owned_text);
            session_scalar_cell_deinit(&argument_cell);
            return MYLITE_ERROR;
        }
        result = (uint64_t)character_count;
    } else if (function_kind == PLANNED_STRING_LENGTH_FUNCTION_BIT) {
        if (text_length > UINT64_MAX / byte_bit_count) {
            set_unsupported_error(database, "BIT_LENGTH() result is out of range");
            free(owned_text);
            session_scalar_cell_deinit(&argument_cell);
            return MYLITE_ERROR;
        }
        result = (uint64_t)text_length * byte_bit_count;
    } else {
        result = (uint64_t)text_length;
    }

    rc = format_uint64(database, result, out_cell->integer_text, sizeof(out_cell->integer_text));
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->integer_text;
    }
    free(owned_text);
    session_scalar_cell_deinit(&argument_cell);
    return rc;
}

static int evaluate_string_length_scalar_argument(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *inout_cell,
    char **out_owned_text,
    const char **out_text,
    size_t *out_text_length,
    bool *out_is_null
) {
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    int rc = MYLITE_OK;

    if (inout_cell == NULL || out_owned_text == NULL || out_text == NULL ||
        out_text_length == NULL || out_is_null == NULL) {
        return MYLITE_MISUSE;
    }
    *out_owned_text = NULL;
    *out_text = NULL;
    *out_text_length = 0U;
    *out_is_null = false;

    expression = unwrap_parenthesized_expression(expression);
    if (!string_length_scalar_argument_is_admitted(expression)) {
        set_unsupported_error(
            database,
            "string length functions support only string, integer, boolean, NULL, "
            "session scalar, and system variable arguments"
        );
        return MYLITE_ERROR;
    }

    if (expression->kind == MYLITE_SQL_AST_LITERAL) {
        literal_kind = mylite_sql_ast_node_literal_kind(expression);
        if (literal_kind == MYLITE_SQL_AST_LITERAL_STRING) {
            rc = decode_sql_string_literal(
                database,
                expression,
                "string length functions support only string literals",
                "string length function literals do not support NUL bytes",
                out_owned_text,
                out_text_length
            );
            if (rc == MYLITE_OK) {
                *out_text = *out_owned_text;
            }
            return rc;
        }
    }

    if (expression->kind == MYLITE_SQL_AST_LITERAL ||
        expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        rc = literal_projection_value(database, expression, inout_cell);
    } else {
        rc = string_length_session_scalar_argument_value(database, expression, inout_cell);
    }
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (inout_cell->value == NULL) {
        *out_is_null = true;
        return MYLITE_OK;
    }
    *out_text = inout_cell->value;
    *out_text_length = strlen(inout_cell->value);
    return MYLITE_OK;
}

static int string_length_session_scalar_argument_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    expression = unwrap_parenthesized_expression(expression);
    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL) {
        return MYLITE_OK;
    }

    switch (expression->kind) {
    case MYLITE_SQL_AST_DATABASE_FUNCTION:
    case MYLITE_SQL_AST_SCHEMA_FUNCTION:
        if (database->session.has_selected_schema) {
            out_cell->value = database->session.selected_schema;
        }
        return MYLITE_OK;
    case MYLITE_SQL_AST_USER_FUNCTION:
    case MYLITE_SQL_AST_SESSION_USER_FUNCTION:
    case MYLITE_SQL_AST_SYSTEM_USER_FUNCTION:
        out_cell->value = database->session.client_user_identity;
        return MYLITE_OK;
    case MYLITE_SQL_AST_CURRENT_USER_FUNCTION:
        out_cell->value = database->session.current_user_identity;
        return MYLITE_OK;
    case MYLITE_SQL_AST_CURRENT_ROLE_FUNCTION:
        out_cell->value = "NONE";
        return MYLITE_OK;
    case MYLITE_SQL_AST_CONNECTION_ID_FUNCTION: {
        int written = snprintf(
            out_cell->integer_text,
            sizeof(out_cell->integer_text),
            "%" PRIu64,
            database->session.connection_id
        );
        if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
            set_runtime_error(database, "failed to format CONNECTION_ID() value");
            return MYLITE_ERROR;
        }
        out_cell->value = out_cell->integer_text;
        return MYLITE_OK;
    }
    case MYLITE_SQL_AST_VERSION_FUNCTION:
        out_cell->value = mylite_version();
        return MYLITE_OK;
    case MYLITE_SQL_AST_PI_FUNCTION:
        out_cell->value = scalar_pi_text;
        return MYLITE_OK;
    case MYLITE_SQL_AST_RAND_FUNCTION:
        return rand_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_RAND_SEED_UNSUPPORTED:
        set_unsupported_error(database, "RAND(seed) is not supported");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_CURRENT_TIMESTAMP_VALUE:
        return current_timestamp_scalar_value(database, out_cell);
    case MYLITE_SQL_AST_CURRENT_TIMESTAMP_ARGUMENT_COUNT_ERROR:
        set_native_function_parameter_count_error(database, "CURRENT_TIMESTAMP");
        return MYLITE_ERROR;
    case MYLITE_SQL_AST_ROW_COUNT_FUNCTION: {
        int written = snprintf(
            out_cell->integer_text,
            sizeof(out_cell->integer_text),
            "%" PRId64,
            database->session.previous_row_count
        );
        if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
            set_runtime_error(database, "failed to format ROW_COUNT() value");
            return MYLITE_ERROR;
        }
        out_cell->value = out_cell->integer_text;
        return MYLITE_OK;
    }
    case MYLITE_SQL_AST_FOUND_ROWS_FUNCTION: {
        int written = snprintf(
            out_cell->integer_text,
            sizeof(out_cell->integer_text),
            "%" PRIu64,
            database->session.found_rows
        );
        if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
            set_runtime_error(database, "failed to format FOUND_ROWS() value");
            return MYLITE_ERROR;
        }
        out_cell->value = out_cell->integer_text;
        return MYLITE_OK;
    }
    case MYLITE_SQL_AST_LAST_INSERT_ID_FUNCTION: {
        int written = snprintf(
            out_cell->integer_text,
            sizeof(out_cell->integer_text),
            "%" PRIu64,
            database->session.last_insert_id
        );
        if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
            set_runtime_error(database, "failed to format LAST_INSERT_ID() value");
            return MYLITE_ERROR;
        }
        out_cell->value = out_cell->integer_text;
        return MYLITE_OK;
    }
    case MYLITE_SQL_AST_SYSTEM_VARIABLE:
        return system_variable_value(database, expression, out_cell);
    default:
        set_unsupported_error(
            database,
            "string length functions support only string, integer, boolean, NULL, "
            "session scalar, and system variable arguments"
        );
        return MYLITE_ERROR;
    }
}

static bool string_length_scalar_argument_is_admitted(
    const struct mylite_sql_ast_node *expression
) {
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;

    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        return false;
    }
    if (is_session_scalar_expression(expression)) {
        return true;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);
        const struct mylite_sql_ast_node *literal =
            unwrap_parenthesized_expression(child_at(expression, 0U));

        if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
            operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            return false;
        }
        return (literal != NULL && literal->kind == MYLITE_SQL_AST_LITERAL &&
                mylite_sql_ast_node_literal_kind(literal) == MYLITE_SQL_AST_LITERAL_INTEGER) != 0;
    }
    if (expression->kind != MYLITE_SQL_AST_LITERAL) {
        return false;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(expression);
    return (literal_kind == MYLITE_SQL_AST_LITERAL_STRING ||
            literal_kind == MYLITE_SQL_AST_LITERAL_INTEGER ||
            literal_kind == MYLITE_SQL_AST_LITERAL_TRUE ||
            literal_kind == MYLITE_SQL_AST_LITERAL_FALSE ||
            literal_kind == MYLITE_SQL_AST_LITERAL_NULL) != 0;
}

static enum planned_string_length_function_kind string_length_function_kind(
    enum mylite_sql_ast_node_kind ast_kind
) {
    switch (ast_kind) {
    case MYLITE_SQL_AST_LENGTH_FUNCTION:
    case MYLITE_SQL_AST_OCTET_LENGTH_FUNCTION:
        return PLANNED_STRING_LENGTH_FUNCTION_BYTE;
    case MYLITE_SQL_AST_BIT_LENGTH_FUNCTION:
        return PLANNED_STRING_LENGTH_FUNCTION_BIT;
    case MYLITE_SQL_AST_CHAR_LENGTH_FUNCTION:
    case MYLITE_SQL_AST_CHARACTER_LENGTH_FUNCTION:
        return PLANNED_STRING_LENGTH_FUNCTION_CHARACTER;
    default:
        return PLANNED_STRING_LENGTH_FUNCTION_NONE;
    }
}

static bool is_string_length_function_kind(enum mylite_sql_ast_node_kind ast_kind) {
    return string_length_function_kind(ast_kind) != PLANNED_STRING_LENGTH_FUNCTION_NONE;
}

static int string_case_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    enum planned_string_case_function_kind function_kind = PLANNED_STRING_CASE_FUNCTION_NONE;
    struct session_scalar_cell argument_cell = {0};
    char *owned_text = NULL;
    const char *text = NULL;
    size_t text_length = 0U;
    bool is_null = false;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    expression = unwrap_parenthesized_expression(expression);
    function_kind = expression == NULL ? PLANNED_STRING_CASE_FUNCTION_NONE
                                       : string_case_function_kind(expression->kind);
    if (function_kind == PLANNED_STRING_CASE_FUNCTION_NONE ||
        mylite_sql_ast_node_child_count(expression) != 1U) {
        set_unsupported_error(database, "string case functions support exactly one argument");
        return MYLITE_ERROR;
    }

    rc = evaluate_string_case_scalar_argument(
        database,
        child_at(expression, 0U),
        &argument_cell,
        &owned_text,
        &text,
        &text_length,
        &is_null
    );
    if (rc != MYLITE_OK || is_null) {
        free(owned_text);
        session_scalar_cell_deinit(&argument_cell);
        return rc;
    }

    rc = mylite_string_case_ascii_value(
        database,
        string_case_function_to_value_kind(function_kind),
        text,
        text_length,
        &out_cell->owned_text
    );
    if (rc == MYLITE_NOMEM) {
        set_nomem_error(database);
    } else if (rc == MYLITE_OK) {
        out_cell->value = out_cell->owned_text;
    }

    free(owned_text);
    session_scalar_cell_deinit(&argument_cell);
    return rc;
}

static int evaluate_string_case_scalar_argument(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *inout_cell,
    char **out_owned_text,
    const char **out_text,
    size_t *out_text_length,
    bool *out_is_null
) {
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    int rc = MYLITE_OK;

    if (inout_cell == NULL || out_owned_text == NULL || out_text == NULL ||
        out_text_length == NULL || out_is_null == NULL) {
        return MYLITE_MISUSE;
    }
    *out_owned_text = NULL;
    *out_text = NULL;
    *out_text_length = 0U;
    *out_is_null = false;

    expression = unwrap_parenthesized_expression(expression);
    if (!string_case_scalar_argument_is_admitted(expression)) {
        set_unsupported_error(
            database,
            "string case functions support only string, integer, boolean, NULL, "
            "session scalar, and system variable arguments"
        );
        return MYLITE_ERROR;
    }

    if (expression->kind == MYLITE_SQL_AST_LITERAL) {
        literal_kind = mylite_sql_ast_node_literal_kind(expression);
        if (literal_kind == MYLITE_SQL_AST_LITERAL_STRING) {
            rc = decode_sql_string_literal(
                database,
                expression,
                "string case functions support only string literals",
                "string case function literals do not support NUL bytes",
                out_owned_text,
                out_text_length
            );
            if (rc == MYLITE_OK) {
                *out_text = *out_owned_text;
            }
            return rc;
        }
    }

    if (expression->kind == MYLITE_SQL_AST_LITERAL ||
        expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        rc = literal_projection_value(database, expression, inout_cell);
    } else {
        rc = string_length_session_scalar_argument_value(database, expression, inout_cell);
    }
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (inout_cell->value == NULL) {
        *out_is_null = true;
        return MYLITE_OK;
    }
    *out_text = inout_cell->value;
    *out_text_length = strlen(inout_cell->value);
    return MYLITE_OK;
}

static bool string_case_scalar_argument_is_admitted(const struct mylite_sql_ast_node *expression) {
    return string_length_scalar_argument_is_admitted(expression);
}

static enum planned_string_case_function_kind string_case_function_kind(
    enum mylite_sql_ast_node_kind ast_kind
) {
    switch (ast_kind) {
    case MYLITE_SQL_AST_LOWER_FUNCTION:
    case MYLITE_SQL_AST_LCASE_FUNCTION:
        return PLANNED_STRING_CASE_FUNCTION_LOWER;
    case MYLITE_SQL_AST_UPPER_FUNCTION:
    case MYLITE_SQL_AST_UCASE_FUNCTION:
        return PLANNED_STRING_CASE_FUNCTION_UPPER;
    default:
        return PLANNED_STRING_CASE_FUNCTION_NONE;
    }
}

static bool is_string_case_function_kind(enum mylite_sql_ast_node_kind ast_kind) {
    return string_case_function_kind(ast_kind) != PLANNED_STRING_CASE_FUNCTION_NONE;
}

static enum mylite_string_case_kind string_case_function_to_value_kind(
    enum planned_string_case_function_kind function_kind
) {
    if (function_kind == PLANNED_STRING_CASE_FUNCTION_UPPER) {
        return MYLITE_STRING_CASE_UPPER;
    }
    return MYLITE_STRING_CASE_LOWER;
}

static int scalar_subquery_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    const struct mylite_sql_ast_node *statement = NULL;

    expression = unwrap_parenthesized_expression(expression);
    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL || expression->kind != MYLITE_SQL_AST_SCALAR_SUBQUERY ||
        mylite_sql_ast_node_child_count(expression) != 1U) {
        set_unsupported_error(database, "scalar subquery supports only parenthesized SELECT");
        return MYLITE_ERROR;
    }

    statement = child_at(expression, 0U);
    if (statement == NULL || statement->kind != MYLITE_SQL_AST_SELECT_STATEMENT) {
        set_unsupported_error(database, "scalar subquery supports only parenthesized SELECT");
        return MYLITE_ERROR;
    }

    return scalar_subquery_select_value(database, statement, out_cell);
}

static int scalar_subquery_select_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement,
    struct session_scalar_cell *out_cell
) {
    const struct mylite_sql_ast_node *select_list = child_at(statement, 0U);
    const struct mylite_sql_ast_node *select_item = NULL;
    const struct mylite_sql_ast_node *child = NULL;

    if (mylite_sql_ast_node_select_modifier(statement) != MYLITE_SQL_AST_SELECT_MODIFIER_DEFAULT ||
        mylite_sql_ast_node_select_options(statement) != 0U ||
        mylite_sql_ast_node_select_calc_found_rows(statement) != 0 ||
        mylite_sql_ast_node_select_locking_clause(statement) !=
            MYLITE_SQL_AST_SELECT_LOCKING_CLAUSE_NONE) {
        set_unsupported_error(database, "scalar subquery supports only plain inner SELECT");
        return MYLITE_ERROR;
    }
    if (select_list == NULL || select_list->kind != MYLITE_SQL_AST_SELECT_LIST) {
        set_unsupported_error(database, "scalar subquery supports only one explicit select item");
        return MYLITE_ERROR;
    }
    if (select_list_is_wildcard(select_list)) {
        if (select_statement_has_no_source_or_dual(statement)) {
            set_no_tables_used_error(database);
            return MYLITE_ERROR;
        }
        set_unsupported_error(database, "scalar subquery does not support table-backed SELECT");
        return MYLITE_ERROR;
    }
    if (mylite_sql_ast_node_child_count(select_list) != 1U) {
        set_scalar_subquery_column_count_error(database);
        return MYLITE_ERROR;
    }

    child = child_at(statement, 1U);
    while (child != NULL) {
        if (child->kind == MYLITE_SQL_AST_FROM_DUAL) {
            child = child->next_sibling;
            continue;
        }
        if (child->kind == MYLITE_SQL_AST_FROM_TABLE) {
            set_unsupported_error(database, "scalar subquery does not support table-backed SELECT");
            return MYLITE_ERROR;
        }
        set_unsupported_error(
            database,
            "scalar subquery supports only no-source or DUAL inner SELECT"
        );
        return MYLITE_ERROR;
    }

    select_item = child_at(select_list, 0U);
    if (select_item == NULL || select_item->kind != MYLITE_SQL_AST_SELECT_ITEM) {
        set_unsupported_error(database, "scalar subquery supports only one explicit select item");
        return MYLITE_ERROR;
    }
    return scalar_subquery_inner_value(database, child_at(select_item, 0U), out_cell);
}

static int scalar_subquery_inner_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_unsupported_error(database, "scalar subquery supports only scalar inner values");
        return MYLITE_ERROR;
    }

    switch (expression->kind) {
    case MYLITE_SQL_AST_DATABASE_FUNCTION:
    case MYLITE_SQL_AST_SCHEMA_FUNCTION:
        if (database->session.has_selected_schema) {
            out_cell->value = database->session.selected_schema;
        }
        return MYLITE_OK;
    case MYLITE_SQL_AST_LITERAL:
        return literal_projection_value(database, expression, out_cell);
    case MYLITE_SQL_AST_UNARY_EXPRESSION:
        if (is_scalar_projection_literal_expression(expression)) {
            return literal_projection_value(database, expression, out_cell);
        }
        break;
    case MYLITE_SQL_AST_SYSTEM_VARIABLE:
        return system_variable_value(database, expression, out_cell);
    default:
        break;
    }

    set_unsupported_error(
        database,
        "scalar subquery supports only DATABASE(), SCHEMA(), integer, boolean, NULL, "
        "and system variable inner values"
    );
    return MYLITE_ERROR;
}

static int session_scalar_value_without_case(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    expression = unwrap_parenthesized_expression(expression);
    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL) {
        return MYLITE_OK;
    }

    switch (expression->kind) {
    case MYLITE_SQL_AST_LITERAL:
        return literal_projection_value(database, expression, out_cell);
    case MYLITE_SQL_AST_UNARY_EXPRESSION:
        return session_unary_scalar_value(database, expression, out_cell);
    case MYLITE_SQL_AST_BINARY_EXPRESSION:
        return session_binary_scalar_value(database, expression, out_cell);
    case MYLITE_SQL_AST_MOD_FUNCTION:
        return scalar_arithmetic_value(database, expression, out_cell);
    case MYLITE_SQL_AST_IF_FUNCTION:
        return if_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_IFNULL_FUNCTION:
        return ifnull_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_COALESCE_FUNCTION:
        return coalesce_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_NULLIF_FUNCTION:
        return nullif_function_value(database, expression, out_cell);
    case MYLITE_SQL_AST_ISNULL_FUNCTION:
        return isnull_function_value(database, expression, out_cell);
    default:
        return MYLITE_OK;
    }
}

static int session_unary_scalar_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    if (is_scalar_projection_literal_expression(expression)) {
        return literal_projection_value(database, expression, out_cell);
    }
    if (is_scalar_bitwise_unary_operator(mylite_sql_ast_node_operator(expression))) {
        return scalar_bitwise_value(database, expression, out_cell);
    }
    if (is_scalar_logical_unary_operator(mylite_sql_ast_node_operator(expression))) {
        return scalar_logical_value(database, expression, out_cell);
    }
    return scalar_arithmetic_value(database, expression, out_cell);
}

static int session_binary_scalar_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    if (is_scalar_division_projection_expression(expression)) {
        return scalar_division_value(database, expression, out_cell);
    }
    if (is_scalar_bitwise_projection_expression(expression)) {
        return scalar_bitwise_value(database, expression, out_cell);
    }
    if (is_scalar_logical_projection_expression(expression)) {
        return scalar_logical_value(database, expression, out_cell);
    }
    if (is_date_format_numeric_equal_expression(expression)) {
        return date_format_numeric_equal_value(database, expression, out_cell);
    }
    if (is_scalar_comparison_operator(mylite_sql_ast_node_operator(expression))) {
        return scalar_comparison_value(database, expression, out_cell);
    }
    return scalar_arithmetic_value(database, expression, out_cell);
}

static int field_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    const struct mylite_sql_ast_node *arguments = NULL;
    struct field_scalar_argument *values = NULL;
    struct field_scalar_argument_list field_arguments = {0};
    enum planned_row_scalar_field_domain domain = PLANNED_ROW_SCALAR_FIELD_DOMAIN_NONE;
    size_t argument_count = 0U;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL || expression->kind != MYLITE_SQL_AST_FIELD_FUNCTION ||
        mylite_sql_ast_node_child_count(expression) != 1U) {
        set_unsupported_error(database, "FIELD() supports only FIELD(search, value, ...)");
        return MYLITE_ERROR;
    }

    arguments = child_at(expression, 0U);
    if (arguments == NULL || arguments->kind != MYLITE_SQL_AST_FUNCTION_ARGUMENT_LIST) {
        set_native_function_parameter_count_error(database, "FIELD");
        return MYLITE_ERROR;
    }
    argument_count = mylite_sql_ast_node_child_count(arguments);
    if (argument_count < 2U) {
        set_native_function_parameter_count_error(database, "FIELD");
        return MYLITE_ERROR;
    }
    if (argument_count > SIZE_MAX / sizeof(*values)) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    values = (struct field_scalar_argument *)calloc(argument_count, sizeof(*values));
    if (values == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    rc = evaluate_field_scalar_arguments(database, arguments, values, argument_count, &domain);
    if (rc == MYLITE_OK) {
        field_arguments.values = values;
        field_arguments.count = argument_count;
        rc = format_field_scalar_result_position(
            database,
            field_scalar_result_position(&field_arguments, domain),
            out_cell
        );
    }

    for (size_t argument_index = 0U; argument_index < argument_count; ++argument_index) {
        field_scalar_argument_deinit(&values[argument_index]);
    }
    free(values);
    return rc;
}

static int evaluate_field_scalar_arguments(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *arguments,
    struct field_scalar_argument *values,
    size_t argument_count,
    enum planned_row_scalar_field_domain *out_domain
) {
    const struct mylite_sql_ast_node *argument = child_at(arguments, 0U);
    enum planned_row_scalar_field_domain domain = PLANNED_ROW_SCALAR_FIELD_DOMAIN_NONE;

    if (values == NULL || out_domain == NULL) {
        return MYLITE_MISUSE;
    }
    for (size_t argument_index = 0U; argument_index < argument_count; ++argument_index) {
        int rc = MYLITE_OK;

        if (argument == NULL) {
            set_parse_error(database, NULL);
            return MYLITE_ERROR;
        }
        rc = evaluate_field_scalar_argument(database, argument, &values[argument_index]);
        if (rc != MYLITE_OK) {
            return rc;
        }
        rc = merge_field_domain(database, values[argument_index].domain, &domain);
        if (rc != MYLITE_OK) {
            return rc;
        }
        argument = argument->next_sibling;
    }
    if (argument != NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    *out_domain = domain;
    return MYLITE_OK;
}

static int evaluate_field_scalar_argument(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct field_scalar_argument *out_argument
) {
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;

    if (out_argument == NULL) {
        return MYLITE_MISUSE;
    }
    *out_argument = (struct field_scalar_argument){0};
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_unsupported_error(
            database,
            "FIELD() supports only string, integer, boolean, and NULL arguments"
        );
        return MYLITE_ERROR;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        return evaluate_field_scalar_integer_argument(database, expression, out_argument);
    }
    if (expression->kind != MYLITE_SQL_AST_LITERAL) {
        set_unsupported_error(
            database,
            "FIELD() supports only string, integer, boolean, and NULL arguments"
        );
        return MYLITE_ERROR;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(expression);
    switch (literal_kind) {
    case MYLITE_SQL_AST_LITERAL_STRING:
        return evaluate_field_scalar_string_argument(database, expression, out_argument);
    case MYLITE_SQL_AST_LITERAL_INTEGER:
        return evaluate_field_scalar_integer_argument(database, expression, out_argument);
    case MYLITE_SQL_AST_LITERAL_TRUE:
        out_argument->domain = PLANNED_ROW_SCALAR_FIELD_DOMAIN_INTEGER;
        out_argument->integer = 1;
        return MYLITE_OK;
    case MYLITE_SQL_AST_LITERAL_FALSE:
        out_argument->domain = PLANNED_ROW_SCALAR_FIELD_DOMAIN_INTEGER;
        out_argument->integer = 0;
        return MYLITE_OK;
    case MYLITE_SQL_AST_LITERAL_NULL:
        out_argument->is_null = true;
        return MYLITE_OK;
    default:
        break;
    }

    set_unsupported_error(
        database,
        "FIELD() supports only string, integer, boolean, and NULL arguments"
    );
    return MYLITE_ERROR;
}

static int evaluate_field_scalar_string_argument(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *literal,
    struct field_scalar_argument *out_argument
) {
    char *text = NULL;
    size_t text_length = 0U;
    int rc = decode_sql_string_literal(
        database,
        literal,
        "FIELD() supports only string literals",
        "FIELD() string literals do not support NUL bytes",
        &text,
        &text_length
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (!field_ascii_text_is_supported(text, text_length)) {
        free(text);
        set_unsupported_error(database, "FIELD() string literals support only ASCII values");
        return MYLITE_ERROR;
    }

    out_argument->domain = PLANNED_ROW_SCALAR_FIELD_DOMAIN_STRING;
    out_argument->text = text;
    out_argument->text_length = text_length;
    return MYLITE_OK;
}

static int evaluate_field_scalar_integer_argument(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct field_scalar_argument *out_argument
) {
    const struct mylite_sql_ast_node *literal = expression;
    bool is_negative = false;
    uint64_t magnitude = 0U;
    int rc = MYLITE_OK;

    if (expression != NULL && expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

        if (operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            is_negative = true;
        } else if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE) {
            set_unsupported_error(database, "FIELD() supports only signed integer literals");
            return MYLITE_ERROR;
        }
        literal = unwrap_parenthesized_expression(child_at(expression, 0U));
    }
    if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER) {
        set_unsupported_error(database, "FIELD() supports only signed integer literals");
        return MYLITE_ERROR;
    }

    rc = parse_unsigned_integer_literal(&literal->span, &magnitude);
    if (rc != MYLITE_OK || (is_negative && magnitude > (uint64_t)INT64_MAX + 1U) ||
        (!is_negative && magnitude > (uint64_t)INT64_MAX)) {
        set_unsupported_error(
            database,
            "FIELD() integer literals must fit the signed 64-bit range"
        );
        return MYLITE_ERROR;
    }

    out_argument->domain = PLANNED_ROW_SCALAR_FIELD_DOMAIN_INTEGER;
    if (is_negative && magnitude == (uint64_t)INT64_MAX + 1U) {
        out_argument->integer = INT64_MIN;
    } else if (is_negative) {
        out_argument->integer = -(int64_t)magnitude;
    } else {
        out_argument->integer = (int64_t)magnitude;
    }
    return MYLITE_OK;
}

static int merge_field_domain(
    struct mylite_db *database,
    enum planned_row_scalar_field_domain incoming,
    enum planned_row_scalar_field_domain *inout_domain
) {
    if (inout_domain == NULL) {
        return MYLITE_MISUSE;
    }
    if (incoming == PLANNED_ROW_SCALAR_FIELD_DOMAIN_NONE) {
        return MYLITE_OK;
    }
    if (*inout_domain == PLANNED_ROW_SCALAR_FIELD_DOMAIN_NONE) {
        *inout_domain = incoming;
        return MYLITE_OK;
    }
    if (*inout_domain == incoming) {
        return MYLITE_OK;
    }

    set_unsupported_error(database, "FIELD() does not support mixed string and numeric arguments");
    return MYLITE_ERROR;
}

static bool field_ascii_text_is_supported(const char *text, size_t text_length) {
    if (text == NULL) {
        return false;
    }
    for (size_t index = 0U; index < text_length; ++index) {
        if ((unsigned char)text[index] > ascii_text_max_byte) {
            return false;
        }
    }
    return true;
}

static bool field_ascii_text_equals_case_insensitive(
    const char *left,
    size_t left_length,
    const char *right,
    size_t right_length
) {
    if (left == NULL || right == NULL || left_length != right_length) {
        return false;
    }
    for (size_t index = 0U; index < left_length; ++index) {
        if (ascii_lower((unsigned char)left[index]) != ascii_lower((unsigned char)right[index])) {
            return false;
        }
    }
    return true;
}

static size_t field_scalar_result_position(
    const struct field_scalar_argument_list *arguments,
    enum planned_row_scalar_field_domain domain
) {
    if (arguments == NULL || arguments->values == NULL || arguments->count < 2U ||
        arguments->values[0].is_null) {
        return 0U;
    }
    for (size_t argument_index = 1U; argument_index < arguments->count; ++argument_index) {
        if (field_scalar_arguments_match(
                &arguments->values[0],
                &arguments->values[argument_index],
                domain
            )) {
            return argument_index;
        }
    }
    return 0U;
}

static bool field_scalar_arguments_match(
    const struct field_scalar_argument *left,
    const struct field_scalar_argument *right,
    enum planned_row_scalar_field_domain domain
) {
    if (left == NULL || right == NULL || right->is_null) {
        return false;
    }
    if (domain == PLANNED_ROW_SCALAR_FIELD_DOMAIN_STRING) {
        return field_ascii_text_equals_case_insensitive(
            left->text,
            left->text_length,
            right->text,
            right->text_length
        );
    }
    if (domain == PLANNED_ROW_SCALAR_FIELD_DOMAIN_INTEGER) {
        return left->integer == right->integer;
    }
    return false;
}

static int format_field_scalar_result_position(
    struct mylite_db *database,
    size_t result_position,
    struct session_scalar_cell *out_cell
) {
    int written =
        snprintf(out_cell->integer_text, sizeof(out_cell->integer_text), "%zu", result_position);

    if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
        set_runtime_error(database, "failed to format FIELD() value");
        return MYLITE_ERROR;
    }
    out_cell->value = out_cell->integer_text;
    return MYLITE_OK;
}

static void field_scalar_argument_deinit(struct field_scalar_argument *argument) {
    if (argument == NULL) {
        return;
    }
    free(argument->text);
    *argument = (struct field_scalar_argument){0};
}

static int scalar_division_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct scalar_arithmetic_value left = {.is_null = false, .integer = 0};
    struct scalar_arithmetic_value right = {.is_null = false, .integer = 0};
    size_t warning_count = 0U;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    expression = unwrap_parenthesized_expression(expression);
    if (!is_scalar_division_projection_expression(expression)) {
        set_scalar_division_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_scalar_arithmetic_expression(database, child_at(expression, 0U), &left);
    if (rc == MYLITE_OK &&
        scalar_division_left_null_short_circuits(child_at(expression, 0U), &left)) {
        out_cell->staged_division_by_zero_warning_count = left.division_by_zero_warning_count;
        return MYLITE_OK;
    }
    if (rc == MYLITE_OK) {
        rc = evaluate_scalar_arithmetic_expression(database, child_at(expression, 1U), &right);
    }
    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = accumulate_staged_division_by_zero_warnings(
        database,
        left.division_by_zero_warning_count,
        &warning_count
    );
    if (rc == MYLITE_OK) {
        rc = accumulate_staged_division_by_zero_warnings(
            database,
            right.division_by_zero_warning_count,
            &warning_count
        );
    }
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (left.is_null || right.is_null) {
        out_cell->staged_division_by_zero_warning_count = warning_count;
        return MYLITE_OK;
    }
    if (right.integer == 0) {
        rc = accumulate_staged_division_by_zero_warnings(database, 1U, &warning_count);
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = warning_count;
        }
        return rc;
    }

    rc = format_scalar_division_value(
        database,
        left.integer,
        right.integer,
        out_cell->integer_text,
        sizeof(out_cell->integer_text)
    );
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->integer_text;
        out_cell->staged_division_by_zero_warning_count = warning_count;
    }
    return rc;
}

static bool scalar_division_left_null_short_circuits(
    const struct mylite_sql_ast_node *expression,
    const struct scalar_arithmetic_value *left
) {
    if (left == NULL || !left->is_null) {
        return false;
    }
    if (left->division_by_zero_warning_count != 0U) {
        return true;
    }

    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        return false;
    }
    if (expression->kind == MYLITE_SQL_AST_IF_FUNCTION) {
        return true;
    }
    if (expression->kind == MYLITE_SQL_AST_NULLIF_FUNCTION) {
        return true;
    }
    return false;
}

static int format_scalar_division_value(
    struct mylite_db *database,
    int64_t numerator,
    int64_t denominator,
    char *buffer,
    size_t buffer_size
) {
    uint64_t numerator_magnitude = absolute_int64_magnitude(numerator);
    uint64_t denominator_magnitude = absolute_int64_magnitude(denominator);
    uint64_t integer_part = 0U;
    uint64_t remainder = 0U;
    unsigned int fraction = 0U;
    int round_digit = 0;
    bool is_negative = (numerator < 0) != (denominator < 0);
    int written = 0;

    if (buffer == NULL || denominator_magnitude == 0U) {
        return MYLITE_MISUSE;
    }

    integer_part = numerator_magnitude / denominator_magnitude;
    remainder = numerator_magnitude % denominator_magnitude;
    for (size_t digit_index = 0U; digit_index < avg_fraction_digits; ++digit_index) {
        int digit = next_decimal_digit(&remainder, denominator_magnitude);

        if (digit < 0) {
            set_runtime_error(database, "failed to format scalar division value");
            return MYLITE_ERROR;
        }
        fraction = (fraction * decimal_base) + (unsigned int)digit;
    }
    round_digit = next_decimal_digit(&remainder, denominator_magnitude);
    if (round_digit < 0) {
        set_runtime_error(database, "failed to format scalar division value");
        return MYLITE_ERROR;
    }
    if (round_digit >= avg_round_half_digit) {
        ++fraction;
        if (fraction == avg_fraction_scale) {
            fraction = 0U;
            ++integer_part;
        }
    }

    written = snprintf(
        buffer,
        buffer_size,
        "%s%" PRIu64 ".%04u",
        is_negative && (integer_part != 0U || fraction != 0U) ? "-" : "",
        integer_part,
        fraction
    );
    if (written < 0 || (size_t)written >= buffer_size) {
        set_runtime_error(database, "failed to format scalar division value");
        return MYLITE_ERROR;
    }
    return MYLITE_OK;
}

static int scalar_bitwise_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct scalar_bitwise_value value = {.is_null = false, .integer = 0U};
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    rc = evaluate_scalar_bitwise_expression(database, expression, &value);
    if (rc != MYLITE_OK || value.is_null) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    rc = format_uint64(
        database,
        value.integer,
        out_cell->integer_text,
        sizeof(out_cell->integer_text)
    );
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->integer_text;
        out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
    }
    return rc;
}

static int abs_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct scalar_bitwise_value value = {.is_null = false, .integer = 0U};
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL || mylite_sql_ast_node_child_count(expression) != 1U) {
        set_abs_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_abs_operand(database, child_at(expression, 0U), &value);
    if (rc != MYLITE_OK || value.is_null) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    rc = format_uint64(
        database,
        value.integer,
        out_cell->integer_text,
        sizeof(out_cell->integer_text)
    );
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->integer_text;
        out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
    }
    return rc;
}

static int evaluate_abs_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_bitwise_value *out_value
) {
    struct scalar_arithmetic_value arithmetic = {.is_null = false, .integer = 0};
    bool handled = false;
    int rc = MYLITE_OK;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct scalar_bitwise_value){.is_null = false, .integer = 0U};
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_abs_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_abs_direct_literal_operand(database, expression, out_value, &handled);
    if (rc != MYLITE_OK || handled) {
        return rc;
    }
    if (is_scalar_bitwise_projection_expression(expression)) {
        return evaluate_scalar_bitwise_expression(database, expression, out_value);
    }
    if (!is_scalar_arithmetic_projection_expression(expression)) {
        set_abs_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_scalar_arithmetic_expression(database, expression, &arithmetic);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_value->is_null = arithmetic.is_null;
    out_value->division_by_zero_warning_count = arithmetic.division_by_zero_warning_count;
    if (arithmetic.is_null) {
        return MYLITE_OK;
    }
    if (arithmetic.integer == INT64_MIN) {
        set_abs_signed_minimum_overflow_error(database);
        return MYLITE_ERROR;
    }
    if (arithmetic.integer < 0) {
        out_value->integer = (uint64_t)(-arithmetic.integer);
    } else {
        out_value->integer = (uint64_t)arithmetic.integer;
    }
    return MYLITE_OK;
}

static int evaluate_abs_direct_literal_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_bitwise_value *out_value,
    bool *out_handled
) {
    static const uint64_t int64_min_magnitude = 9223372036854775808ULL;
    const struct mylite_sql_ast_node *literal = expression;
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    bool is_negative = false;
    bool has_sign = false;
    uint64_t magnitude = 0U;

    if (out_value == NULL || out_handled == NULL) {
        return MYLITE_MISUSE;
    }
    *out_handled = false;
    if (expression == NULL) {
        return MYLITE_OK;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

        if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
            operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            return MYLITE_OK;
        }
        literal = unwrap_parenthesized_expression(child_at(expression, 0U));
        if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
            mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER) {
            return MYLITE_OK;
        }
        has_sign = true;
        is_negative = operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE;
    }
    if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL) {
        return MYLITE_OK;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(literal);
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
        out_value->is_null = true;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_TRUE) {
        out_value->integer = 1U;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_FALSE) {
        out_value->integer = 0U;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (literal_kind != MYLITE_SQL_AST_LITERAL_INTEGER) {
        return MYLITE_OK;
    }
    *out_handled = true;

    if (parse_unsigned_integer_literal(&literal->span, &magnitude) != MYLITE_OK) {
        set_abs_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (is_negative && magnitude == int64_min_magnitude) {
        set_abs_signed_minimum_overflow_error(database);
        return MYLITE_ERROR;
    }
    out_value->integer = magnitude;
    return MYLITE_OK;
}

static int sign_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct scalar_arithmetic_value value = {.is_null = false, .integer = 0};
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL || mylite_sql_ast_node_child_count(expression) != 1U) {
        set_sign_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_sign_operand(database, child_at(expression, 0U), &value);
    if (rc != MYLITE_OK || value.is_null) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    if (value.integer < 0) {
        out_cell->value = "-1";
    } else if (value.integer > 0) {
        out_cell->value = "1";
    } else {
        out_cell->value = "0";
    }
    out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
    return MYLITE_OK;
}

static int evaluate_sign_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_arithmetic_value *out_value
) {
    struct scalar_arithmetic_value arithmetic = {.is_null = false, .integer = 0};
    bool handled = false;
    int rc = MYLITE_OK;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct scalar_arithmetic_value){.is_null = false, .integer = 0};
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_sign_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_sign_direct_literal_operand(database, expression, out_value, &handled);
    if (rc != MYLITE_OK || handled) {
        return rc;
    }
    if (is_scalar_bitwise_projection_expression(expression)) {
        struct scalar_bitwise_value bitwise = {.is_null = false, .integer = 0U};

        rc = evaluate_scalar_bitwise_expression(database, expression, &bitwise);
        if (rc != MYLITE_OK) {
            return rc;
        }
        out_value->is_null = bitwise.is_null;
        out_value->division_by_zero_warning_count = bitwise.division_by_zero_warning_count;
        if (!bitwise.is_null) {
            out_value->integer = bitwise.integer == 0U ? 0 : 1;
        }
        return MYLITE_OK;
    }
    if (!is_scalar_arithmetic_projection_expression(expression)) {
        set_sign_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_scalar_arithmetic_expression(database, expression, &arithmetic);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_value->is_null = arithmetic.is_null;
    out_value->division_by_zero_warning_count = arithmetic.division_by_zero_warning_count;
    if (arithmetic.is_null) {
        return MYLITE_OK;
    }
    if (arithmetic.integer < 0) {
        out_value->integer = -1;
    } else if (arithmetic.integer > 0) {
        out_value->integer = 1;
    }
    return MYLITE_OK;
}

static int evaluate_sign_direct_literal_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_arithmetic_value *out_value,
    bool *out_handled
) {
    const struct mylite_sql_ast_node *literal = expression;
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    bool is_negative = false;
    bool has_sign = false;

    if (out_value == NULL || out_handled == NULL) {
        return MYLITE_MISUSE;
    }
    *out_handled = false;
    if (expression == NULL) {
        return MYLITE_OK;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

        if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
            operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            return MYLITE_OK;
        }
        literal = unwrap_parenthesized_expression(child_at(expression, 0U));
        if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
            mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER) {
            return MYLITE_OK;
        }
        has_sign = true;
        is_negative = operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE;
    }
    if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL) {
        return MYLITE_OK;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(literal);
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
        out_value->is_null = true;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_TRUE) {
        out_value->integer = 1;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_FALSE) {
        out_value->integer = 0;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (literal_kind != MYLITE_SQL_AST_LITERAL_INTEGER) {
        return MYLITE_OK;
    }
    *out_handled = true;

    return sign_of_decimal_integer_literal(database, &literal->span, is_negative, out_value);
}

static int sign_of_decimal_integer_literal(
    struct mylite_db *database,
    const struct mylite_sql_source_span *span,
    bool is_negative,
    struct scalar_arithmetic_value *out_value
) {
    bool is_zero = true;

    if (span == NULL || span->text == NULL || span->length == 0U || out_value == NULL) {
        set_sign_unsupported_error(database);
        return MYLITE_ERROR;
    }

    for (size_t index = 0U; index < span->length; ++index) {
        unsigned char byte = (unsigned char)span->text[index];

        if (byte < '0' || byte > '9') {
            set_sign_unsupported_error(database);
            return MYLITE_ERROR;
        }
        if (byte != '0') {
            is_zero = false;
        }
    }

    if (is_zero) {
        out_value->integer = 0;
    } else if (is_negative) {
        out_value->integer = -1;
    } else {
        out_value->integer = 1;
    }
    return MYLITE_OK;
}

static int rounding_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL || mylite_sql_ast_node_child_count(expression) != 1U) {
        set_rounding_unsupported_error(database);
        return MYLITE_ERROR;
    }

    return evaluate_rounding_operand(database, child_at(expression, 0U), out_cell);
}

static int evaluate_rounding_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    bool handled = false;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_rounding_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_rounding_direct_literal_operand(database, expression, out_cell, &handled);
    if (rc != MYLITE_OK || handled) {
        return rc;
    }
    if (is_scalar_bitwise_projection_expression(expression)) {
        struct scalar_bitwise_value bitwise = {.is_null = false, .integer = 0U};

        rc = evaluate_scalar_bitwise_expression(database, expression, &bitwise);
        if (rc != MYLITE_OK || bitwise.is_null) {
            if (rc == MYLITE_OK) {
                out_cell->staged_division_by_zero_warning_count =
                    bitwise.division_by_zero_warning_count;
            }
            return rc;
        }
        rc = format_uint64(
            database,
            bitwise.integer,
            out_cell->integer_text,
            sizeof(out_cell->integer_text)
        );
        if (rc == MYLITE_OK) {
            out_cell->value = out_cell->integer_text;
            out_cell->staged_division_by_zero_warning_count =
                bitwise.division_by_zero_warning_count;
        }
        return rc;
    }
    if (is_scalar_arithmetic_projection_expression(expression)) {
        struct scalar_arithmetic_value arithmetic = {.is_null = false, .integer = 0};
        int written = 0;

        rc = evaluate_scalar_arithmetic_expression(database, expression, &arithmetic);
        if (rc != MYLITE_OK || arithmetic.is_null) {
            if (rc == MYLITE_OK) {
                out_cell->staged_division_by_zero_warning_count =
                    arithmetic.division_by_zero_warning_count;
            }
            return rc;
        }
        written = snprintf(
            out_cell->integer_text,
            sizeof(out_cell->integer_text),
            "%" PRId64,
            arithmetic.integer
        );
        if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
            set_runtime_error(database, "failed to format scalar rounding value");
            return MYLITE_ERROR;
        }
        out_cell->value = out_cell->integer_text;
        out_cell->staged_division_by_zero_warning_count = arithmetic.division_by_zero_warning_count;
        return MYLITE_OK;
    }

    set_rounding_unsupported_error(database);
    return MYLITE_ERROR;
}

static int evaluate_rounding_direct_literal_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell,
    bool *out_handled
) {
    const struct mylite_sql_ast_node *literal = expression;
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    bool is_negative = false;
    bool has_sign = false;
    int rc = MYLITE_OK;

    if (out_cell == NULL || out_handled == NULL) {
        return MYLITE_MISUSE;
    }
    *out_handled = false;
    if (expression == NULL) {
        return MYLITE_OK;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

        if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
            operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            return MYLITE_OK;
        }
        literal = unwrap_parenthesized_expression(child_at(expression, 0U));
        if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
            mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER) {
            return MYLITE_OK;
        }
        has_sign = true;
        is_negative = operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE;
    }
    if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL) {
        return MYLITE_OK;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(literal);
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_TRUE) {
        out_cell->value = "1";
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_FALSE) {
        out_cell->value = "0";
        *out_handled = true;
        return MYLITE_OK;
    }
    if (literal_kind != MYLITE_SQL_AST_LITERAL_INTEGER) {
        return MYLITE_OK;
    }
    *out_handled = true;

    rc = normalize_decimal_integer_literal(
        database,
        &literal->span,
        is_negative,
        out_cell->literal_text,
        sizeof(out_cell->literal_text)
    );
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->literal_text;
    }
    return rc;
}

static int sqrt_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct approximate_numeric_input_value value = {
        .is_null = false,
        .is_negative = false,
        .magnitude = 0U,
        .division_by_zero_warning_count = 0U,
    };
    double result = 0.0;
    uint64_t integer_result = 0U;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL || expression->kind != MYLITE_SQL_AST_SQRT_FUNCTION ||
        mylite_sql_ast_node_child_count(expression) != 1U) {
        set_sqrt_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_approximate_numeric_operand(
        database,
        child_at(expression, 0U),
        &value,
        set_sqrt_unsupported_error
    );
    if (rc != MYLITE_OK || value.is_null || value.is_negative) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    result = sqrt((double)value.magnitude);
    integer_result = (uint64_t)result;
    if ((double)integer_result == result) {
        rc = format_uint64(
            database,
            integer_result,
            out_cell->double_text,
            sizeof(out_cell->double_text)
        );
    } else {
        rc = format_double_text(
            database,
            result,
            "SQRT",
            out_cell->double_text,
            sizeof(out_cell->double_text)
        );
    }
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->double_text;
        out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
    }
    return rc;
}

static int angle_conversion_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct approximate_numeric_input_value value = {
        .is_null = false,
        .is_negative = false,
        .magnitude = 0U,
        .division_by_zero_warning_count = 0U,
    };
    bool is_degrees = false;
    const char *function_name = NULL;
    double input = 0.0;
    double output = 0.0;
    double pi = acos(-1.0);
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL ||
        (expression->kind != MYLITE_SQL_AST_DEGREES_FUNCTION &&
         expression->kind != MYLITE_SQL_AST_RADIANS_FUNCTION) ||
        mylite_sql_ast_node_child_count(expression) != 1U) {
        set_angle_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }

    is_degrees = expression->kind == MYLITE_SQL_AST_DEGREES_FUNCTION;
    if (is_degrees) {
        function_name = "DEGREES";
    } else {
        function_name = "RADIANS";
    }
    rc = evaluate_approximate_numeric_operand(
        database,
        child_at(expression, 0U),
        &value,
        set_angle_conversion_unsupported_error
    );
    if (rc != MYLITE_OK || value.is_null) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    input = (double)value.magnitude;
    if (value.is_negative) {
        input = -input;
    }
    if (is_degrees) {
        output = input * (angle_conversion_half_turn_degrees / pi);
    } else {
        output = input * (pi / angle_conversion_half_turn_degrees);
    }
    rc = format_double_text(
        database,
        output,
        function_name,
        out_cell->double_text,
        sizeof(out_cell->double_text)
    );
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->double_text;
        out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
    }
    return rc;
}

static int inverse_trig_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct approximate_numeric_input_value value = {
        .is_null = false,
        .is_negative = false,
        .magnitude = 0U,
        .division_by_zero_warning_count = 0U,
    };
    bool is_acos = false;
    const char *function_name = NULL;
    double input = 0.0;
    double output = 0.0;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL ||
        (expression->kind != MYLITE_SQL_AST_ACOS_FUNCTION &&
         expression->kind != MYLITE_SQL_AST_ASIN_FUNCTION) ||
        mylite_sql_ast_node_child_count(expression) != 1U) {
        set_inverse_trig_unsupported_error(database);
        return MYLITE_ERROR;
    }

    is_acos = expression->kind == MYLITE_SQL_AST_ACOS_FUNCTION;
    if (is_acos) {
        function_name = "ACOS";
    } else {
        function_name = "ASIN";
    }
    rc = evaluate_approximate_numeric_operand(
        database,
        child_at(expression, 0U),
        &value,
        set_inverse_trig_unsupported_error
    );
    if (rc != MYLITE_OK || value.is_null || value.magnitude > 1U) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    input = (double)value.magnitude;
    if (value.is_negative) {
        input = -input;
    }
    if (is_acos) {
        output = acos(input);
    } else {
        output = asin(input);
    }
    rc = format_double_text(
        database,
        output,
        function_name,
        out_cell->double_text,
        sizeof(out_cell->double_text)
    );
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->double_text;
        out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
    }
    return rc;
}

static int atan_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct approximate_numeric_input_value first = {
        .is_null = false,
        .is_negative = false,
        .magnitude = 0U,
        .division_by_zero_warning_count = 0U,
    };
    const char *function_name = NULL;
    size_t child_count = 0U;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL || (expression->kind != MYLITE_SQL_AST_ATAN_FUNCTION &&
                               expression->kind != MYLITE_SQL_AST_ATAN2_FUNCTION)) {
        set_atan_unsupported_error(database);
        return MYLITE_ERROR;
    }
    child_count = mylite_sql_ast_node_child_count(expression);
    if (child_count != 1U && child_count != 2U) {
        set_atan_unsupported_error(database);
        return MYLITE_ERROR;
    }

    function_name = expression->kind == MYLITE_SQL_AST_ATAN_FUNCTION ? "ATAN" : "ATAN2";
    rc = evaluate_approximate_numeric_operand(
        database,
        child_at(expression, 0U),
        &first,
        set_atan_unsupported_error
    );
    if (rc != MYLITE_OK || first.is_null) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = first.division_by_zero_warning_count;
        }
        return rc;
    }

    if (child_count == 1U) {
        return atan_one_argument_function_value(database, &first, function_name, out_cell);
    }

    return atan_two_argument_function_value(database, expression, &first, function_name, out_cell);
}

static int atan_one_argument_function_value(
    struct mylite_db *database,
    const struct approximate_numeric_input_value *first,
    const char *function_name,
    struct session_scalar_cell *out_cell
) {
    size_t warning_count = 0U;
    double output = 0.0;
    int rc = MYLITE_OK;

    if (first == NULL) {
        return MYLITE_MISUSE;
    }
    rc = accumulate_staged_division_by_zero_warnings(
        database,
        first->division_by_zero_warning_count,
        &warning_count
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    output = atan2(approximate_numeric_input_to_double(first), 1.0);
    return finish_atan_function_value(database, output, function_name, warning_count, out_cell);
}

static int atan_two_argument_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    const struct approximate_numeric_input_value *first,
    const char *function_name,
    struct session_scalar_cell *out_cell
) {
    struct approximate_numeric_input_value second = {
        .is_null = false,
        .is_negative = false,
        .magnitude = 0U,
        .division_by_zero_warning_count = 0U,
    };
    size_t warning_count = 0U;
    double output = 0.0;
    int rc = MYLITE_OK;

    if (expression == NULL || first == NULL || out_cell == NULL) {
        return MYLITE_MISUSE;
    }

    rc = evaluate_approximate_numeric_operand(
        database,
        child_at(expression, 1U),
        &second,
        set_atan_unsupported_error
    );
    if (rc == MYLITE_OK) {
        rc = accumulate_staged_division_by_zero_warnings(
            database,
            first->division_by_zero_warning_count,
            &warning_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = accumulate_staged_division_by_zero_warnings(
            database,
            second.division_by_zero_warning_count,
            &warning_count
        );
    }
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (second.is_null) {
        out_cell->staged_division_by_zero_warning_count = warning_count;
        return MYLITE_OK;
    }

    output = atan2(
        approximate_numeric_input_to_double(first),
        approximate_numeric_input_to_double(&second)
    );
    return finish_atan_function_value(database, output, function_name, warning_count, out_cell);
}

static int finish_atan_function_value(
    struct mylite_db *database,
    double output,
    const char *function_name,
    size_t warning_count,
    struct session_scalar_cell *out_cell
) {
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    rc = format_double_text(
        database,
        output,
        function_name,
        out_cell->double_text,
        sizeof(out_cell->double_text)
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    out_cell->value = out_cell->double_text;
    out_cell->staged_division_by_zero_warning_count = warning_count;
    return MYLITE_OK;
}

static int exp_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct approximate_numeric_input_value value = {
        .is_null = false,
        .is_negative = false,
        .magnitude = 0U,
        .division_by_zero_warning_count = 0U,
    };
    double output = 0.0;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL || expression->kind != MYLITE_SQL_AST_EXP_FUNCTION ||
        mylite_sql_ast_node_child_count(expression) != 1U) {
        set_exp_log_power_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_approximate_numeric_operand(
        database,
        child_at(expression, 0U),
        &value,
        set_exp_log_power_unsupported_error
    );
    if (rc != MYLITE_OK || value.is_null) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    output = exp(approximate_numeric_input_to_double(&value));
    if (!isfinite(output)) {
        return set_double_out_of_range_error(database, "exp");
    }
    return finish_exp_log_power_function_value(
        database,
        output,
        "EXP",
        value.division_by_zero_warning_count,
        out_cell
    );
}

static int logarithm_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct approximate_numeric_input_value value = {
        .is_null = false,
        .is_negative = false,
        .magnitude = 0U,
        .division_by_zero_warning_count = 0U,
    };
    const char *function_name = NULL;
    double log_base = 0.0;
    size_t child_count = 0U;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL) {
        set_exp_log_power_unsupported_error(database);
        return MYLITE_ERROR;
    }
    child_count = mylite_sql_ast_node_child_count(expression);
    if (expression->kind == MYLITE_SQL_AST_LN_FUNCTION && child_count == 1U) {
        function_name = "LN";
        log_base = 0.0;
    } else if (
        expression->kind == MYLITE_SQL_AST_LOG_FUNCTION && (child_count == 1U || child_count == 2U)
    ) {
        function_name = "LOG";
        log_base = 0.0;
    } else if (expression->kind == MYLITE_SQL_AST_LOG10_FUNCTION && child_count == 1U) {
        function_name = "LOG10";
        log_base = logarithm_base_ten;
    } else if (expression->kind == MYLITE_SQL_AST_LOG2_FUNCTION && child_count == 1U) {
        function_name = "LOG2";
        log_base = logarithm_base_two;
    } else {
        set_exp_log_power_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_approximate_numeric_operand(
        database,
        child_at(expression, 0U),
        &value,
        set_exp_log_power_unsupported_error
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (child_count == 2U) {
        return two_argument_logarithm_function_value(database, expression, &value, out_cell);
    }
    return one_argument_logarithm_function_value(
        database,
        &value,
        function_name,
        log_base,
        out_cell
    );
}

static int one_argument_logarithm_function_value(
    struct mylite_db *database,
    const struct approximate_numeric_input_value *value,
    const char *function_name,
    double log_base,
    struct session_scalar_cell *out_cell
) {
    size_t division_warning_count = 0U;
    double input = 0.0;
    double output = 0.0;
    int rc = MYLITE_OK;

    if (value == NULL || function_name == NULL || out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    rc = accumulate_staged_warning_count(
        database,
        value->division_by_zero_warning_count,
        &division_warning_count
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (value->is_null) {
        out_cell->staged_division_by_zero_warning_count = division_warning_count;
        return MYLITE_OK;
    }

    input = approximate_numeric_input_to_double(value);
    if (input <= 0.0) {
        out_cell->staged_division_by_zero_warning_count = division_warning_count;
        out_cell->staged_invalid_logarithm_warning_count = 1U;
        return MYLITE_OK;
    }
    if (log_base == 0.0) {
        output = log(input);
    } else {
        output = log(input) / log(log_base);
    }
    return finish_exp_log_power_function_value(
        database,
        output,
        function_name,
        division_warning_count,
        out_cell
    );
}

static int two_argument_logarithm_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    const struct approximate_numeric_input_value *base,
    struct session_scalar_cell *out_cell
) {
    struct approximate_numeric_input_value value = {
        .is_null = false,
        .is_negative = false,
        .magnitude = 0U,
        .division_by_zero_warning_count = 0U,
    };
    size_t division_warning_count = 0U;
    double base_input = 0.0;
    double value_input = 0.0;
    double output = 0.0;
    int rc = MYLITE_OK;

    if (expression == NULL || base == NULL || out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    rc = accumulate_staged_warning_count(
        database,
        base->division_by_zero_warning_count,
        &division_warning_count
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (base->is_null) {
        out_cell->staged_division_by_zero_warning_count = division_warning_count;
        return MYLITE_OK;
    }

    base_input = approximate_numeric_input_to_double(base);
    if (base_input <= 0.0 || base_input == 1.0) {
        out_cell->staged_division_by_zero_warning_count = division_warning_count;
        out_cell->staged_invalid_logarithm_warning_count = 1U;
        return MYLITE_OK;
    }

    rc = evaluate_approximate_numeric_operand(
        database,
        child_at(expression, 1U),
        &value,
        set_exp_log_power_unsupported_error
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = accumulate_staged_warning_count(
        database,
        value.division_by_zero_warning_count,
        &division_warning_count
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (value.is_null) {
        out_cell->staged_division_by_zero_warning_count = division_warning_count;
        return MYLITE_OK;
    }

    value_input = approximate_numeric_input_to_double(&value);
    if (value_input <= 0.0) {
        out_cell->staged_division_by_zero_warning_count = division_warning_count;
        out_cell->staged_invalid_logarithm_warning_count = 1U;
        return MYLITE_OK;
    }

    output = log(value_input) / log(base_input);
    return finish_exp_log_power_function_value(
        database,
        output,
        "LOG",
        division_warning_count,
        out_cell
    );
}

static int power_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct approximate_numeric_input_value value = {
        .is_null = false,
        .is_negative = false,
        .magnitude = 0U,
        .division_by_zero_warning_count = 0U,
    };
    struct approximate_numeric_input_value exponent = {
        .is_null = false,
        .is_negative = false,
        .magnitude = 0U,
        .division_by_zero_warning_count = 0U,
    };
    const char *function_name = NULL;
    size_t division_warning_count = 0U;
    double output = 0.0;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL ||
        (expression->kind != MYLITE_SQL_AST_POW_FUNCTION &&
         expression->kind != MYLITE_SQL_AST_POWER_FUNCTION) ||
        mylite_sql_ast_node_child_count(expression) != 2U) {
        set_exp_log_power_unsupported_error(database);
        return MYLITE_ERROR;
    }

    function_name = expression->kind == MYLITE_SQL_AST_POW_FUNCTION ? "POW" : "POWER";
    rc = evaluate_approximate_numeric_operand(
        database,
        child_at(expression, 0U),
        &value,
        set_exp_log_power_unsupported_error
    );
    if (rc == MYLITE_OK) {
        rc = evaluate_approximate_numeric_operand(
            database,
            child_at(expression, 1U),
            &exponent,
            set_exp_log_power_unsupported_error
        );
    }
    if (rc == MYLITE_OK) {
        rc = accumulate_staged_warning_count(
            database,
            value.division_by_zero_warning_count,
            &division_warning_count
        );
    }
    if (rc == MYLITE_OK) {
        rc = accumulate_staged_warning_count(
            database,
            exponent.division_by_zero_warning_count,
            &division_warning_count
        );
    }
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (value.is_null || exponent.is_null) {
        out_cell->staged_division_by_zero_warning_count = division_warning_count;
        return MYLITE_OK;
    }

    output =
        pow(approximate_numeric_input_to_double(&value),
            approximate_numeric_input_to_double(&exponent));
    if (!isfinite(output)) {
        return set_double_out_of_range_error(database, function_name);
    }
    return finish_exp_log_power_function_value(
        database,
        output,
        function_name,
        division_warning_count,
        out_cell
    );
}

static int finish_exp_log_power_function_value(
    struct mylite_db *database,
    double output,
    const char *function_name,
    size_t division_warning_count,
    struct session_scalar_cell *out_cell
) {
    int rc = MYLITE_OK;

    if (out_cell == NULL || function_name == NULL) {
        return MYLITE_MISUSE;
    }
    rc = format_double_text(
        database,
        output,
        function_name,
        out_cell->double_text,
        sizeof(out_cell->double_text)
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    out_cell->value = out_cell->double_text;
    out_cell->staged_division_by_zero_warning_count = division_warning_count;
    return MYLITE_OK;
}

static int set_double_out_of_range_error(struct mylite_db *database, const char *function_name) {
    char message[MYLITE_DIAGNOSTIC_MESSAGE_CAPACITY];
    int written = snprintf(
        message,
        sizeof(message),
        "DOUBLE value is out of range in '%s()'",
        function_name == NULL ? "math" : function_name
    );

    if (written < 0 || (size_t)written >= sizeof(message)) {
        set_runtime_error(database, "DOUBLE value is out of range");
        return MYLITE_ERROR;
    }

    mylite_diagnostics_set_error(
        mylite_connection_diagnostics(database),
        mysql_error_bigint_out_of_range,
        "22003",
        message
    );
    return MYLITE_ERROR;
}

static double approximate_numeric_input_to_double(
    const struct approximate_numeric_input_value *value
) {
    double input = 0.0;

    if (value == NULL) {
        return 0.0;
    }

    input = (double)value->magnitude;
    if (value->is_negative) {
        input = -input;
    }
    return input;
}

static int evaluate_approximate_numeric_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct approximate_numeric_input_value *out_value,
    void (*set_unsupported_error)(struct mylite_db *)
) {
    struct scalar_arithmetic_value arithmetic = {.is_null = false, .integer = 0};
    bool handled = false;
    int rc = MYLITE_OK;

    if (out_value == NULL || set_unsupported_error == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct approximate_numeric_input_value){.is_null = false, .is_negative = false};
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_approximate_numeric_direct_value_operand(
        database,
        expression,
        out_value,
        set_unsupported_error,
        &handled
    );
    if (rc != MYLITE_OK || handled) {
        return rc;
    }
    if (is_scalar_bitwise_projection_expression(expression)) {
        struct scalar_bitwise_value bitwise = {.is_null = false, .integer = 0U};

        rc = evaluate_scalar_bitwise_expression(database, expression, &bitwise);
        if (rc != MYLITE_OK) {
            return rc;
        }
        out_value->is_null = bitwise.is_null;
        out_value->magnitude = bitwise.integer;
        out_value->division_by_zero_warning_count = bitwise.division_by_zero_warning_count;
        return MYLITE_OK;
    }
    if (!is_scalar_arithmetic_projection_expression(expression)) {
        set_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_scalar_arithmetic_expression(database, expression, &arithmetic);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_value->is_null = arithmetic.is_null;
    out_value->division_by_zero_warning_count = arithmetic.division_by_zero_warning_count;
    if (arithmetic.is_null) {
        return MYLITE_OK;
    }
    if (arithmetic.integer < 0) {
        out_value->is_negative = true;
        out_value->magnitude = arithmetic.integer == INT64_MIN ? ((uint64_t)INT64_MAX + 1U)
                                                               : (uint64_t)(-arithmetic.integer);
    } else {
        out_value->magnitude = (uint64_t)arithmetic.integer;
    }
    return MYLITE_OK;
}

static int evaluate_approximate_numeric_direct_value_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct approximate_numeric_input_value *out_value,
    void (*set_unsupported_error)(struct mylite_db *),
    bool *out_handled
) {
    const struct mylite_sql_ast_node *literal = expression;
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    bool is_negative = false;
    bool has_sign = false;
    uint64_t magnitude = 0U;

    if (out_value == NULL || set_unsupported_error == NULL || out_handled == NULL) {
        return MYLITE_MISUSE;
    }
    *out_handled = false;
    if (expression == NULL) {
        return MYLITE_OK;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

        if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
            operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            return MYLITE_OK;
        }
        literal = unwrap_parenthesized_expression(child_at(expression, 0U));
        if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
            mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER) {
            return MYLITE_OK;
        }
        has_sign = true;
        is_negative = operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE;
    }
    if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL) {
        return MYLITE_OK;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(literal);
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
        out_value->is_null = true;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_TRUE) {
        out_value->magnitude = 1U;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_FALSE) {
        out_value->magnitude = 0U;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (literal_kind != MYLITE_SQL_AST_LITERAL_INTEGER) {
        return MYLITE_OK;
    }
    *out_handled = true;

    if (parse_unsigned_integer_literal(&literal->span, &magnitude) != MYLITE_OK) {
        set_unsupported_error(database);
        return MYLITE_ERROR;
    }
    out_value->is_negative = false;
    if (is_negative && magnitude != 0U) {
        out_value->is_negative = true;
    }
    out_value->magnitude = magnitude;
    return MYLITE_OK;
}

static int format_double_text(
    struct mylite_db *database,
    double value,
    const char *function_name,
    char *buffer,
    size_t buffer_size
) {
    if (function_name == NULL || buffer == NULL || buffer_size == 0U) {
        return MYLITE_MISUSE;
    }

    if (should_format_scientific_integer_double(value)) {
        return format_scientific_double_text(database, value, function_name, buffer, buffer_size);
    }

    for (int precision = 1; precision <= double_text_max_significant_digits; ++precision) {
        char candidate[double_text_capacity];
        char *end = NULL;
        double parsed = 0.0;
        int written = format_c_locale_text(candidate, sizeof(candidate), "%.*g", precision, value);

        if (written < 0 || (size_t)written >= sizeof(candidate)) {
            set_double_format_error(database, function_name);
            return MYLITE_ERROR;
        }
        if (parse_c_locale_double(candidate, &end, &parsed) == MYLITE_OK && end != candidate &&
            end != NULL && *end == '\0' && parsed == value) {
            return copy_normalized_double_text(
                database,
                candidate,
                function_name,
                buffer,
                buffer_size
            );
        }
    }

    set_double_format_error(database, function_name);
    return MYLITE_ERROR;
}

static bool should_format_scientific_integer_double(double value) {
    double magnitude = fabs(value);

    if (magnitude < double_scientific_integer_threshold) {
        return false;
    }
    return trunc(value) == value;
}

static int format_scientific_double_text(
    struct mylite_db *database,
    double value,
    const char *function_name,
    char *buffer,
    size_t buffer_size
) {
    if (function_name == NULL || buffer == NULL || buffer_size == 0U) {
        return MYLITE_MISUSE;
    }

    for (int precision = 0; precision < double_text_max_significant_digits; ++precision) {
        char candidate[double_text_capacity];
        char *end = NULL;
        double parsed = 0.0;
        int written = format_c_locale_text(candidate, sizeof(candidate), "%.*e", precision, value);

        if (written < 0 || (size_t)written >= sizeof(candidate)) {
            set_double_format_error(database, function_name);
            return MYLITE_ERROR;
        }
        if (parse_c_locale_double(candidate, &end, &parsed) == MYLITE_OK && end != candidate &&
            end != NULL && *end == '\0' && parsed == value) {
            return copy_normalized_scientific_double_text(
                database,
                candidate,
                function_name,
                buffer,
                buffer_size
            );
        }
    }

    set_double_format_error(database, function_name);
    return MYLITE_ERROR;
}

static int format_c_locale_text(char *buffer, size_t buffer_size, const char *format, ...) {
    va_list arguments;
    int written = 0;

    if (buffer == NULL || buffer_size == 0U || format == NULL) {
        return -1;
    }

    va_start(arguments, format);
#ifdef _WIN32
    _locale_t c_locale = _create_locale(LC_NUMERIC, "C");

    if (c_locale == NULL) {
        va_end(arguments);
        return -1;
    }
    written = _vsnprintf_l(buffer, buffer_size, format, c_locale, arguments);
    _free_locale(c_locale);
#else
    locale_t c_locale = newlocale(LC_NUMERIC_MASK, "C", (locale_t)0);
    locale_t previous_locale = (locale_t)0;

    if (c_locale == (locale_t)0) {
        va_end(arguments);
        return -1;
    }
    previous_locale = uselocale(c_locale);
    if (previous_locale == (locale_t)0) {
        freelocale(c_locale);
        va_end(arguments);
        return -1;
    }
    written = vsnprintf(buffer, buffer_size, format, arguments);
    if (uselocale(previous_locale) == (locale_t)0) {
        written = -1;
    }
    freelocale(c_locale);
#endif
    va_end(arguments);
    return written;
}

static int parse_c_locale_double(const char *text, char **out_end, double *out_value) {
    if (text == NULL || out_end == NULL || out_value == NULL) {
        return MYLITE_MISUSE;
    }

#ifdef _WIN32
    _locale_t c_locale = _create_locale(LC_NUMERIC, "C");

    if (c_locale == NULL) {
        return MYLITE_ERROR;
    }
    *out_value = _strtod_l(text, out_end, c_locale);
    _free_locale(c_locale);
#else
    locale_t c_locale = newlocale(LC_NUMERIC_MASK, "C", (locale_t)0);
    locale_t previous_locale = (locale_t)0;
    int rc = MYLITE_OK;

    if (c_locale == (locale_t)0) {
        return MYLITE_ERROR;
    }
    previous_locale = uselocale(c_locale);
    if (previous_locale == (locale_t)0) {
        freelocale(c_locale);
        return MYLITE_ERROR;
    }
    *out_value = strtod(text, out_end);
    if (uselocale(previous_locale) == (locale_t)0) {
        rc = MYLITE_ERROR;
    }
    freelocale(c_locale);
    if (rc != MYLITE_OK) {
        return rc;
    }
#endif

    return MYLITE_OK;
}

static int copy_normalized_double_text(
    struct mylite_db *database,
    const char *candidate,
    const char *function_name,
    char *buffer,
    size_t buffer_size
) {
    size_t write_index = 0U;

    if (candidate == NULL || function_name == NULL || buffer == NULL || buffer_size == 0U) {
        return MYLITE_MISUSE;
    }
    for (size_t read_index = 0U; candidate[read_index] != '\0'; ++read_index) {
        if (write_index + 1U >= buffer_size) {
            set_double_format_error(database, function_name);
            return MYLITE_ERROR;
        }
        buffer[write_index] = candidate[read_index];
        ++write_index;
        if ((candidate[read_index] == 'e' || candidate[read_index] == 'E') &&
            candidate[read_index + 1U] == '+') {
            ++read_index;
        }
    }
    buffer[write_index] = '\0';
    return MYLITE_OK;
}

static int copy_normalized_scientific_double_text(
    struct mylite_db *database,
    const char *candidate,
    const char *function_name,
    char *buffer,
    size_t buffer_size
) {
    const char *exponent = NULL;
    size_t mantissa_end = 0U;
    size_t write_index = 0U;
    size_t exponent_index = 0U;

    if (candidate == NULL || function_name == NULL || buffer == NULL || buffer_size == 0U) {
        return MYLITE_MISUSE;
    }
    exponent = strchr(candidate, 'e');
    if (exponent == NULL) {
        exponent = strchr(candidate, 'E');
    }
    if (exponent == NULL) {
        set_double_format_error(database, function_name);
        return MYLITE_ERROR;
    }

    mantissa_end = (size_t)(exponent - candidate);
    while (mantissa_end > 0U && candidate[mantissa_end - 1U] == '0') {
        --mantissa_end;
    }
    if (mantissa_end > 0U && candidate[mantissa_end - 1U] == '.') {
        --mantissa_end;
    }
    for (size_t read_index = 0U; read_index < mantissa_end; ++read_index) {
        if (write_index + 1U >= buffer_size) {
            set_double_format_error(database, function_name);
            return MYLITE_ERROR;
        }
        buffer[write_index] = candidate[read_index];
        ++write_index;
    }

    if (write_index + 1U >= buffer_size) {
        set_double_format_error(database, function_name);
        return MYLITE_ERROR;
    }
    buffer[write_index] = 'e';
    ++write_index;

    exponent_index = (size_t)(exponent - candidate) + 1U;
    if (candidate[exponent_index] == '+') {
        ++exponent_index;
    } else if (candidate[exponent_index] == '-') {
        if (write_index + 1U >= buffer_size) {
            set_double_format_error(database, function_name);
            return MYLITE_ERROR;
        }
        buffer[write_index] = '-';
        ++write_index;
        ++exponent_index;
    }
    while (candidate[exponent_index] == '0' && candidate[exponent_index + 1U] != '\0') {
        ++exponent_index;
    }
    while (candidate[exponent_index] != '\0') {
        if (write_index + 1U >= buffer_size) {
            set_double_format_error(database, function_name);
            return MYLITE_ERROR;
        }
        buffer[write_index] = candidate[exponent_index];
        ++write_index;
        ++exponent_index;
    }
    buffer[write_index] = '\0';
    return MYLITE_OK;
}

static void set_double_format_error(struct mylite_db *database, const char *function_name) {
    char message[double_format_error_capacity];
    int written = snprintf(
        message,
        sizeof(message),
        "failed to format %s() value",
        function_name == NULL ? "scalar double" : function_name
    );

    if (written < 0 || (size_t)written >= sizeof(message)) {
        set_runtime_error(database, "failed to format scalar double value");
        return;
    }
    set_runtime_error(database, message);
}

static int base_conversion_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct scalar_bitwise_value value = {.is_null = false, .integer = 0U};
    unsigned int base = 0U;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL || mylite_sql_ast_node_child_count(expression) != 1U) {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (expression->kind == MYLITE_SQL_AST_BIN_FUNCTION) {
        base = base_conversion_binary_base;
    } else if (expression->kind == MYLITE_SQL_AST_OCT_FUNCTION) {
        base = base_conversion_octal_base;
    } else {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_base_conversion_operand(database, child_at(expression, 0U), &value);
    if (rc != MYLITE_OK || value.is_null) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    rc = format_base_conversion_value(
        database,
        value.integer,
        base,
        out_cell->base_conversion_text,
        sizeof(out_cell->base_conversion_text)
    );
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->base_conversion_text;
        out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
    }
    return rc;
}

static int conv_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct conv_arguments arguments;
    struct conv_output_format output = {0};
    uint64_t converted = 0U;
    unsigned int input_base = 0U;
    unsigned int output_base = 0U;
    bool is_null = false;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL || expression->kind != MYLITE_SQL_AST_CONV_FUNCTION ||
        mylite_sql_ast_node_child_count(expression) != 3U) {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_conv_arguments(database, expression, out_cell, &arguments, &is_null);
    if (rc != MYLITE_OK || is_null) {
        return rc;
    }

    input_base = absolute_conv_base(arguments.from_base.integer);
    output_base = absolute_conv_base(arguments.to_base.integer);
    if (input_base < base_conversion_binary_base || input_base > base_conversion_max_base ||
        output_base < base_conversion_binary_base || output_base > base_conversion_max_base) {
        return MYLITE_OK;
    }

    rc = convert_conv_value(
        database,
        &arguments.input,
        input_base,
        arguments.from_base.integer < 0,
        out_cell,
        &converted
    );
    if (rc == MYLITE_OK) {
        output.value = converted;
        output.base = output_base;
        output.signed_output = arguments.to_base.integer < 0;
        rc = format_conv_output_value(
            database,
            output,
            out_cell->base_conversion_text,
            sizeof(out_cell->base_conversion_text)
        );
    }
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->base_conversion_text;
    }
    return rc;
}

static int evaluate_conv_arguments(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *cell,
    struct conv_arguments *out_arguments,
    bool *out_is_null
) {
    int rc = MYLITE_OK;

    if (expression == NULL || cell == NULL || out_arguments == NULL || out_is_null == NULL) {
        return MYLITE_MISUSE;
    }
    out_arguments->input = (struct conv_input_value){
        .is_null = false,
        .is_negative = false,
        .magnitude = 0U,
        .division_by_zero_warning_count = 0U,
    };
    out_arguments->from_base = (struct scalar_arithmetic_value){
        .is_null = false,
        .integer = 0,
        .division_by_zero_warning_count = 0U,
    };
    out_arguments->to_base = (struct scalar_arithmetic_value){
        .is_null = false,
        .integer = 0,
        .division_by_zero_warning_count = 0U,
    };
    *out_is_null = false;

    rc = evaluate_conv_value_operand(database, child_at(expression, 0U), &out_arguments->input);
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (out_arguments->input.is_null) {
        rc = set_conv_staged_division_by_zero_count(database, out_arguments, false, false, cell);
        *out_is_null = true;
        return rc;
    }

    rc = evaluate_conv_base_operand(database, child_at(expression, 1U), &out_arguments->from_base);
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (out_arguments->from_base.is_null) {
        rc = set_conv_staged_division_by_zero_count(database, out_arguments, true, false, cell);
        *out_is_null = true;
        return rc;
    }

    rc = evaluate_conv_base_operand(database, child_at(expression, 2U), &out_arguments->to_base);
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (out_arguments->to_base.is_null) {
        rc = set_conv_staged_division_by_zero_count(database, out_arguments, true, true, cell);
        *out_is_null = true;
        return rc;
    }

    return set_conv_staged_division_by_zero_count(database, out_arguments, true, true, cell);
}

static int set_conv_staged_division_by_zero_count(
    struct mylite_db *database,
    const struct conv_arguments *arguments,
    bool include_from_base,
    bool include_to_base,
    struct session_scalar_cell *cell
) {
    size_t warning_count = 0U;
    int rc = MYLITE_OK;

    if (arguments == NULL || cell == NULL) {
        return MYLITE_MISUSE;
    }

    rc = accumulate_staged_division_by_zero_warnings(
        database,
        arguments->input.division_by_zero_warning_count,
        &warning_count
    );
    if (rc == MYLITE_OK && include_from_base) {
        rc = accumulate_staged_division_by_zero_warnings(
            database,
            arguments->from_base.division_by_zero_warning_count,
            &warning_count
        );
    }
    if (rc == MYLITE_OK && include_to_base) {
        rc = accumulate_staged_division_by_zero_warnings(
            database,
            arguments->to_base.division_by_zero_warning_count,
            &warning_count
        );
    }
    if (rc == MYLITE_OK) {
        cell->staged_division_by_zero_warning_count = warning_count;
    }
    return rc;
}

static unsigned int absolute_conv_base(int64_t base) {
    if (base == INT64_MIN) {
        return base_conversion_max_base + 1U;
    }
    if (base < 0) {
        return (unsigned int)(-base);
    }
    return (unsigned int)base;
}

static int evaluate_conv_value_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct conv_input_value *out_value
) {
    struct scalar_arithmetic_value arithmetic = {.is_null = false, .integer = 0};
    bool handled = false;
    int rc = MYLITE_OK;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct conv_input_value){.is_null = false, .is_negative = false, .magnitude = 0U};
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_conv_direct_value_operand(database, expression, out_value, &handled);
    if (rc != MYLITE_OK || handled) {
        return rc;
    }
    if (is_scalar_bitwise_projection_expression(expression)) {
        struct scalar_bitwise_value bitwise = {.is_null = false, .integer = 0U};

        rc = evaluate_scalar_bitwise_expression(database, expression, &bitwise);
        if (rc != MYLITE_OK) {
            return rc;
        }
        out_value->is_null = bitwise.is_null;
        out_value->magnitude = bitwise.integer;
        out_value->division_by_zero_warning_count = bitwise.division_by_zero_warning_count;
        return MYLITE_OK;
    }
    if (!is_scalar_arithmetic_projection_expression(expression)) {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_scalar_arithmetic_expression(database, expression, &arithmetic);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_value->is_null = arithmetic.is_null;
    out_value->division_by_zero_warning_count = arithmetic.division_by_zero_warning_count;
    if (arithmetic.is_null) {
        return MYLITE_OK;
    }
    if (arithmetic.integer < 0) {
        out_value->is_negative = true;
        out_value->magnitude = arithmetic.integer == INT64_MIN ? ((uint64_t)INT64_MAX + 1U)
                                                               : (uint64_t)(-arithmetic.integer);
    } else {
        out_value->magnitude = (uint64_t)arithmetic.integer;
    }
    return MYLITE_OK;
}

static int evaluate_conv_direct_value_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct conv_input_value *out_value,
    bool *out_handled
) {
    static const uint64_t int64_min_magnitude = 9223372036854775808ULL;
    const struct mylite_sql_ast_node *literal = expression;
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    bool is_negative = false;
    bool has_sign = false;
    uint64_t magnitude = 0U;

    if (out_value == NULL || out_handled == NULL) {
        return MYLITE_MISUSE;
    }
    *out_handled = false;
    if (expression == NULL) {
        return MYLITE_OK;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

        if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
            operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            return MYLITE_OK;
        }
        literal = unwrap_parenthesized_expression(child_at(expression, 0U));
        if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
            mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER) {
            return MYLITE_OK;
        }
        has_sign = true;
        is_negative = operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE;
    }
    if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL) {
        return MYLITE_OK;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(literal);
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
        out_value->is_null = true;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_TRUE) {
        out_value->magnitude = 1U;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_FALSE) {
        out_value->magnitude = 0U;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (literal_kind != MYLITE_SQL_AST_LITERAL_INTEGER) {
        return MYLITE_OK;
    }
    *out_handled = true;

    if (parse_unsigned_integer_literal(&literal->span, &magnitude) != MYLITE_OK) {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (is_negative && magnitude > int64_min_magnitude) {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }
    out_value->is_negative = false;
    if (is_negative && magnitude != 0U) {
        out_value->is_negative = true;
    }
    out_value->magnitude = magnitude;
    return MYLITE_OK;
}

static int evaluate_conv_base_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_arithmetic_value *out_value
) {
    expression = unwrap_parenthesized_expression(expression);
    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct scalar_arithmetic_value){.is_null = false, .integer = 0};
    if (expression == NULL || !is_scalar_arithmetic_projection_expression(expression)) {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }
    return evaluate_scalar_arithmetic_expression(database, expression, out_value);
}

static int convert_conv_value(
    struct mylite_db *database,
    const struct conv_input_value *input,
    unsigned int from_base,
    bool signed_input,
    struct session_scalar_cell *cell,
    uint64_t *out_value
) {
    uint64_t limit = UINT64_MAX;
    struct conv_digit_parse parse = {0};
    char input_text[integer_text_capacity];
    int rc = MYLITE_OK;

    if (input == NULL || cell == NULL || out_value == NULL) {
        return MYLITE_MISUSE;
    }
    if (signed_input) {
        limit = (uint64_t)INT64_MAX;
        if (input->is_negative) {
            limit = (uint64_t)INT64_MAX + 1U;
        }
    }
    rc = format_conv_input_text(database, input, input_text, sizeof(input_text));
    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = parse_conv_input_digits(input_text, from_base, limit, &parse);
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (!parse.saw_digit || parse.overflowed) {
        rc = stage_conv_truncated_decimal_warning(database, input_text, cell);
        if (rc != MYLITE_OK) {
            return rc;
        }
    }
    if (!parse.saw_digit) {
        *out_value = 0U;
    } else if (input->is_negative) {
        *out_value = 0U - parse.value;
    } else {
        *out_value = parse.value;
    }
    return MYLITE_OK;
}

static int parse_conv_input_digits(
    const char *input_text,
    unsigned int from_base,
    uint64_t limit,
    struct conv_digit_parse *out_parse
) {
    struct conv_digit_parse parse = {0};
    size_t offset = 0U;

    if (input_text == NULL || out_parse == NULL) {
        return MYLITE_MISUSE;
    }
    if (input_text[offset] == '-') {
        ++offset;
    }
    while (input_text[offset] != '\0') {
        unsigned char byte = (unsigned char)input_text[offset];
        uint64_t digit = 0U;

        if (byte < '0' || byte > '9') {
            break;
        }
        digit = (uint64_t)(byte - '0');
        if (digit >= (uint64_t)from_base) {
            break;
        }
        parse.saw_digit = true;
        if (!parse.overflowed) {
            if (parse.value > (limit - digit) / (uint64_t)from_base) {
                parse.value = limit;
                parse.overflowed = true;
            } else {
                parse.value = (parse.value * (uint64_t)from_base) + digit;
            }
        }
        ++offset;
    }
    *out_parse = parse;
    return MYLITE_OK;
}

static int format_conv_input_text(
    struct mylite_db *database,
    const struct conv_input_value *input,
    char *buffer,
    size_t buffer_size
) {
    int written = 0;

    if (input == NULL || buffer == NULL || buffer_size == 0U) {
        return MYLITE_MISUSE;
    }
    if (!input->is_negative) {
        return format_uint64(database, input->magnitude, buffer, buffer_size);
    }
    written = snprintf(buffer, buffer_size, "-%" PRIu64, input->magnitude);
    if (written < 0 || (size_t)written >= buffer_size) {
        set_runtime_error(database, "failed to format CONV() input value");
        return MYLITE_ERROR;
    }
    return MYLITE_OK;
}

static int stage_conv_truncated_decimal_warning(
    struct mylite_db *database,
    const char *input_text,
    struct session_scalar_cell *cell
) {
    int written = 0;

    if (input_text == NULL || cell == NULL) {
        return MYLITE_MISUSE;
    }
    written = snprintf(
        cell->staged_truncated_decimal_text,
        sizeof(cell->staged_truncated_decimal_text),
        "%s",
        input_text
    );
    if (written < 0 || (size_t)written >= sizeof(cell->staged_truncated_decimal_text)) {
        set_runtime_error(database, "failed to stage CONV() warning");
        return MYLITE_ERROR;
    }
    cell->has_staged_truncated_decimal_warning = true;
    return MYLITE_OK;
}

static int format_conv_output_value(
    struct mylite_db *database,
    struct conv_output_format format,
    char *buffer,
    size_t buffer_size
) {
    uint64_t magnitude = format.value;
    bool is_negative = false;
    int rc = MYLITE_OK;

    if (buffer == NULL || buffer_size == 0U || format.base < base_conversion_binary_base ||
        format.base > base_conversion_max_base) {
        set_runtime_error(database, "failed to format CONV() value");
        return MYLITE_ERROR;
    }
    if (format.signed_output && format.value > (uint64_t)INT64_MAX) {
        is_negative = true;
        magnitude = 0U - format.value;
    }
    if (is_negative) {
        if (buffer_size < 2U) {
            set_runtime_error(database, "failed to format CONV() value");
            return MYLITE_ERROR;
        }
        buffer[0] = '-';
        rc = format_base_conversion_value(
            database,
            magnitude,
            format.base,
            buffer + 1U,
            buffer_size - 1U
        );
    } else {
        rc = format_base_conversion_value(database, magnitude, format.base, buffer, buffer_size);
    }
    return rc;
}

static int format_base_conversion_value(
    struct mylite_db *database,
    uint64_t value,
    unsigned int base,
    char *buffer,
    size_t buffer_size
) {
    char reversed[base_conversion_text_capacity];
    size_t digit_count = 0U;

    if (buffer == NULL || buffer_size == 0U || base < base_conversion_binary_base ||
        base > base_conversion_max_base) {
        set_runtime_error(database, "failed to format base conversion value");
        return MYLITE_ERROR;
    }
    if (value == 0U) {
        if (buffer_size < 2U) {
            set_runtime_error(database, "failed to format base conversion value");
            return MYLITE_ERROR;
        }
        buffer[0] = '0';
        buffer[1] = '\0';
        return MYLITE_OK;
    }

    while (value != 0U) {
        unsigned int digit = (unsigned int)(value % base);

        if (digit_count == sizeof(reversed)) {
            set_runtime_error(database, "failed to format base conversion value");
            return MYLITE_ERROR;
        }
        reversed[digit_count] = digit < (unsigned int)decimal_base
                                    ? (char)('0' + digit)
                                    : (char)('A' + digit - (unsigned int)decimal_base);
        ++digit_count;
        value /= base;
    }
    if (digit_count >= buffer_size) {
        set_runtime_error(database, "failed to format base conversion value");
        return MYLITE_ERROR;
    }
    for (size_t index = 0U; index < digit_count; ++index) {
        buffer[index] = reversed[digit_count - index - 1U];
    }
    buffer[digit_count] = '\0';
    return MYLITE_OK;
}

static int evaluate_base_conversion_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_bitwise_value *out_value
) {
    struct scalar_arithmetic_value arithmetic = {.is_null = false, .integer = 0};
    bool handled = false;
    int rc = MYLITE_OK;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct scalar_bitwise_value){.is_null = false, .integer = 0U};
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_base_conversion_direct_literal_operand(database, expression, out_value, &handled);
    if (rc != MYLITE_OK || handled) {
        return rc;
    }
    if (is_scalar_bitwise_projection_expression(expression)) {
        return evaluate_scalar_bitwise_expression(database, expression, out_value);
    }
    if (!is_scalar_arithmetic_projection_expression(expression)) {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_scalar_arithmetic_expression(database, expression, &arithmetic);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_value->is_null = arithmetic.is_null;
    out_value->integer = (uint64_t)arithmetic.integer;
    out_value->division_by_zero_warning_count = arithmetic.division_by_zero_warning_count;
    return MYLITE_OK;
}

static int evaluate_base_conversion_direct_literal_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_bitwise_value *out_value,
    bool *out_handled
) {
    static const uint64_t int64_min_magnitude = 9223372036854775808ULL;
    const struct mylite_sql_ast_node *literal = expression;
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    bool is_negative = false;
    bool has_sign = false;
    uint64_t magnitude = 0U;

    if (out_value == NULL || out_handled == NULL) {
        return MYLITE_MISUSE;
    }
    *out_handled = false;
    if (expression == NULL) {
        return MYLITE_OK;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

        if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
            operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            return MYLITE_OK;
        }
        literal = unwrap_parenthesized_expression(child_at(expression, 0U));
        if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
            mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER) {
            return MYLITE_OK;
        }
        has_sign = true;
        is_negative = operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE;
    }
    if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL) {
        return MYLITE_OK;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(literal);
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
        out_value->is_null = true;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_TRUE) {
        out_value->integer = 1U;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_FALSE) {
        out_value->integer = 0U;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (literal_kind != MYLITE_SQL_AST_LITERAL_INTEGER) {
        return MYLITE_OK;
    }
    *out_handled = true;

    if (parse_unsigned_integer_literal(&literal->span, &magnitude) != MYLITE_OK) {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (!is_negative) {
        out_value->integer = magnitude;
        return MYLITE_OK;
    }
    if (magnitude > int64_min_magnitude) {
        set_base_conversion_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (magnitude == int64_min_magnitude) {
        out_value->integer = (uint64_t)INT64_MIN;
    } else if (magnitude != 0U) {
        out_value->integer = (uint64_t)(-(int64_t)magnitude);
    }
    return MYLITE_OK;
}

static int bit_count_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct scalar_bitwise_value value = {.is_null = false, .integer = 0U};
    uint64_t bit_count = 0U;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (expression == NULL || mylite_sql_ast_node_child_count(expression) != 1U) {
        set_bit_count_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_bit_count_operand(database, child_at(expression, 0U), &value);
    if (rc != MYLITE_OK || value.is_null) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    bit_count = count_uint64_bits(value.integer);
    rc = format_uint64(database, bit_count, out_cell->integer_text, sizeof(out_cell->integer_text));
    if (rc == MYLITE_OK) {
        out_cell->value = out_cell->integer_text;
        out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
    }
    return rc;
}

static int cast_binary_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};

    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL || expression->kind != MYLITE_SQL_AST_CAST_BINARY_EXPRESSION ||
        mylite_sql_ast_node_child_count(expression) != 1U) {
        set_unsupported_error(database, "CAST AS BINARY supports only bare BINARY casts");
        return MYLITE_ERROR;
    }

    return cast_binary_input_value(database, child_at(expression, 0U), out_cell);
}

static int cast_binary_input_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    const struct mylite_sql_ast_node *literal = expression;
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    bool is_negative = false;
    bool has_sign = false;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_unsupported_error(
            database,
            "CAST AS BINARY supports only string, integer, boolean, and NULL values"
        );
        return MYLITE_ERROR;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

        has_sign = true;
        if (operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            is_negative = true;
        } else if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE) {
            set_unsupported_error(database, "CAST AS BINARY supports only signed integer values");
            return MYLITE_ERROR;
        }
        literal = unwrap_parenthesized_expression(child_at(expression, 0U));
    }
    if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL) {
        set_unsupported_error(
            database,
            "CAST AS BINARY supports only string, integer, boolean, and NULL values"
        );
        return MYLITE_ERROR;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(literal);
    if (has_sign && literal_kind != MYLITE_SQL_AST_LITERAL_INTEGER) {
        set_unsupported_error(database, "CAST AS BINARY supports only signed integer values");
        return MYLITE_ERROR;
    }
    switch (literal_kind) {
    case MYLITE_SQL_AST_LITERAL_STRING: {
        size_t text_length = 0U;
        int rc = decode_sql_string_literal(
            database,
            literal,
            "CAST AS BINARY supports only string literals",
            "CAST AS BINARY does not support embedded NUL bytes",
            &out_cell->owned_text,
            &text_length
        );
        (void)text_length;
        if (rc == MYLITE_OK) {
            out_cell->value = out_cell->owned_text;
        }
        return rc;
    }
    case MYLITE_SQL_AST_LITERAL_INTEGER: {
        int rc = normalize_decimal_integer_literal(
            database,
            &literal->span,
            is_negative,
            out_cell->literal_text,
            sizeof(out_cell->literal_text)
        );

        if (rc == MYLITE_OK) {
            out_cell->value = out_cell->literal_text;
        }
        return rc;
    }
    case MYLITE_SQL_AST_LITERAL_TRUE:
        out_cell->value = "1";
        return MYLITE_OK;
    case MYLITE_SQL_AST_LITERAL_FALSE:
        out_cell->value = "0";
        return MYLITE_OK;
    case MYLITE_SQL_AST_LITERAL_NULL:
        out_cell->value = NULL;
        return MYLITE_OK;
    default:
        break;
    }

    set_unsupported_error(
        database,
        "CAST AS BINARY supports only string, integer, boolean, and NULL values"
    );
    return MYLITE_ERROR;
}

static int date_format_function_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    char *value = NULL;
    char *format = NULL;
    size_t value_length = 0U;
    size_t format_length = 0U;
    bool value_is_null = false;
    bool format_is_null = false;
    bool result_is_null = false;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};

    rc = date_format_function_arguments(
        database,
        expression,
        &value,
        &value_length,
        &value_is_null,
        &format,
        &format_length,
        &format_is_null
    );
    if (rc == MYLITE_OK && !value_is_null && !format_is_null) {
        rc = mylite_date_format_value(
            database,
            value,
            value_length,
            MYLITE_DATE_FORMAT_INPUT_STRING,
            format,
            format_length,
            &out_cell->owned_text,
            &result_is_null
        );
    } else {
        result_is_null = true;
    }
    if (rc == MYLITE_OK && !result_is_null) {
        out_cell->value = out_cell->owned_text;
    }
    free(value);
    free(format);
    return rc;
}

static int date_format_function_arguments(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    char **out_value,
    size_t *out_value_length,
    bool *out_value_is_null,
    char **out_format,
    size_t *out_format_length,
    bool *out_format_is_null
) {
    int rc = MYLITE_OK;

    if (out_value == NULL || out_value_length == NULL || out_value_is_null == NULL ||
        out_format == NULL || out_format_length == NULL || out_format_is_null == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = NULL;
    *out_value_length = 0U;
    *out_value_is_null = false;
    *out_format = NULL;
    *out_format_length = 0U;
    *out_format_is_null = false;

    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL || expression->kind != MYLITE_SQL_AST_DATE_FORMAT_FUNCTION ||
        mylite_sql_ast_node_child_count(expression) != 2U) {
        set_native_function_parameter_count_error(database, "DATE_FORMAT");
        return MYLITE_ERROR;
    }

    rc = date_format_string_or_null_argument(
        database,
        child_at(expression, 0U),
        "DATE_FORMAT() supports only string, DATE, DATETIME, TIMESTAMP, and NULL values",
        out_value,
        out_value_length,
        out_value_is_null
    );
    if (rc == MYLITE_OK) {
        rc = date_format_string_or_null_argument(
            database,
            child_at(expression, 1U),
            "DATE_FORMAT() supports only string format literals and NULL",
            out_format,
            out_format_length,
            out_format_is_null
        );
    }
    if (rc == MYLITE_OK && !*out_format_is_null) {
        rc = mylite_date_format_validate_format(database, *out_format, *out_format_length);
    }
    return rc;
}

static int date_format_string_or_null_argument(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    const char *unsupported_message,
    char **out_text,
    size_t *out_text_length,
    bool *out_is_null
) {
    int rc = MYLITE_OK;

    if (out_text == NULL || out_text_length == NULL || out_is_null == NULL) {
        return MYLITE_MISUSE;
    }
    *out_text = NULL;
    *out_text_length = 0U;
    *out_is_null = false;

    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }
    if (expression->kind == MYLITE_SQL_AST_LITERAL &&
        mylite_sql_ast_node_literal_kind(expression) == MYLITE_SQL_AST_LITERAL_NULL) {
        *out_is_null = true;
        return MYLITE_OK;
    }
    if (expression->kind == MYLITE_SQL_AST_IDENTIFIER ||
        expression->kind == MYLITE_SQL_AST_QUALIFIED_IDENTIFIER) {
        return date_add_set_unknown_identifier_error(database, expression);
    }
    if (expression->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(expression) != MYLITE_SQL_AST_LITERAL_STRING) {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }

    rc = decode_sql_string_literal(
        database,
        expression,
        unsupported_message,
        "DATE_FORMAT() literals do not support NUL bytes",
        out_text,
        out_text_length
    );
    if (rc == MYLITE_OK && memchr(*out_text, '\0', *out_text_length) != NULL) {
        set_unsupported_error(database, "DATE_FORMAT() literals do not support NUL bytes");
        rc = MYLITE_ERROR;
    }
    return rc;
}

static int date_format_numeric_equal_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    const struct mylite_sql_ast_node *date_format = NULL;
    const struct mylite_sql_ast_node *numeric = NULL;
    char *value = NULL;
    char *format = NULL;
    char *formatted = NULL;
    size_t value_length = 0U;
    size_t format_length = 0U;
    bool value_is_null = false;
    bool format_is_null = false;
    bool result_is_null = false;
    double left = 0.0;
    double right = 0.0;
    char *end = NULL;
    int rc = MYLITE_OK;
    int written = 0;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    if (!row_scalar_date_format_numeric_equal_sides(expression, &date_format, &numeric)) {
        set_unsupported_error(
            database,
            "DATE_FORMAT() numeric comparison supports only DATE_FORMAT(value, format) = "
            "numeric_literal"
        );
        return MYLITE_ERROR;
    }

    rc = date_format_function_arguments(
        database,
        date_format,
        &value,
        &value_length,
        &value_is_null,
        &format,
        &format_length,
        &format_is_null
    );
    if (rc == MYLITE_OK && !format_is_null &&
        !date_format_numeric_equal_format_is_supported(format, format_length)) {
        set_unsupported_error(
            database,
            "DATE_FORMAT() numeric comparison supports only DATE_FORMAT(value, '%H.%i') = "
            "numeric_literal"
        );
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && !value_is_null && !format_is_null) {
        rc = mylite_date_format_value(
            database,
            value,
            value_length,
            MYLITE_DATE_FORMAT_INPUT_STRING,
            format,
            format_length,
            &formatted,
            &result_is_null
        );
    } else {
        result_is_null = true;
    }
    if (rc == MYLITE_OK) {
        rc = date_format_numeric_literal_value(database, numeric, &right);
    }
    if (rc != MYLITE_OK) {
        free(value);
        free(format);
        free(formatted);
        return rc;
    }
    if (result_is_null) {
        free(value);
        free(format);
        free(formatted);
        return MYLITE_OK;
    }

    left = strtod(formatted, &end);
    if (end == formatted || *end != '\0') {
        set_unsupported_error(
            database,
            "DATE_FORMAT() numeric comparison supports only numeric DATE_FORMAT() output"
        );
        free(value);
        free(format);
        free(formatted);
        return MYLITE_ERROR;
    }
    written = snprintf(
        out_cell->integer_text,
        sizeof(out_cell->integer_text),
        "%d",
        left == right ? 1 : 0
    );
    if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
        set_runtime_error(database, "failed to format DATE_FORMAT() comparison value");
        free(value);
        free(format);
        free(formatted);
        return MYLITE_ERROR;
    }
    out_cell->value = out_cell->integer_text;
    free(value);
    free(format);
    free(formatted);
    return MYLITE_OK;
}

static bool is_date_format_numeric_equal_expression(const struct mylite_sql_ast_node *expression) {
    const struct mylite_sql_ast_node *date_format = NULL;
    const struct mylite_sql_ast_node *numeric = NULL;

    return row_scalar_date_format_numeric_equal_sides(expression, &date_format, &numeric);
}

static int date_format_numeric_literal_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    double *out_value
) {
    const struct mylite_sql_ast_node *literal = expression;
    bool is_negative = false;
    size_t text_size = 0U;
    char *text = NULL;
    char *end = NULL;
    int rc = MYLITE_OK;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = 0.0;
    expression = unwrap_parenthesized_expression(expression);
    if (expression != NULL && expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

        if (operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            is_negative = true;
        } else if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE) {
            set_unsupported_error(database, "DATE_FORMAT() numeric comparison requires a literal");
            return MYLITE_ERROR;
        }
        literal = unwrap_parenthesized_expression(child_at(expression, 0U));
    }
    if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
        (mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER &&
         mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_DECIMAL)) {
        set_unsupported_error(database, "DATE_FORMAT() numeric comparison requires a literal");
        return MYLITE_ERROR;
    }
    text_size = literal->span.length + 1U;
    if (is_negative) {
        ++text_size;
    }
    text = (char *)malloc(text_size);
    if (text == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    if (is_negative) {
        text[0] = '-';
        memcpy(text + 1, literal->span.text, literal->span.length);
        text[literal->span.length + 1U] = '\0';
    } else {
        memcpy(text, literal->span.text, literal->span.length);
        text[literal->span.length] = '\0';
    }
    *out_value = strtod(text, &end);
    if (end == text || *end != '\0') {
        set_unsupported_error(database, "DATE_FORMAT() numeric comparison requires a literal");
        rc = MYLITE_ERROR;
    }
    free(text);
    return rc;
}

static bool date_format_numeric_equal_format_is_supported(
    const char *format,
    size_t format_length
) {
    static const char supported_format[] = "%H.%i";

    return (format != NULL && format_length == sizeof(supported_format) - 1U &&
            memcmp(format, supported_format, sizeof(supported_format) - 1U) == 0) != 0;
}

static int date_add_second_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct date_add_datetime_parts input = {0};
    struct date_add_datetime_parts output = {0};
    int64_t interval_seconds = 0;
    bool temporal_is_null = false;
    bool interval_is_null = false;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};

    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL || expression->kind != MYLITE_SQL_AST_DATE_ADD_FUNCTION ||
        mylite_sql_ast_node_child_count(expression) != 2U) {
        set_unsupported_error(
            database,
            "DATE_ADD() supports only DATE_ADD(date, INTERVAL value SECOND)"
        );
        return MYLITE_ERROR;
    }

    rc = date_add_second_temporal_argument(
        database,
        child_at(expression, 0U),
        &input,
        &temporal_is_null
    );
    if (rc != MYLITE_OK || temporal_is_null) {
        return rc;
    }
    rc = date_add_second_interval_argument(
        database,
        child_at(expression, 1U),
        &interval_seconds,
        &interval_is_null
    );
    if (rc != MYLITE_OK || interval_is_null) {
        return rc;
    }
    rc = date_add_second_apply(database, &input, interval_seconds, &output);
    if (rc != MYLITE_OK) {
        return rc;
    }
    return date_add_second_format(database, &output, out_cell);
}

static int date_add_second_temporal_argument(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct date_add_datetime_parts *out_datetime,
    bool *out_is_null
) {
    char *text = NULL;
    size_t text_length = 0U;
    int rc = MYLITE_OK;

    if (out_datetime == NULL || out_is_null == NULL) {
        return MYLITE_MISUSE;
    }
    *out_datetime = (struct date_add_datetime_parts){0};
    *out_is_null = false;

    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_unsupported_error(
            database,
            "DATE_ADD() supports only date or datetime string literals and NULL"
        );
        return MYLITE_ERROR;
    }
    if (expression->kind == MYLITE_SQL_AST_IDENTIFIER) {
        return date_add_set_unknown_identifier_error(database, expression);
    }
    if (expression->kind != MYLITE_SQL_AST_LITERAL) {
        set_unsupported_error(
            database,
            "DATE_ADD() supports only date or datetime string literals and NULL"
        );
        return MYLITE_ERROR;
    }
    if (mylite_sql_ast_node_literal_kind(expression) == MYLITE_SQL_AST_LITERAL_NULL) {
        *out_is_null = true;
        return MYLITE_OK;
    }

    rc = decode_sql_string_literal(
        database,
        expression,
        "DATE_ADD() supports only date or datetime string literals and NULL",
        "DATE_ADD() date literals do not support NUL bytes",
        &text,
        &text_length
    );
    if (rc == MYLITE_OK && memchr(text, '\0', text_length) != NULL) {
        set_unsupported_error(database, "DATE_ADD() date literals do not support NUL bytes");
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && !date_add_parse_datetime_text(text, text_length, out_datetime)) {
        set_unsupported_error(
            database,
            "DATE_ADD() supports only canonical YYYY-MM-DD or YYYY-MM-DD HH:MM:SS values"
        );
        rc = MYLITE_ERROR;
    }
    free(text);
    return rc;
}

static int date_add_second_interval_argument(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    int64_t *out_interval,
    bool *out_is_null
) {
    bool out_of_range = false;

    expression = unwrap_parenthesized_expression(expression);
    if (out_interval == NULL || out_is_null == NULL) {
        return MYLITE_MISUSE;
    }
    *out_interval = 0;
    *out_is_null = false;

    if (expression == NULL) {
        set_unsupported_error(
            database,
            "DATE_ADD() INTERVAL SECOND supports only signed integer literals and NULL"
        );
        return MYLITE_ERROR;
    }
    if (expression->kind == MYLITE_SQL_AST_LITERAL &&
        mylite_sql_ast_node_literal_kind(expression) == MYLITE_SQL_AST_LITERAL_NULL) {
        *out_is_null = true;
        return MYLITE_OK;
    }
    if (!date_add_signed_integer_literal(expression, out_interval, &out_of_range)) {
        if (out_of_range) {
            set_unsupported_error(
                database,
                "DATE_ADD() INTERVAL SECOND literals must fit the signed 64-bit range"
            );
            return MYLITE_ERROR;
        }
        set_unsupported_error(
            database,
            "DATE_ADD() INTERVAL SECOND supports only signed integer literals and NULL"
        );
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int date_add_second_apply(
    struct mylite_db *database,
    const struct date_add_datetime_parts *input,
    int64_t interval_seconds,
    struct date_add_datetime_parts *out_datetime
) {
    const int64_t seconds_per_day = date_add_seconds_per_day();
    struct date_add_day_second result_day_second = {0};
    int64_t days = 0;
    int64_t day_seconds = 0;
    int64_t base_seconds = 0;
    int64_t result_seconds = 0;
    int64_t result_day_seconds = 0;

    if (input == NULL || out_datetime == NULL) {
        return MYLITE_MISUSE;
    }
    *out_datetime = (struct date_add_datetime_parts){0};

    days = date_add_days_from_datetime(input);
    day_seconds = ((int64_t)input->hour * (int64_t)time_second_per_hour) +
                  ((int64_t)input->minute * (int64_t)time_second_per_minute) +
                  (int64_t)input->second;
    base_seconds = (days * seconds_per_day) + day_seconds;
    if (!date_add_checked_add_int64(base_seconds, interval_seconds, &result_seconds)) {
        set_unsupported_error(
            database,
            "DATE_ADD() result is outside the supported datetime range"
        );
        return MYLITE_ERROR;
    }

    result_day_second = date_add_floor_divmod_seconds(result_seconds);
    date_add_civil_from_days(result_day_second.days, out_datetime);
    if (out_datetime->year < date_minimum_year || out_datetime->year > date_maximum_year) {
        set_unsupported_error(
            database,
            "DATE_ADD() result is outside the supported datetime range"
        );
        return MYLITE_ERROR;
    }

    result_day_seconds = result_day_second.day_seconds;
    out_datetime->hour = (uint32_t)(result_day_seconds / time_second_per_hour);
    result_day_seconds %= time_second_per_hour;
    out_datetime->minute = (uint32_t)(result_day_seconds / time_second_per_minute);
    out_datetime->second = (uint32_t)(result_day_seconds % time_second_per_minute);
    return MYLITE_OK;
}

static int date_add_second_format(
    struct mylite_db *database,
    const struct date_add_datetime_parts *datetime,
    struct session_scalar_cell *out_cell
) {
    int written = 0;

    if (datetime == NULL || out_cell == NULL) {
        return MYLITE_MISUSE;
    }

    written = snprintf(
        out_cell->datetime_text,
        sizeof(out_cell->datetime_text),
        "%04" PRId64 "-%02" PRIu32 "-%02" PRIu32 " %02" PRIu32 ":%02" PRIu32 ":%02" PRIu32,
        datetime->year,
        datetime->month,
        datetime->day,
        datetime->hour,
        datetime->minute,
        datetime->second
    );
    if (written != datetime_text_length) {
        set_runtime_error(database, "failed to format DATE_ADD() result");
        return MYLITE_ERROR;
    }

    out_cell->value = out_cell->datetime_text;
    return MYLITE_OK;
}

static bool date_add_parse_datetime_text(
    const char *text,
    size_t text_length,
    struct date_add_datetime_parts *out_datetime
) {
    uint32_t year = 0U;

    if (out_datetime == NULL) {
        return false;
    }
    *out_datetime = (struct date_add_datetime_parts){0};
    if (date_text_is_canonical_valid(text, text_length)) {
        if (!date_component_text_to_u32(
                text + date_year_text_offset,
                date_year_text_length,
                &year
            ) ||
            !date_component_text_to_u32(
                text + date_month_text_offset,
                date_month_text_length,
                &out_datetime->month
            ) ||
            !date_component_text_to_u32(
                text + date_day_text_offset,
                date_day_text_length,
                &out_datetime->day
            )) {
            return false;
        }
        out_datetime->year = (int64_t)year;
        out_datetime->hour = 0U;
        out_datetime->minute = 0U;
        out_datetime->second = 0U;
        return true;
    }
    if (!datetime_text_is_canonical_valid(text, text_length)) {
        return false;
    }
    if (!date_component_text_to_u32(text + date_year_text_offset, date_year_text_length, &year) ||
        !date_component_text_to_u32(
            text + date_month_text_offset,
            date_month_text_length,
            &out_datetime->month
        ) ||
        !date_component_text_to_u32(
            text + date_day_text_offset,
            date_day_text_length,
            &out_datetime->day
        ) ||
        !date_component_text_to_u32(
            text + datetime_hour_text_offset,
            datetime_hour_text_length,
            &out_datetime->hour
        ) ||
        !date_component_text_to_u32(
            text + datetime_minute_text_offset,
            datetime_minute_text_length,
            &out_datetime->minute
        ) ||
        !date_component_text_to_u32(
            text + datetime_second_text_offset,
            datetime_second_text_length,
            &out_datetime->second
        )) {
        return false;
    }
    out_datetime->year = (int64_t)year;
    return true;
}

static bool date_add_signed_integer_literal(
    const struct mylite_sql_ast_node *expression,
    int64_t *out_value,
    bool *out_out_of_range
) {
    const uint64_t signed_negative_abs_max = 9223372036854775808ULL;
    const struct mylite_sql_ast_node *literal = expression;
    uint64_t magnitude = 0U;
    bool is_negative = false;

    if (out_value == NULL || out_out_of_range == NULL) {
        return false;
    }
    *out_value = 0;
    *out_out_of_range = false;
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        return false;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

        if (operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            is_negative = true;
        } else if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE) {
            return false;
        }
        literal = unwrap_parenthesized_expression(child_at(expression, 0U));
    } else {
        literal = expression;
    }
    if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER) {
        return false;
    }
    if (parse_unsigned_integer_literal(&literal->span, &magnitude) != MYLITE_OK) {
        *out_out_of_range = true;
        return false;
    }

    if (is_negative) {
        if (magnitude > signed_negative_abs_max) {
            *out_out_of_range = true;
            return false;
        }
        if (magnitude == signed_negative_abs_max) {
            *out_value = INT64_MIN;
        } else {
            *out_value = -(int64_t)magnitude;
        }
        return true;
    }
    if (magnitude > (uint64_t)INT64_MAX) {
        *out_out_of_range = true;
        return false;
    }
    *out_value = (int64_t)magnitude;
    return true;
}

static int date_add_set_unknown_identifier_error(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression
) {
    char column_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];

    if (expression == NULL ||
        !date_add_copy_identifier_span_text(&expression->span, column_name, sizeof(column_name))) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    set_unknown_column_error(database, column_name);
    return MYLITE_ERROR;
}

static bool date_add_copy_identifier_span_text(
    const struct mylite_sql_source_span *span,
    char *destination,
    size_t destination_size
) {
    const char *source = NULL;
    size_t source_size = 0U;
    size_t destination_index = 0U;

    if (span == NULL || span->text == NULL || span->length == 0U || destination == NULL ||
        destination_size == 0U) {
        return false;
    }

    source = span->text;
    source_size = span->length;
    if (source[0] != '`' && source[0] != '"') {
        if (source_size >= destination_size) {
            return false;
        }
        memcpy(destination, source, source_size);
        destination[source_size] = '\0';
        return true;
    }
    if (source_size < 2U || source[source_size - 1U] != source[0]) {
        return false;
    }
    for (size_t source_index = 1U; source_index + 1U < source_size; ++source_index) {
        if (destination_index + 1U >= destination_size) {
            return false;
        }
        if (source[source_index] == source[0] && source[source_index + 1U] == source[0]) {
            destination[destination_index] = source[0];
            ++source_index;
        } else {
            destination[destination_index] = source[source_index];
        }
        ++destination_index;
    }
    destination[destination_index] = '\0';
    return destination_index != 0U;
}

static bool date_add_checked_add_int64(int64_t left, int64_t right, int64_t *out_value) {
    if (out_value == NULL) {
        return false;
    }
    if ((right > 0 && left > INT64_MAX - right) || (right < 0 && left < INT64_MIN - right)) {
        return false;
    }
    *out_value = left + right;
    return true;
}

static int64_t date_add_seconds_per_day(void) {
    return (int64_t)datetime_hours_per_day * (int64_t)time_second_per_hour;
}

static int64_t date_add_days_from_datetime(const struct date_add_datetime_parts *datetime) {
    uint32_t month_prime = 0U;
    uint32_t year_of_era = 0U;
    uint32_t day_of_year = 0U;
    uint32_t day_of_era = 0U;
    int64_t era = 0;
    int64_t year = 0;

    if (datetime == NULL) {
        return 0;
    }
    year = datetime->year;
    year -= datetime->month <= date_add_march_year_shift_month ? 1 : 0;
    era = (year >= 0 ? year : year - date_add_era_year_offset) / date_leap_year_quadricentennial;
    year_of_era = (uint32_t)(year - (era * date_leap_year_quadricentennial));
    month_prime = datetime->month > date_add_march_year_shift_month
                      ? datetime->month - date_add_month_shift
                      : datetime->month + date_add_march_based_months_after_february;
    day_of_year =
        (((date_add_month_scale * month_prime) + date_add_month_bias) / date_add_month_divisor) +
        datetime->day - 1U;
    day_of_era = (year_of_era * date_add_days_per_non_leap_year) +
                 (year_of_era / date_leap_year_quadrennial) -
                 (year_of_era / date_leap_year_century) + day_of_year;

    return (era * date_add_days_per_era) + (int64_t)day_of_era - date_add_unix_epoch_day_offset;
}

static void date_add_civil_from_days(int64_t days, struct date_add_datetime_parts *out_datetime) {
    uint32_t day_of_era = 0U;
    uint32_t year_of_era = 0U;
    uint32_t day_of_year = 0U;
    uint32_t month_prime = 0U;
    int64_t era = 0;
    int64_t year = 0;

    if (out_datetime == NULL) {
        return;
    }
    days += date_add_unix_epoch_day_offset;
    era = (days >= 0 ? days : days - date_add_days_per_era_offset) / date_add_days_per_era;
    day_of_era = (uint32_t)(days - (era * date_add_days_per_era));
    year_of_era = (day_of_era - (day_of_era / date_add_leap_cycle_four_year_days) +
                   (day_of_era / date_add_leap_cycle_century_days) -
                   (day_of_era / date_add_days_per_era_offset)) /
                  date_add_days_per_non_leap_year;
    year = (int64_t)year_of_era + (era * date_leap_year_quadricentennial);
    day_of_year = day_of_era - ((date_add_days_per_non_leap_year * year_of_era) +
                                (year_of_era / date_leap_year_quadrennial) -
                                (year_of_era / date_leap_year_century));
    month_prime =
        ((date_add_month_divisor * day_of_year) + date_add_month_bias) / date_add_month_scale;

    out_datetime->day =
        day_of_year -
        (((date_add_month_scale * month_prime) + date_add_month_bias) / date_add_month_divisor) +
        1U;
    out_datetime->month = month_prime < date_add_march_based_month_switch
                              ? month_prime + date_add_month_shift
                              : month_prime - date_add_march_based_months_after_february;
    out_datetime->year = year + (out_datetime->month <= date_add_march_year_shift_month ? 1 : 0);
}

static struct date_add_day_second date_add_floor_divmod_seconds(int64_t total_seconds) {
    const int64_t seconds_per_day = date_add_seconds_per_day();
    struct date_add_day_second result = {0};

    result.days = total_seconds / seconds_per_day;
    result.day_seconds = total_seconds % seconds_per_day;

    if (result.day_seconds < 0) {
        result.day_seconds += seconds_per_day;
        --result.days;
    }
    return result;
}

static int evaluate_bit_count_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_bitwise_value *out_value
) {
    struct scalar_arithmetic_value arithmetic = {.is_null = false, .integer = 0};
    bool handled = false;
    int rc = MYLITE_OK;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct scalar_bitwise_value){.is_null = false, .integer = 0U};
    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_bit_count_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_bit_count_direct_literal_operand(database, expression, out_value, &handled);
    if (rc != MYLITE_OK || handled) {
        return rc;
    }
    if (is_scalar_bitwise_projection_expression(expression)) {
        return evaluate_scalar_bitwise_expression(database, expression, out_value);
    }
    if (!is_scalar_arithmetic_projection_expression(expression)) {
        set_bit_count_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = evaluate_scalar_arithmetic_expression(database, expression, &arithmetic);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_value->is_null = arithmetic.is_null;
    out_value->integer = (uint64_t)arithmetic.integer;
    out_value->division_by_zero_warning_count = arithmetic.division_by_zero_warning_count;
    return MYLITE_OK;
}

static int evaluate_bit_count_direct_literal_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_bitwise_value *out_value,
    bool *out_handled
) {
    static const uint64_t int64_min_magnitude = 9223372036854775808ULL;
    const struct mylite_sql_ast_node *literal = expression;
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NONE;
    bool is_negative = false;
    bool has_sign = false;
    uint64_t magnitude = 0U;

    if (out_value == NULL || out_handled == NULL) {
        return MYLITE_MISUSE;
    }
    *out_handled = false;
    if (expression == NULL) {
        return MYLITE_OK;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

        if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
            operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            return MYLITE_OK;
        }
        literal = unwrap_parenthesized_expression(child_at(expression, 0U));
        if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
            mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER) {
            return MYLITE_OK;
        }
        has_sign = true;
        is_negative = operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE;
    }
    if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL) {
        return MYLITE_OK;
    }

    literal_kind = mylite_sql_ast_node_literal_kind(literal);
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_NULL) {
        out_value->is_null = true;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_TRUE) {
        out_value->integer = 1U;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (!has_sign && literal_kind == MYLITE_SQL_AST_LITERAL_FALSE) {
        out_value->integer = 0U;
        *out_handled = true;
        return MYLITE_OK;
    }
    if (literal_kind != MYLITE_SQL_AST_LITERAL_INTEGER) {
        return MYLITE_OK;
    }
    *out_handled = true;

    if (parse_unsigned_integer_literal(&literal->span, &magnitude) != MYLITE_OK) {
        set_bit_count_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (!is_negative) {
        out_value->integer = magnitude;
        return MYLITE_OK;
    }
    if (magnitude > int64_min_magnitude) {
        set_bit_count_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (magnitude == int64_min_magnitude) {
        out_value->integer = (uint64_t)INT64_MIN;
    } else if (magnitude != 0U) {
        out_value->integer = (uint64_t)(-(int64_t)magnitude);
    }
    return MYLITE_OK;
}

static uint64_t count_uint64_bits(uint64_t value) {
    uint64_t count = 0U;

    while (value != 0U) {
        count += value & 1U;
        value >>= 1U;
    }
    return count;
}

static int evaluate_scalar_bitwise_expression(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_bitwise_value *out_value
) {
    struct scalar_bitwise_eval_stack expression_stack = {0};
    struct scalar_bitwise_value_stack value_stack = {0};
    int rc = MYLITE_OK;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct scalar_bitwise_value){.is_null = false, .integer = 0U};
    if (expression == NULL) {
        set_scalar_bitwise_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = scalar_bitwise_eval_stack_push(
        database,
        &expression_stack,
        SCALAR_BITWISE_EVAL_ENTER,
        expression,
        MYLITE_SQL_AST_OPERATOR_NONE
    );
    while (rc == MYLITE_OK && expression_stack.count != 0U) {
        struct scalar_bitwise_eval_frame frame = expression_stack.items[--expression_stack.count];

        rc = evaluate_scalar_bitwise_frame(database, &expression_stack, &value_stack, &frame);
    }
    if (rc == MYLITE_OK && !scalar_bitwise_value_stack_pop(&value_stack, out_value)) {
        set_runtime_error(database, "missing scalar bitwise result");
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && value_stack.count != 0U) {
        set_runtime_error(database, "invalid scalar bitwise result stack");
        rc = MYLITE_ERROR;
    }

    scalar_bitwise_eval_stack_deinit(&expression_stack);
    scalar_bitwise_value_stack_deinit(&value_stack);
    return rc;
}

static int evaluate_scalar_bitwise_frame(
    struct mylite_db *database,
    struct scalar_bitwise_eval_stack *expression_stack,
    struct scalar_bitwise_value_stack *value_stack,
    const struct scalar_bitwise_eval_frame *frame
) {
    if (frame == NULL) {
        return MYLITE_MISUSE;
    }
    switch (frame->kind) {
    case SCALAR_BITWISE_EVAL_APPLY:
        return evaluate_scalar_bitwise_apply_frame(database, value_stack, frame->operator_kind);
    case SCALAR_BITWISE_EVAL_APPLY_UNARY:
        return evaluate_scalar_bitwise_apply_unary_frame(database, value_stack);
    case SCALAR_BITWISE_EVAL_SHORT_CIRCUIT_OR_ENTER_RIGHT:
        return evaluate_scalar_bitwise_short_circuit_or_enter_right_frame(
            database,
            expression_stack,
            value_stack,
            frame
        );
    case SCALAR_BITWISE_EVAL_ENTER:
        return evaluate_scalar_bitwise_enter_frame(
            database,
            expression_stack,
            value_stack,
            frame->expression
        );
    }

    set_runtime_error(database, "invalid scalar bitwise evaluation frame");
    return MYLITE_ERROR;
}

static int evaluate_scalar_bitwise_apply_frame(
    struct mylite_db *database,
    struct scalar_bitwise_value_stack *value_stack,
    enum mylite_sql_ast_operator operator_kind
) {
    struct scalar_bitwise_value left = {.is_null = false, .integer = 0U};
    struct scalar_bitwise_value right = {.is_null = false, .integer = 0U};
    struct scalar_bitwise_value result = {.is_null = false, .integer = 0U};
    int rc = MYLITE_OK;

    if (!scalar_bitwise_value_stack_pop(value_stack, &right) ||
        !scalar_bitwise_value_stack_pop(value_stack, &left)) {
        set_runtime_error(database, "invalid scalar bitwise evaluation stack");
        return MYLITE_ERROR;
    }
    if (left.division_by_zero_warning_count > SIZE_MAX - right.division_by_zero_warning_count) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    result.division_by_zero_warning_count =
        left.division_by_zero_warning_count + right.division_by_zero_warning_count;

    rc = apply_scalar_bitwise_operator(&left, &right, operator_kind, &result);
    if (rc == MYLITE_OK) {
        rc = scalar_bitwise_value_stack_push(database, value_stack, result);
    } else {
        set_scalar_bitwise_unsupported_error(database);
    }
    return rc;
}

static int evaluate_scalar_bitwise_apply_unary_frame(
    struct mylite_db *database,
    struct scalar_bitwise_value_stack *value_stack
) {
    struct scalar_bitwise_value value = {.is_null = false, .integer = 0U};

    if (!scalar_bitwise_value_stack_pop(value_stack, &value)) {
        set_runtime_error(database, "invalid scalar bitwise evaluation stack");
        return MYLITE_ERROR;
    }
    if (!value.is_null) {
        value.integer = ~value.integer;
    }
    return scalar_bitwise_value_stack_push(database, value_stack, value);
}

static int evaluate_scalar_bitwise_short_circuit_or_enter_right_frame(
    struct mylite_db *database,
    struct scalar_bitwise_eval_stack *expression_stack,
    const struct scalar_bitwise_value_stack *value_stack,
    const struct scalar_bitwise_eval_frame *frame
) {
    const struct scalar_bitwise_value *left = NULL;
    int rc = MYLITE_OK;

    if (value_stack == NULL || frame == NULL || value_stack->count == 0U) {
        set_runtime_error(database, "invalid scalar bitwise evaluation stack");
        return MYLITE_ERROR;
    }

    left = &value_stack->items[value_stack->count - 1U];
    if (left->is_null) {
        return MYLITE_OK;
    }

    rc = scalar_bitwise_eval_stack_push(
        database,
        expression_stack,
        SCALAR_BITWISE_EVAL_APPLY,
        NULL,
        frame->operator_kind
    );
    if (rc == MYLITE_OK) {
        rc = scalar_bitwise_eval_stack_push(
            database,
            expression_stack,
            SCALAR_BITWISE_EVAL_ENTER,
            frame->expression,
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    return rc;
}

static int evaluate_scalar_bitwise_enter_frame(
    struct mylite_db *database,
    struct scalar_bitwise_eval_stack *expression_stack,
    struct scalar_bitwise_value_stack *value_stack,
    const struct mylite_sql_ast_node *expression
) {
    enum mylite_sql_ast_operator operator_kind = MYLITE_SQL_AST_OPERATOR_NONE;
    struct scalar_bitwise_value value = {.is_null = false, .integer = 0U};
    int rc = MYLITE_OK;

    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_scalar_bitwise_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        operator_kind = mylite_sql_ast_node_operator(expression);
        if (!is_scalar_bitwise_unary_operator(operator_kind)) {
            rc = evaluate_scalar_bitwise_operand(database, expression, &value);
            if (rc == MYLITE_OK) {
                rc = scalar_bitwise_value_stack_push(database, value_stack, value);
            }
            return rc;
        }
        rc = scalar_bitwise_eval_stack_push(
            database,
            expression_stack,
            SCALAR_BITWISE_EVAL_APPLY_UNARY,
            NULL,
            operator_kind
        );
        if (rc == MYLITE_OK) {
            rc = scalar_bitwise_eval_stack_push(
                database,
                expression_stack,
                SCALAR_BITWISE_EVAL_ENTER,
                child_at(expression, 0U),
                MYLITE_SQL_AST_OPERATOR_NONE
            );
        }
        return rc;
    }
    if (expression->kind == MYLITE_SQL_AST_BINARY_EXPRESSION) {
        operator_kind = mylite_sql_ast_node_operator(expression);
        if (is_scalar_bitwise_operator(operator_kind)) {
            rc = scalar_bitwise_eval_stack_push(
                database,
                expression_stack,
                SCALAR_BITWISE_EVAL_SHORT_CIRCUIT_OR_ENTER_RIGHT,
                child_at(expression, 1U),
                operator_kind
            );
            if (rc == MYLITE_OK) {
                rc = scalar_bitwise_eval_stack_push(
                    database,
                    expression_stack,
                    SCALAR_BITWISE_EVAL_ENTER,
                    child_at(expression, 0U),
                    MYLITE_SQL_AST_OPERATOR_NONE
                );
            }
            return rc;
        }
    }

    rc = evaluate_scalar_bitwise_operand(database, expression, &value);
    if (rc == MYLITE_OK) {
        rc = scalar_bitwise_value_stack_push(database, value_stack, value);
    }
    return rc;
}

static int evaluate_scalar_bitwise_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_bitwise_value *out_value
) {
    struct scalar_arithmetic_value arithmetic = {.is_null = false, .integer = 0};
    int rc = MYLITE_OK;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct scalar_bitwise_value){.is_null = false, .integer = 0U};
    rc = evaluate_scalar_arithmetic_expression(database, expression, &arithmetic);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_value->is_null = arithmetic.is_null;
    out_value->integer = (uint64_t)arithmetic.integer;
    out_value->division_by_zero_warning_count = arithmetic.division_by_zero_warning_count;
    return MYLITE_OK;
}

static int apply_scalar_bitwise_operator(
    const struct scalar_bitwise_value *left,
    const struct scalar_bitwise_value *right,
    enum mylite_sql_ast_operator operator_kind,
    struct scalar_bitwise_value *out_result
) {
    if (left == NULL || right == NULL || out_result == NULL) {
        return MYLITE_MISUSE;
    }
    if (left->is_null || right->is_null) {
        out_result->is_null = true;
        return MYLITE_OK;
    }

    switch (operator_kind) {
    case MYLITE_SQL_AST_OPERATOR_BITWISE_XOR:
        out_result->integer = left->integer ^ right->integer;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_LEFT_SHIFT:
        out_result->integer =
            right->integer >= scalar_bitwise_integer_bits ? 0U : left->integer << right->integer;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_RIGHT_SHIFT:
        out_result->integer =
            right->integer >= scalar_bitwise_integer_bits ? 0U : left->integer >> right->integer;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_BITWISE_AND:
        out_result->integer = left->integer & right->integer;
        return MYLITE_OK;
    case MYLITE_SQL_AST_OPERATOR_BITWISE_OR:
        out_result->integer = left->integer | right->integer;
        return MYLITE_OK;
    default:
        return MYLITE_ERROR;
    }
}

static int scalar_bitwise_eval_stack_push(
    struct mylite_db *database,
    struct scalar_bitwise_eval_stack *stack,
    enum scalar_bitwise_eval_frame_kind kind,
    const struct mylite_sql_ast_node *expression,
    enum mylite_sql_ast_operator operator_kind
) {
    struct scalar_bitwise_eval_frame *items = NULL;
    size_t capacity = 0U;

    if (stack == NULL) {
        return MYLITE_MISUSE;
    }
    if (stack->count == stack->capacity) {
        capacity = stack->capacity == 0U ? if_stack_initial_capacity : stack->capacity * 2U;
        if (capacity < stack->capacity || capacity > SIZE_MAX / sizeof(*items)) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        items = (struct scalar_bitwise_eval_frame *)
            realloc((void *)stack->items, capacity * sizeof(*items));
        if (items == NULL) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        stack->items = items;
        stack->capacity = capacity;
    }

    stack->items[stack->count] = (struct scalar_bitwise_eval_frame){
        .kind = kind,
        .expression = expression,
        .operator_kind = operator_kind,
    };
    ++stack->count;
    return MYLITE_OK;
}

static void scalar_bitwise_eval_stack_deinit(struct scalar_bitwise_eval_stack *stack) {
    if (stack == NULL) {
        return;
    }

    free((void *)stack->items);
    *stack = (struct scalar_bitwise_eval_stack){0};
}

static int scalar_bitwise_value_stack_push(
    struct mylite_db *database,
    struct scalar_bitwise_value_stack *stack,
    struct scalar_bitwise_value value
) {
    struct scalar_bitwise_value *items = NULL;
    size_t capacity = 0U;

    if (stack == NULL) {
        return MYLITE_MISUSE;
    }
    if (stack->count == stack->capacity) {
        capacity = stack->capacity == 0U ? if_stack_initial_capacity : stack->capacity * 2U;
        if (capacity < stack->capacity || capacity > SIZE_MAX / sizeof(*items)) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        items =
            (struct scalar_bitwise_value *)realloc((void *)stack->items, capacity * sizeof(*items));
        if (items == NULL) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        stack->items = items;
        stack->capacity = capacity;
    }

    stack->items[stack->count] = value;
    ++stack->count;
    return MYLITE_OK;
}

static bool scalar_bitwise_value_stack_pop(
    struct scalar_bitwise_value_stack *stack,
    struct scalar_bitwise_value *out_value
) {
    if (stack == NULL || out_value == NULL || stack->count == 0U) {
        return false;
    }

    --stack->count;
    *out_value = stack->items[stack->count];
    return true;
}

static void scalar_bitwise_value_stack_deinit(struct scalar_bitwise_value_stack *stack) {
    if (stack == NULL) {
        return;
    }

    free((void *)stack->items);
    *stack = (struct scalar_bitwise_value_stack){0};
}

static int scalar_logical_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct scalar_arithmetic_value value = {.is_null = false, .integer = 0};
    int written = 0;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    rc = evaluate_scalar_logical_expression(database, expression, &value);
    if (rc != MYLITE_OK || value.is_null) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    written =
        snprintf(out_cell->integer_text, sizeof(out_cell->integer_text), "%" PRId64, value.integer);
    if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
        set_runtime_error(database, "failed to format scalar logical value");
        return MYLITE_ERROR;
    }

    out_cell->value = out_cell->integer_text;
    out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
    return MYLITE_OK;
}

static int evaluate_scalar_logical_expression(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_arithmetic_value *out_value
) {
    struct scalar_logical_eval_stack expression_stack = {0};
    struct scalar_arithmetic_value_stack value_stack = {0};
    int rc = MYLITE_OK;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct scalar_arithmetic_value){.is_null = false, .integer = 0};
    if (!is_scalar_logical_projection_expression(expression)) {
        set_scalar_logical_unsupported_error(database);
        return MYLITE_ERROR;
    }
    rc = scalar_logical_eval_stack_push(
        database,
        &expression_stack,
        SCALAR_LOGICAL_EVAL_ENTER,
        expression,
        MYLITE_SQL_AST_OPERATOR_NONE
    );
    while (rc == MYLITE_OK && expression_stack.count != 0U) {
        struct scalar_logical_eval_frame frame = expression_stack.items[--expression_stack.count];

        rc = evaluate_scalar_logical_frame(database, &expression_stack, &value_stack, &frame);
    }
    if (rc == MYLITE_OK) {
        rc = finish_scalar_arithmetic_result(database, &value_stack, out_value);
    }
    scalar_logical_eval_stack_deinit(&expression_stack);
    scalar_arithmetic_value_stack_deinit(&value_stack);
    return rc;
}

static int evaluate_scalar_logical_frame(
    struct mylite_db *database,
    struct scalar_logical_eval_stack *expression_stack,
    struct scalar_arithmetic_value_stack *value_stack,
    const struct scalar_logical_eval_frame *frame
) {
    if (frame == NULL) {
        return MYLITE_MISUSE;
    }
    switch (frame->kind) {
    case SCALAR_LOGICAL_EVAL_APPLY_NOT:
        return evaluate_scalar_logical_apply_not_frame(database, value_stack);
    case SCALAR_LOGICAL_EVAL_APPLY_COMPARISON:
        return evaluate_scalar_logical_apply_comparison_frame(
            database,
            value_stack,
            frame->operator_kind
        );
    case SCALAR_LOGICAL_EVAL_APPLY_IS:
        return evaluate_scalar_logical_apply_is_frame(database, value_stack, frame->operator_kind);
    case SCALAR_LOGICAL_EVAL_COMPARISON_SHORT_CIRCUIT_OR_ENTER_RIGHT:
        return evaluate_scalar_logical_comparison_short_circuit_or_enter_right_frame(
            database,
            expression_stack,
            value_stack,
            frame
        );
    case SCALAR_LOGICAL_EVAL_APPLY_LOGICAL:
        return evaluate_scalar_logical_apply_logical_frame(
            database,
            value_stack,
            frame->operator_kind
        );
    case SCALAR_LOGICAL_EVAL_LOGICAL_SHORT_CIRCUIT_OR_ENTER_RIGHT:
        return evaluate_scalar_logical_short_circuit_or_enter_right_frame(
            database,
            expression_stack,
            value_stack,
            frame
        );
    case SCALAR_LOGICAL_EVAL_ENTER:
    default:
        return evaluate_scalar_logical_enter_frame(
            database,
            expression_stack,
            value_stack,
            frame->expression
        );
    }
}

static int evaluate_scalar_logical_apply_not_frame(
    struct mylite_db *database,
    struct scalar_arithmetic_value_stack *value_stack
) {
    struct scalar_arithmetic_value value = {.is_null = false, .integer = 0};

    if (!scalar_arithmetic_value_stack_pop(value_stack, &value)) {
        set_runtime_error(database, "invalid scalar logical evaluation stack");
        return MYLITE_ERROR;
    }
    if (value.is_null) {
        return scalar_arithmetic_value_stack_push(database, value_stack, value);
    }
    value.integer = value.integer == 0 ? 1 : 0;
    return scalar_arithmetic_value_stack_push(database, value_stack, value);
}

static int evaluate_scalar_logical_apply_comparison_frame(
    struct mylite_db *database,
    struct scalar_arithmetic_value_stack *value_stack,
    enum mylite_sql_ast_operator operator_kind
) {
    struct scalar_arithmetic_value left = {.is_null = false, .integer = 0};
    struct scalar_arithmetic_value right = {.is_null = false, .integer = 0};
    struct scalar_arithmetic_value result = {.is_null = false, .integer = 0};
    struct scalar_comparison_operation operation = {
        .operator_kind = operator_kind,
        .left = 0,
        .right = 0,
    };

    if (!scalar_arithmetic_value_stack_pop(value_stack, &right) ||
        !scalar_arithmetic_value_stack_pop(value_stack, &left)) {
        set_runtime_error(database, "invalid scalar logical comparison stack");
        return MYLITE_ERROR;
    }
    if (left.division_by_zero_warning_count > SIZE_MAX - right.division_by_zero_warning_count) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    result.division_by_zero_warning_count =
        left.division_by_zero_warning_count + right.division_by_zero_warning_count;

    if (operator_kind == MYLITE_SQL_AST_OPERATOR_NULL_SAFE_EQUAL) {
        if (left.is_null || right.is_null) {
            result.integer = left.is_null == right.is_null ? 1 : 0;
            return scalar_arithmetic_value_stack_push(database, value_stack, result);
        }
        result.integer = left.integer == right.integer ? 1 : 0;
        return scalar_arithmetic_value_stack_push(database, value_stack, result);
    }
    if (left.is_null || right.is_null) {
        result.is_null = true;
        return scalar_arithmetic_value_stack_push(database, value_stack, result);
    }
    if (!is_scalar_comparison_operator(operator_kind)) {
        set_scalar_logical_unsupported_error(database);
        return MYLITE_ERROR;
    }

    operation.left = left.integer;
    operation.right = right.integer;
    if (scalar_comparison_result_is_true(&operation)) {
        result.integer = 1;
    } else {
        result.integer = 0;
    }
    return scalar_arithmetic_value_stack_push(database, value_stack, result);
}

static int evaluate_scalar_logical_apply_is_frame(
    struct mylite_db *database,
    struct scalar_arithmetic_value_stack *value_stack,
    enum mylite_sql_ast_operator operator_kind
) {
    struct scalar_arithmetic_value value = {.is_null = false, .integer = 0};
    struct scalar_arithmetic_value result = {.is_null = false, .integer = 0};

    if (!scalar_arithmetic_value_stack_pop(value_stack, &value)) {
        set_runtime_error(database, "invalid scalar IS evaluation stack");
        return MYLITE_ERROR;
    }
    result.division_by_zero_warning_count = value.division_by_zero_warning_count;

    switch (operator_kind) {
    case MYLITE_SQL_AST_OPERATOR_IS_NULL:
    case MYLITE_SQL_AST_OPERATOR_IS_UNKNOWN:
        if (value.is_null) {
            result.integer = 1;
        }
        break;
    case MYLITE_SQL_AST_OPERATOR_IS_NOT_NULL:
    case MYLITE_SQL_AST_OPERATOR_IS_NOT_UNKNOWN:
        if (!value.is_null) {
            result.integer = 1;
        }
        break;
    case MYLITE_SQL_AST_OPERATOR_IS_TRUE:
        if (scalar_arithmetic_truth_value(&value)) {
            result.integer = 1;
        }
        break;
    case MYLITE_SQL_AST_OPERATOR_IS_NOT_TRUE:
        if (!scalar_arithmetic_truth_value(&value)) {
            result.integer = 1;
        }
        break;
    case MYLITE_SQL_AST_OPERATOR_IS_FALSE:
        if (!value.is_null && value.integer == 0) {
            result.integer = 1;
        }
        break;
    case MYLITE_SQL_AST_OPERATOR_IS_NOT_FALSE:
        if (value.is_null || value.integer != 0) {
            result.integer = 1;
        }
        break;
    default:
        set_scalar_logical_unsupported_error(database);
        return MYLITE_ERROR;
    }

    return scalar_arithmetic_value_stack_push(database, value_stack, result);
}

static int evaluate_scalar_logical_comparison_short_circuit_or_enter_right_frame(
    struct mylite_db *database,
    struct scalar_logical_eval_stack *expression_stack,
    const struct scalar_arithmetic_value_stack *value_stack,
    const struct scalar_logical_eval_frame *frame
) {
    const struct scalar_arithmetic_value *left = NULL;
    int rc = MYLITE_OK;

    if (value_stack == NULL || frame == NULL || value_stack->count == 0U) {
        set_runtime_error(database, "invalid scalar logical comparison stack");
        return MYLITE_ERROR;
    }

    left = &value_stack->items[value_stack->count - 1U];
    if (left->is_null) {
        return MYLITE_OK;
    }

    rc = scalar_logical_eval_stack_push(
        database,
        expression_stack,
        SCALAR_LOGICAL_EVAL_APPLY_COMPARISON,
        NULL,
        frame->operator_kind
    );
    if (rc == MYLITE_OK) {
        rc = scalar_logical_eval_stack_push(
            database,
            expression_stack,
            SCALAR_LOGICAL_EVAL_ENTER,
            frame->expression,
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    return rc;
}

static int evaluate_scalar_logical_apply_logical_frame(
    struct mylite_db *database,
    struct scalar_arithmetic_value_stack *value_stack,
    enum mylite_sql_ast_operator operator_kind
) {
    struct scalar_arithmetic_value left = {.is_null = false, .integer = 0};
    struct scalar_arithmetic_value right = {.is_null = false, .integer = 0};
    struct scalar_arithmetic_value result = {.is_null = false, .integer = 0};

    if (!scalar_arithmetic_value_stack_pop(value_stack, &right) ||
        !scalar_arithmetic_value_stack_pop(value_stack, &left)) {
        set_runtime_error(database, "invalid scalar logical evaluation stack");
        return MYLITE_ERROR;
    }
    if (left.division_by_zero_warning_count > SIZE_MAX - right.division_by_zero_warning_count) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    result.division_by_zero_warning_count =
        left.division_by_zero_warning_count + right.division_by_zero_warning_count;

    switch (operator_kind) {
    case MYLITE_SQL_AST_OPERATOR_LOGICAL_AND:
        evaluate_scalar_logical_and_result(&left, &right, &result);
        break;
    case MYLITE_SQL_AST_OPERATOR_LOGICAL_OR:
        evaluate_scalar_logical_or_result(&left, &right, &result);
        break;
    case MYLITE_SQL_AST_OPERATOR_LOGICAL_XOR:
        evaluate_scalar_logical_xor_result(&left, &right, &result);
        break;
    default:
        set_scalar_logical_unsupported_error(database);
        return MYLITE_ERROR;
    }

    return scalar_arithmetic_value_stack_push(database, value_stack, result);
}

static void evaluate_scalar_logical_and_result(
    const struct scalar_arithmetic_value *left,
    const struct scalar_arithmetic_value *right,
    struct scalar_arithmetic_value *result
) {
    if ((!left->is_null && left->integer == 0) || (!right->is_null && right->integer == 0)) {
        result->integer = 0;
        return;
    }
    if (left->is_null || right->is_null) {
        result->is_null = true;
        return;
    }
    result->integer = 1;
}

static void evaluate_scalar_logical_or_result(
    const struct scalar_arithmetic_value *left,
    const struct scalar_arithmetic_value *right,
    struct scalar_arithmetic_value *result
) {
    if (scalar_arithmetic_truth_value(left) || scalar_arithmetic_truth_value(right)) {
        result->integer = 1;
        return;
    }
    if (left->is_null || right->is_null) {
        result->is_null = true;
        return;
    }
    result->integer = 0;
}

static void evaluate_scalar_logical_xor_result(
    const struct scalar_arithmetic_value *left,
    const struct scalar_arithmetic_value *right,
    struct scalar_arithmetic_value *result
) {
    bool left_true = false;
    bool right_true = false;

    if (left->is_null || right->is_null) {
        result->is_null = true;
        return;
    }

    left_true = scalar_arithmetic_truth_value(left);
    right_true = scalar_arithmetic_truth_value(right);
    if (left_true != right_true) {
        result->integer = 1;
    } else {
        result->integer = 0;
    }
}

static bool scalar_arithmetic_truth_value(const struct scalar_arithmetic_value *value) {
    if (value == NULL || value->is_null) {
        return false;
    }
    if (value->integer == 0) {
        return false;
    }
    return true;
}

static int evaluate_scalar_logical_short_circuit_or_enter_right_frame(
    struct mylite_db *database,
    struct scalar_logical_eval_stack *expression_stack,
    struct scalar_arithmetic_value_stack *value_stack,
    const struct scalar_logical_eval_frame *frame
) {
    struct scalar_arithmetic_value *left = NULL;
    int rc = MYLITE_OK;

    if (value_stack == NULL || frame == NULL || value_stack->count == 0U) {
        set_runtime_error(database, "invalid scalar logical evaluation stack");
        return MYLITE_ERROR;
    }

    left = &value_stack->items[value_stack->count - 1U];
    if (frame->operator_kind == MYLITE_SQL_AST_OPERATOR_LOGICAL_AND && !left->is_null &&
        left->integer == 0) {
        left->integer = 0;
        return MYLITE_OK;
    }
    if (frame->operator_kind == MYLITE_SQL_AST_OPERATOR_LOGICAL_OR && !left->is_null &&
        left->integer != 0) {
        left->integer = 1;
        return MYLITE_OK;
    }
    if (frame->operator_kind == MYLITE_SQL_AST_OPERATOR_LOGICAL_XOR && left->is_null) {
        return MYLITE_OK;
    }

    rc = scalar_logical_eval_stack_push(
        database,
        expression_stack,
        SCALAR_LOGICAL_EVAL_APPLY_LOGICAL,
        NULL,
        frame->operator_kind
    );
    if (rc == MYLITE_OK) {
        rc = scalar_logical_eval_stack_push(
            database,
            expression_stack,
            SCALAR_LOGICAL_EVAL_ENTER,
            frame->expression,
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    return rc;
}

static int evaluate_scalar_logical_enter_frame(
    struct mylite_db *database,
    struct scalar_logical_eval_stack *expression_stack,
    struct scalar_arithmetic_value_stack *value_stack,
    const struct mylite_sql_ast_node *expression
) {
    enum mylite_sql_ast_operator operator_kind = MYLITE_SQL_AST_OPERATOR_NONE;

    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_scalar_logical_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        return evaluate_scalar_logical_enter_unary_frame(
            database,
            expression_stack,
            value_stack,
            expression
        );
    }
    if (expression->kind != MYLITE_SQL_AST_BINARY_EXPRESSION) {
        return evaluate_scalar_logical_enter_arithmetic_frame(database, value_stack, expression);
    }

    operator_kind = mylite_sql_ast_node_operator(expression);
    if (is_scalar_logical_operator(operator_kind)) {
        return evaluate_scalar_logical_enter_logical_frame(
            database,
            expression_stack,
            expression,
            operator_kind
        );
    }
    if (is_scalar_comparison_operator(operator_kind)) {
        return evaluate_scalar_logical_enter_comparison_frame(
            database,
            expression_stack,
            expression,
            operator_kind
        );
    }
    if (is_scalar_is_operator(operator_kind)) {
        return evaluate_scalar_logical_enter_is_frame(
            database,
            expression_stack,
            expression,
            operator_kind
        );
    }

    return evaluate_scalar_logical_enter_arithmetic_frame(database, value_stack, expression);
}

static int evaluate_scalar_logical_enter_unary_frame(
    struct mylite_db *database,
    struct scalar_logical_eval_stack *expression_stack,
    struct scalar_arithmetic_value_stack *value_stack,
    const struct mylite_sql_ast_node *expression
) {
    enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);
    int rc = MYLITE_OK;

    if (operator_kind != MYLITE_SQL_AST_OPERATOR_LOGICAL_NOT) {
        return evaluate_scalar_logical_enter_arithmetic_frame(database, value_stack, expression);
    }

    rc = scalar_logical_eval_stack_push(
        database,
        expression_stack,
        SCALAR_LOGICAL_EVAL_APPLY_NOT,
        NULL,
        operator_kind
    );
    if (rc == MYLITE_OK) {
        rc = scalar_logical_eval_stack_push(
            database,
            expression_stack,
            SCALAR_LOGICAL_EVAL_ENTER,
            child_at(expression, 0U),
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    return rc;
}

static int evaluate_scalar_logical_enter_logical_frame(
    struct mylite_db *database,
    struct scalar_logical_eval_stack *expression_stack,
    const struct mylite_sql_ast_node *expression,
    enum mylite_sql_ast_operator operator_kind
) {
    int rc = scalar_logical_eval_stack_push(
        database,
        expression_stack,
        SCALAR_LOGICAL_EVAL_LOGICAL_SHORT_CIRCUIT_OR_ENTER_RIGHT,
        child_at(expression, 1U),
        operator_kind
    );

    if (rc == MYLITE_OK) {
        rc = scalar_logical_eval_stack_push(
            database,
            expression_stack,
            SCALAR_LOGICAL_EVAL_ENTER,
            child_at(expression, 0U),
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    return rc;
}

static int evaluate_scalar_logical_enter_comparison_frame(
    struct mylite_db *database,
    struct scalar_logical_eval_stack *expression_stack,
    const struct mylite_sql_ast_node *expression,
    enum mylite_sql_ast_operator operator_kind
) {
    int rc = MYLITE_OK;

    if (operator_kind == MYLITE_SQL_AST_OPERATOR_NULL_SAFE_EQUAL) {
        return evaluate_scalar_logical_enter_null_safe_comparison_frame(
            database,
            expression_stack,
            expression,
            operator_kind
        );
    }

    rc = scalar_logical_eval_stack_push(
        database,
        expression_stack,
        SCALAR_LOGICAL_EVAL_COMPARISON_SHORT_CIRCUIT_OR_ENTER_RIGHT,
        child_at(expression, 1U),
        operator_kind
    );
    if (rc == MYLITE_OK) {
        rc = scalar_logical_eval_stack_push(
            database,
            expression_stack,
            SCALAR_LOGICAL_EVAL_ENTER,
            child_at(expression, 0U),
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    return rc;
}

static int evaluate_scalar_logical_enter_is_frame(
    struct mylite_db *database,
    struct scalar_logical_eval_stack *expression_stack,
    const struct mylite_sql_ast_node *expression,
    enum mylite_sql_ast_operator operator_kind
) {
    int rc = scalar_logical_eval_stack_push(
        database,
        expression_stack,
        SCALAR_LOGICAL_EVAL_APPLY_IS,
        NULL,
        operator_kind
    );

    if (rc == MYLITE_OK) {
        rc = scalar_logical_eval_stack_push(
            database,
            expression_stack,
            SCALAR_LOGICAL_EVAL_ENTER,
            child_at(expression, 0U),
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    return rc;
}

static int evaluate_scalar_logical_enter_null_safe_comparison_frame(
    struct mylite_db *database,
    struct scalar_logical_eval_stack *expression_stack,
    const struct mylite_sql_ast_node *expression,
    enum mylite_sql_ast_operator operator_kind
) {
    int rc = scalar_logical_eval_stack_push(
        database,
        expression_stack,
        SCALAR_LOGICAL_EVAL_APPLY_COMPARISON,
        NULL,
        operator_kind
    );

    if (rc == MYLITE_OK) {
        rc = scalar_logical_eval_stack_push(
            database,
            expression_stack,
            SCALAR_LOGICAL_EVAL_ENTER,
            child_at(expression, 1U),
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    if (rc == MYLITE_OK) {
        rc = scalar_logical_eval_stack_push(
            database,
            expression_stack,
            SCALAR_LOGICAL_EVAL_ENTER,
            child_at(expression, 0U),
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    return rc;
}

static int evaluate_scalar_logical_enter_arithmetic_frame(
    struct mylite_db *database,
    struct scalar_arithmetic_value_stack *value_stack,
    const struct mylite_sql_ast_node *expression
) {
    struct scalar_arithmetic_value value = {.is_null = false, .integer = 0};
    int rc = evaluate_scalar_arithmetic_expression(database, expression, &value);

    if (rc == MYLITE_OK) {
        rc = scalar_arithmetic_value_stack_push(database, value_stack, value);
    }
    return rc;
}

static int scalar_logical_eval_stack_push(
    struct mylite_db *database,
    struct scalar_logical_eval_stack *stack,
    enum scalar_logical_eval_frame_kind kind,
    const struct mylite_sql_ast_node *expression,
    enum mylite_sql_ast_operator operator_kind
) {
    struct scalar_logical_eval_frame *items = NULL;
    size_t capacity = 0U;

    if (stack == NULL) {
        return MYLITE_MISUSE;
    }
    if (stack->count == stack->capacity) {
        capacity = stack->capacity == 0U ? if_stack_initial_capacity : stack->capacity * 2U;
        if (capacity < stack->capacity || capacity > SIZE_MAX / sizeof(*items)) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        items = (struct scalar_logical_eval_frame *)
            realloc((void *)stack->items, capacity * sizeof(*items));
        if (items == NULL) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        stack->items = items;
        stack->capacity = capacity;
    }

    stack->items[stack->count] = (struct scalar_logical_eval_frame){
        .kind = kind,
        .expression = expression,
        .operator_kind = operator_kind,
    };
    ++stack->count;
    return MYLITE_OK;
}

static void scalar_logical_eval_stack_deinit(struct scalar_logical_eval_stack *stack) {
    if (stack == NULL) {
        return;
    }

    free((void *)stack->items);
    *stack = (struct scalar_logical_eval_stack){0};
}

static int scalar_comparison_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct scalar_arithmetic_value value = {.is_null = false, .integer = 0};
    int written = 0;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    rc = evaluate_scalar_comparison_expression(database, expression, &value);
    if (rc != MYLITE_OK || value.is_null) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    written =
        snprintf(out_cell->integer_text, sizeof(out_cell->integer_text), "%" PRId64, value.integer);
    if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
        set_runtime_error(database, "failed to format scalar comparison value");
        return MYLITE_ERROR;
    }

    out_cell->value = out_cell->integer_text;
    out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
    return MYLITE_OK;
}

static int evaluate_scalar_comparison_expression(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_arithmetic_value *out_value
) {
    struct scalar_comparison_eval_stack expression_stack = {0};
    struct scalar_arithmetic_value_stack value_stack = {0};
    int rc = MYLITE_OK;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct scalar_arithmetic_value){.is_null = false, .integer = 0};
    if (!is_scalar_comparison_projection_expression(expression)) {
        set_scalar_comparison_unsupported_error(database);
        return MYLITE_ERROR;
    }
    rc = scalar_comparison_eval_stack_push(
        database,
        &expression_stack,
        SCALAR_COMPARISON_EVAL_ENTER,
        expression,
        MYLITE_SQL_AST_OPERATOR_NONE
    );
    while (rc == MYLITE_OK && expression_stack.count != 0U) {
        struct scalar_comparison_eval_frame frame =
            expression_stack.items[--expression_stack.count];

        rc = evaluate_scalar_comparison_frame(database, &expression_stack, &value_stack, &frame);
    }
    if (rc == MYLITE_OK) {
        rc = finish_scalar_arithmetic_result(database, &value_stack, out_value);
    }
    scalar_comparison_eval_stack_deinit(&expression_stack);
    scalar_arithmetic_value_stack_deinit(&value_stack);
    return rc;
}

static int evaluate_scalar_comparison_frame(
    struct mylite_db *database,
    struct scalar_comparison_eval_stack *expression_stack,
    struct scalar_arithmetic_value_stack *value_stack,
    const struct scalar_comparison_eval_frame *frame
) {
    if (frame == NULL) {
        return MYLITE_MISUSE;
    }
    if (frame->kind == SCALAR_COMPARISON_EVAL_APPLY) {
        return evaluate_scalar_comparison_apply_frame(database, value_stack, frame->operator_kind);
    }
    if (frame->kind == SCALAR_COMPARISON_EVAL_SHORT_CIRCUIT_OR_ENTER_RIGHT) {
        return evaluate_scalar_comparison_short_circuit_or_enter_right_frame(
            database,
            expression_stack,
            value_stack,
            frame
        );
    }
    return evaluate_scalar_comparison_enter_frame(
        database,
        expression_stack,
        value_stack,
        frame->expression
    );
}

static int evaluate_scalar_comparison_apply_frame(
    struct mylite_db *database,
    struct scalar_arithmetic_value_stack *value_stack,
    enum mylite_sql_ast_operator operator_kind
) {
    struct scalar_arithmetic_value left = {.is_null = false, .integer = 0};
    struct scalar_arithmetic_value right = {.is_null = false, .integer = 0};
    struct scalar_arithmetic_value result = {.is_null = false, .integer = 0};
    struct scalar_comparison_operation operation = {
        .operator_kind = operator_kind,
        .left = 0,
        .right = 0,
    };

    if (!scalar_arithmetic_value_stack_pop(value_stack, &right) ||
        !scalar_arithmetic_value_stack_pop(value_stack, &left)) {
        set_runtime_error(database, "invalid scalar comparison evaluation stack");
        return MYLITE_ERROR;
    }
    if (left.division_by_zero_warning_count > SIZE_MAX - right.division_by_zero_warning_count) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    result.division_by_zero_warning_count =
        left.division_by_zero_warning_count + right.division_by_zero_warning_count;

    if (operator_kind == MYLITE_SQL_AST_OPERATOR_NULL_SAFE_EQUAL) {
        if (left.is_null || right.is_null) {
            result.integer = left.is_null == right.is_null ? 1 : 0;
            return scalar_arithmetic_value_stack_push(database, value_stack, result);
        }
        result.integer = left.integer == right.integer ? 1 : 0;
        return scalar_arithmetic_value_stack_push(database, value_stack, result);
    }
    if (left.is_null || right.is_null) {
        result.is_null = true;
        return scalar_arithmetic_value_stack_push(database, value_stack, result);
    }
    if (!is_scalar_comparison_operator(operator_kind)) {
        set_scalar_comparison_unsupported_error(database);
        return MYLITE_ERROR;
    }

    operation.left = left.integer;
    operation.right = right.integer;
    if (scalar_comparison_result_is_true(&operation)) {
        result.integer = 1;
    } else {
        result.integer = 0;
    }
    return scalar_arithmetic_value_stack_push(database, value_stack, result);
}

static int evaluate_scalar_comparison_short_circuit_or_enter_right_frame(
    struct mylite_db *database,
    struct scalar_comparison_eval_stack *expression_stack,
    const struct scalar_arithmetic_value_stack *value_stack,
    const struct scalar_comparison_eval_frame *frame
) {
    const struct scalar_arithmetic_value *left = NULL;
    int rc = MYLITE_OK;

    if (value_stack == NULL || frame == NULL || value_stack->count == 0U) {
        set_runtime_error(database, "invalid scalar comparison evaluation stack");
        return MYLITE_ERROR;
    }

    left = &value_stack->items[value_stack->count - 1U];
    if (left->is_null) {
        return MYLITE_OK;
    }

    rc = scalar_comparison_eval_stack_push(
        database,
        expression_stack,
        SCALAR_COMPARISON_EVAL_APPLY,
        NULL,
        frame->operator_kind
    );
    if (rc == MYLITE_OK) {
        rc = scalar_comparison_eval_stack_push(
            database,
            expression_stack,
            SCALAR_COMPARISON_EVAL_ENTER,
            frame->expression,
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    return rc;
}

static int evaluate_scalar_comparison_enter_frame(
    struct mylite_db *database,
    struct scalar_comparison_eval_stack *expression_stack,
    struct scalar_arithmetic_value_stack *value_stack,
    const struct mylite_sql_ast_node *expression
) {
    enum mylite_sql_ast_operator operator_kind = MYLITE_SQL_AST_OPERATOR_NONE;
    struct scalar_arithmetic_value value = {.is_null = false, .integer = 0};
    int rc = MYLITE_OK;

    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_scalar_comparison_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (expression->kind != MYLITE_SQL_AST_BINARY_EXPRESSION) {
        rc = evaluate_scalar_arithmetic_expression(database, expression, &value);
        if (rc == MYLITE_OK) {
            rc = scalar_arithmetic_value_stack_push(database, value_stack, value);
        }
        return rc;
    }

    operator_kind = mylite_sql_ast_node_operator(expression);
    if (!is_scalar_comparison_operator(operator_kind)) {
        rc = evaluate_scalar_arithmetic_expression(database, expression, &value);
        if (rc == MYLITE_OK) {
            rc = scalar_arithmetic_value_stack_push(database, value_stack, value);
        }
        return rc;
    }

    if (operator_kind != MYLITE_SQL_AST_OPERATOR_NULL_SAFE_EQUAL) {
        rc = scalar_comparison_eval_stack_push(
            database,
            expression_stack,
            SCALAR_COMPARISON_EVAL_SHORT_CIRCUIT_OR_ENTER_RIGHT,
            child_at(expression, 1U),
            operator_kind
        );
        if (rc == MYLITE_OK) {
            rc = scalar_comparison_eval_stack_push(
                database,
                expression_stack,
                SCALAR_COMPARISON_EVAL_ENTER,
                child_at(expression, 0U),
                MYLITE_SQL_AST_OPERATOR_NONE
            );
        }
        return rc;
    }

    rc = scalar_comparison_eval_stack_push(
        database,
        expression_stack,
        SCALAR_COMPARISON_EVAL_APPLY,
        NULL,
        operator_kind
    );
    if (rc == MYLITE_OK) {
        rc = scalar_comparison_eval_stack_push(
            database,
            expression_stack,
            SCALAR_COMPARISON_EVAL_ENTER,
            child_at(expression, 1U),
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    if (rc == MYLITE_OK) {
        rc = scalar_comparison_eval_stack_push(
            database,
            expression_stack,
            SCALAR_COMPARISON_EVAL_ENTER,
            child_at(expression, 0U),
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    return rc;
}

static bool scalar_comparison_result_is_true(const struct scalar_comparison_operation *operation) {
    if (operation == NULL) {
        return false;
    }
    switch (operation->operator_kind) {
    case MYLITE_SQL_AST_OPERATOR_EQUAL:
        return operation->left == operation->right;
    case MYLITE_SQL_AST_OPERATOR_NOT_EQUAL:
        return operation->left != operation->right;
    case MYLITE_SQL_AST_OPERATOR_LESS:
        return operation->left < operation->right;
    case MYLITE_SQL_AST_OPERATOR_LESS_EQUAL:
        return operation->left <= operation->right;
    case MYLITE_SQL_AST_OPERATOR_GREATER:
        return operation->left > operation->right;
    case MYLITE_SQL_AST_OPERATOR_GREATER_EQUAL:
        return operation->left >= operation->right;
    default:
        return false;
    }
}

static int scalar_comparison_eval_stack_push(
    struct mylite_db *database,
    struct scalar_comparison_eval_stack *stack,
    enum scalar_comparison_eval_frame_kind kind,
    const struct mylite_sql_ast_node *expression,
    enum mylite_sql_ast_operator operator_kind
) {
    struct scalar_comparison_eval_frame *items = NULL;
    size_t capacity = 0U;

    if (stack == NULL) {
        return MYLITE_MISUSE;
    }
    if (stack->count == stack->capacity) {
        capacity = stack->capacity == 0U ? if_stack_initial_capacity : stack->capacity * 2U;
        if (capacity < stack->capacity || capacity > SIZE_MAX / sizeof(*items)) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        items = (struct scalar_comparison_eval_frame *)
            realloc((void *)stack->items, capacity * sizeof(*items));
        if (items == NULL) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        stack->items = items;
        stack->capacity = capacity;
    }

    stack->items[stack->count] = (struct scalar_comparison_eval_frame){
        .kind = kind,
        .expression = expression,
        .operator_kind = operator_kind,
    };
    ++stack->count;
    return MYLITE_OK;
}

static void scalar_comparison_eval_stack_deinit(struct scalar_comparison_eval_stack *stack) {
    if (stack == NULL) {
        return;
    }

    free((void *)stack->items);
    *stack = (struct scalar_comparison_eval_stack){0};
}

static int scalar_arithmetic_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct session_scalar_cell *out_cell
) {
    struct scalar_arithmetic_value value = {.is_null = false, .integer = 0};
    int written = 0;
    int rc = MYLITE_OK;

    if (out_cell == NULL) {
        return MYLITE_MISUSE;
    }
    *out_cell = (struct session_scalar_cell){0};
    rc = evaluate_scalar_arithmetic_expression(database, expression, &value);
    if (rc != MYLITE_OK || value.is_null) {
        if (rc == MYLITE_OK) {
            out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
        }
        return rc;
    }

    written =
        snprintf(out_cell->integer_text, sizeof(out_cell->integer_text), "%" PRId64, value.integer);
    if (written < 0 || (size_t)written >= sizeof(out_cell->integer_text)) {
        set_runtime_error(database, "failed to format scalar arithmetic value");
        return MYLITE_ERROR;
    }

    out_cell->value = out_cell->integer_text;
    out_cell->staged_division_by_zero_warning_count = value.division_by_zero_warning_count;
    return MYLITE_OK;
}

static int evaluate_scalar_arithmetic_expression(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_arithmetic_value *out_value
) {
    struct scalar_arithmetic_eval_stack expression_stack = {0};
    struct scalar_arithmetic_value_stack value_stack = {0};
    int rc = MYLITE_OK;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct scalar_arithmetic_value){.is_null = false, .integer = 0};
    if (expression == NULL) {
        set_scalar_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }
    rc = scalar_arithmetic_eval_stack_push(
        database,
        &expression_stack,
        SCALAR_ARITHMETIC_EVAL_ENTER,
        expression,
        MYLITE_SQL_AST_OPERATOR_NONE
    );
    while (rc == MYLITE_OK && expression_stack.count != 0U) {
        struct scalar_arithmetic_eval_frame frame =
            expression_stack.items[--expression_stack.count];

        rc = evaluate_scalar_arithmetic_frame(database, &expression_stack, &value_stack, &frame);
    }
    if (rc == MYLITE_OK) {
        rc = finish_scalar_arithmetic_result(database, &value_stack, out_value);
    }
    scalar_arithmetic_eval_stack_deinit(&expression_stack);
    scalar_arithmetic_value_stack_deinit(&value_stack);
    return rc;
}

static int evaluate_scalar_arithmetic_frame(
    struct mylite_db *database,
    struct scalar_arithmetic_eval_stack *expression_stack,
    struct scalar_arithmetic_value_stack *value_stack,
    const struct scalar_arithmetic_eval_frame *frame
) {
    if (frame == NULL) {
        return MYLITE_MISUSE;
    }
    if (frame->kind == SCALAR_ARITHMETIC_EVAL_APPLY) {
        return evaluate_scalar_arithmetic_apply_frame(database, value_stack, frame->operator_kind);
    }
    if (frame->kind == SCALAR_ARITHMETIC_EVAL_APPLY_UNARY) {
        return evaluate_scalar_arithmetic_apply_unary_frame(
            database,
            value_stack,
            frame->operator_kind
        );
    }
    return evaluate_scalar_arithmetic_enter_frame(
        database,
        expression_stack,
        value_stack,
        frame->expression
    );
}

static int evaluate_scalar_arithmetic_apply_frame(
    struct mylite_db *database,
    struct scalar_arithmetic_value_stack *value_stack,
    enum mylite_sql_ast_operator operator_kind
) {
    struct scalar_arithmetic_value left = {.is_null = false, .integer = 0};
    struct scalar_arithmetic_value right = {.is_null = false, .integer = 0};
    struct scalar_arithmetic_value result = {.is_null = false, .integer = 0};
    struct scalar_arithmetic_operation operation = {
        .operator_kind = operator_kind,
        .left = 0,
        .right = 0,
    };
    int rc = MYLITE_OK;

    if (!scalar_arithmetic_value_stack_pop(value_stack, &right) ||
        !scalar_arithmetic_value_stack_pop(value_stack, &left)) {
        set_runtime_error(database, "invalid scalar arithmetic evaluation stack");
        return MYLITE_ERROR;
    }
    if (left.division_by_zero_warning_count > SIZE_MAX - right.division_by_zero_warning_count) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    result.division_by_zero_warning_count =
        left.division_by_zero_warning_count + right.division_by_zero_warning_count;
    if (left.is_null || right.is_null) {
        result.is_null = true;
        return scalar_arithmetic_value_stack_push(database, value_stack, result);
    }
    if ((operator_kind == MYLITE_SQL_AST_OPERATOR_MODULO ||
         operator_kind == MYLITE_SQL_AST_OPERATOR_INTEGER_DIVIDE) &&
        right.integer == 0) {
        result.is_null = true;
        if (result.division_by_zero_warning_count == SIZE_MAX) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        ++result.division_by_zero_warning_count;
        return scalar_arithmetic_value_stack_push(database, value_stack, result);
    }

    operation.left = left.integer;
    operation.right = right.integer;
    rc = apply_scalar_arithmetic_operator(database, &operation, &result.integer);
    if (rc == MYLITE_OK) {
        rc = scalar_arithmetic_value_stack_push(database, value_stack, result);
    }
    return rc;
}

static int evaluate_scalar_arithmetic_apply_unary_frame(
    struct mylite_db *database,
    struct scalar_arithmetic_value_stack *value_stack,
    enum mylite_sql_ast_operator operator_kind
) {
    struct scalar_arithmetic_value value = {.is_null = false, .integer = 0};
    int64_t result = 0;

    if (!scalar_arithmetic_value_stack_pop(value_stack, &value)) {
        set_runtime_error(database, "invalid scalar arithmetic evaluation stack");
        return MYLITE_ERROR;
    }
    if (value.is_null || operator_kind == MYLITE_SQL_AST_OPERATOR_POSITIVE) {
        return scalar_arithmetic_value_stack_push(database, value_stack, value);
    }
    if (operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
        set_scalar_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (checked_int64_negate(value.integer, &result)) {
        set_scalar_arithmetic_overflow_error(database);
        return MYLITE_ERROR;
    }

    value.integer = result;
    return scalar_arithmetic_value_stack_push(database, value_stack, value);
}

static int evaluate_scalar_arithmetic_enter_frame(
    struct mylite_db *database,
    struct scalar_arithmetic_eval_stack *expression_stack,
    struct scalar_arithmetic_value_stack *value_stack,
    const struct mylite_sql_ast_node *expression
) {
    struct scalar_arithmetic_value value = {.is_null = false, .integer = 0};

    expression = unwrap_parenthesized_expression(expression);
    if (expression == NULL) {
        set_scalar_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);
        int rc = MYLITE_OK;

        if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
            operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            set_scalar_arithmetic_unsupported_error(database);
            return MYLITE_ERROR;
        }
        rc = scalar_arithmetic_eval_stack_push(
            database,
            expression_stack,
            SCALAR_ARITHMETIC_EVAL_APPLY_UNARY,
            NULL,
            operator_kind
        );
        if (rc == MYLITE_OK) {
            rc = scalar_arithmetic_eval_stack_push(
                database,
                expression_stack,
                SCALAR_ARITHMETIC_EVAL_ENTER,
                child_at(expression, 0U),
                MYLITE_SQL_AST_OPERATOR_NONE
            );
        }
        return rc;
    }
    if (expression->kind == MYLITE_SQL_AST_MOD_FUNCTION) {
        int rc = MYLITE_OK;

        if (mylite_sql_ast_node_child_count(expression) != 2U) {
            set_scalar_arithmetic_unsupported_error(database);
            return MYLITE_ERROR;
        }
        rc = scalar_arithmetic_eval_stack_push(
            database,
            expression_stack,
            SCALAR_ARITHMETIC_EVAL_APPLY,
            NULL,
            MYLITE_SQL_AST_OPERATOR_MODULO
        );
        if (rc == MYLITE_OK) {
            rc = scalar_arithmetic_eval_stack_push(
                database,
                expression_stack,
                SCALAR_ARITHMETIC_EVAL_ENTER,
                child_at(expression, 1U),
                MYLITE_SQL_AST_OPERATOR_NONE
            );
        }
        if (rc == MYLITE_OK) {
            rc = scalar_arithmetic_eval_stack_push(
                database,
                expression_stack,
                SCALAR_ARITHMETIC_EVAL_ENTER,
                child_at(expression, 0U),
                MYLITE_SQL_AST_OPERATOR_NONE
            );
        }
        return rc;
    }
    if (expression->kind != MYLITE_SQL_AST_BINARY_EXPRESSION) {
        int rc = evaluate_scalar_arithmetic_operand(database, expression, &value);

        if (rc == MYLITE_OK) {
            rc = scalar_arithmetic_value_stack_push(database, value_stack, value);
        }
        return rc;
    }

    enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(expression);

    if (!is_scalar_arithmetic_operator(operator_kind)) {
        set_scalar_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (operator_kind == MYLITE_SQL_AST_OPERATOR_INTEGER_DIVIDE) {
        bool left_operand_short_circuits = false;

        int rc = scalar_arithmetic_div_left_operand_short_circuits(
            database,
            child_at(expression, 0U),
            &left_operand_short_circuits
        );
        if (rc != MYLITE_OK) {
            return rc;
        }
        if (left_operand_short_circuits) {
            value.is_null = true;
            return scalar_arithmetic_value_stack_push(database, value_stack, value);
        }
    }

    int rc = scalar_arithmetic_eval_stack_push(
        database,
        expression_stack,
        SCALAR_ARITHMETIC_EVAL_APPLY,
        NULL,
        operator_kind
    );

    if (rc == MYLITE_OK) {
        rc = scalar_arithmetic_eval_stack_push(
            database,
            expression_stack,
            SCALAR_ARITHMETIC_EVAL_ENTER,
            child_at(expression, 1U),
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    if (rc == MYLITE_OK) {
        rc = scalar_arithmetic_eval_stack_push(
            database,
            expression_stack,
            SCALAR_ARITHMETIC_EVAL_ENTER,
            child_at(expression, 0U),
            MYLITE_SQL_AST_OPERATOR_NONE
        );
    }
    return rc;
}

static int scalar_arithmetic_div_left_operand_short_circuits(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    bool *out_short_circuits
) {
    struct scalar_arithmetic_node_stack stack = {0};
    bool short_circuits = true;
    int rc = MYLITE_OK;

    if (out_short_circuits == NULL) {
        return MYLITE_MISUSE;
    }
    *out_short_circuits = false;
    if (!scalar_arithmetic_node_stack_push(&stack, expression)) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    while (stack.count != 0U && rc == MYLITE_OK && short_circuits) {
        const struct mylite_sql_ast_node *current =
            unwrap_parenthesized_expression(stack.items[--stack.count]);

        rc = scalar_arithmetic_div_short_circuit_visit_node(
            database,
            current,
            &stack,
            &short_circuits
        );
    }
    if (rc == MYLITE_OK) {
        *out_short_circuits = short_circuits;
    }
    scalar_arithmetic_node_stack_deinit(&stack);
    return rc;
}

static int scalar_arithmetic_div_short_circuit_visit_node(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_arithmetic_node_stack *stack,
    bool *out_short_circuits
) {
    enum mylite_sql_ast_operator operator_kind = MYLITE_SQL_AST_OPERATOR_NONE;

    if (expression == NULL || out_short_circuits == NULL) {
        if (out_short_circuits != NULL) {
            *out_short_circuits = false;
        }
        return MYLITE_OK;
    }

    switch (expression->kind) {
    case MYLITE_SQL_AST_LITERAL:
        *out_short_circuits =
            mylite_sql_ast_node_literal_kind(expression) == MYLITE_SQL_AST_LITERAL_NULL;
        return MYLITE_OK;
    case MYLITE_SQL_AST_UNARY_EXPRESSION:
        operator_kind = mylite_sql_ast_node_operator(expression);
        if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
            operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            *out_short_circuits = false;
            return MYLITE_OK;
        }
        return scalar_arithmetic_div_short_circuit_push_child(
            database,
            stack,
            child_at(expression, 0U)
        );
    case MYLITE_SQL_AST_IFNULL_FUNCTION:
        return scalar_arithmetic_div_short_circuit_push_function_arguments(
            database,
            stack,
            expression,
            out_short_circuits
        );
    case MYLITE_SQL_AST_COALESCE_FUNCTION:
    case MYLITE_SQL_AST_NULLIF_FUNCTION:
        return scalar_arithmetic_div_short_circuit_push_child(
            database,
            stack,
            child_at(expression, 0U)
        );
    case MYLITE_SQL_AST_FUNCTION_ARGUMENT_LIST:
        return scalar_arithmetic_div_short_circuit_push_function_arguments(
            database,
            stack,
            expression,
            out_short_circuits
        );
    default:
        *out_short_circuits = false;
        return MYLITE_OK;
    }
}

static int scalar_arithmetic_div_short_circuit_push_child(
    struct mylite_db *database,
    struct scalar_arithmetic_node_stack *stack,
    const struct mylite_sql_ast_node *expression
) {
    if (!scalar_arithmetic_node_stack_push(stack, expression)) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    return MYLITE_OK;
}

static int scalar_arithmetic_div_short_circuit_push_function_arguments(
    struct mylite_db *database,
    struct scalar_arithmetic_node_stack *stack,
    const struct mylite_sql_ast_node *arguments,
    bool *out_short_circuits
) {
    size_t child_count = mylite_sql_ast_node_child_count(arguments);

    if (child_count == 0U) {
        *out_short_circuits = false;
        return MYLITE_OK;
    }
    for (size_t child_index = 0U; child_index < child_count; ++child_index) {
        int rc = scalar_arithmetic_div_short_circuit_push_child(
            database,
            stack,
            child_at(arguments, child_index)
        );

        if (rc != MYLITE_OK) {
            return rc;
        }
    }
    return MYLITE_OK;
}

static int finish_scalar_arithmetic_result(
    struct mylite_db *database,
    struct scalar_arithmetic_value_stack *value_stack,
    struct scalar_arithmetic_value *out_value
) {
    if (!scalar_arithmetic_value_stack_pop(value_stack, out_value)) {
        set_runtime_error(database, "missing scalar arithmetic result");
        return MYLITE_ERROR;
    }
    if (value_stack->count != 0U) {
        set_runtime_error(database, "invalid scalar arithmetic result stack");
        return MYLITE_ERROR;
    }
    return MYLITE_OK;
}

static int evaluate_scalar_arithmetic_operand(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *expression,
    struct scalar_arithmetic_value *out_value
) {
    struct session_scalar_cell cell = {0};
    int rc = MYLITE_OK;

    expression = unwrap_parenthesized_expression(expression);
    if (!is_scalar_value_projection_expression(expression)) {
        set_scalar_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if ((expression->kind == MYLITE_SQL_AST_LITERAL ||
         expression->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) &&
        !is_if_non_function_value_expression(expression)) {
        set_scalar_arithmetic_operand_out_of_range_error(database);
        return MYLITE_ERROR;
    }

    switch (expression->kind) {
    case MYLITE_SQL_AST_LITERAL:
    case MYLITE_SQL_AST_UNARY_EXPRESSION:
        rc = literal_projection_value(database, expression, &cell);
        break;
    case MYLITE_SQL_AST_IF_FUNCTION:
        rc = if_function_value(database, expression, &cell);
        break;
    case MYLITE_SQL_AST_IFNULL_FUNCTION:
        rc = ifnull_function_value(database, expression, &cell);
        break;
    case MYLITE_SQL_AST_COALESCE_FUNCTION:
        rc = coalesce_function_value(database, expression, &cell);
        break;
    case MYLITE_SQL_AST_NULLIF_FUNCTION:
        rc = nullif_function_value(database, expression, &cell);
        break;
    case MYLITE_SQL_AST_ISNULL_FUNCTION:
        rc = isnull_function_value(database, expression, &cell);
        break;
    default:
        set_scalar_arithmetic_unsupported_error(database);
        rc = MYLITE_ERROR;
        break;
    }
    if (rc == MYLITE_OK) {
        rc = parse_scalar_arithmetic_operand(database, &cell, out_value);
    }
    return rc;
}

static int parse_scalar_arithmetic_operand(
    struct mylite_db *database,
    const struct session_scalar_cell *cell,
    struct scalar_arithmetic_value *out_value
) {
    static const uint64_t int64_min_magnitude = 9223372036854775808ULL;
    const char *text = cell == NULL ? NULL : cell->value;
    uint64_t limit = (uint64_t)INT64_MAX;
    uint64_t magnitude = 0U;
    bool is_negative = false;

    if (out_value == NULL) {
        return MYLITE_MISUSE;
    }
    *out_value = (struct scalar_arithmetic_value){.is_null = false, .integer = 0};
    out_value->division_by_zero_warning_count =
        cell == NULL ? 0U : cell->staged_division_by_zero_warning_count;
    if (text == NULL) {
        out_value->is_null = true;
        return MYLITE_OK;
    }
    if (text[0] == '-') {
        is_negative = true;
        limit = int64_min_magnitude;
        ++text;
    }
    if (text[0] == '\0') {
        set_scalar_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }

    for (size_t index = 0U; text[index] != '\0'; ++index) {
        unsigned char byte = (unsigned char)text[index];
        uint64_t digit = 0U;

        if (byte < '0' || byte > '9') {
            set_scalar_arithmetic_unsupported_error(database);
            return MYLITE_ERROR;
        }
        digit = (uint64_t)(byte - '0');
        if (magnitude > (limit - digit) / decimal_base) {
            set_scalar_arithmetic_operand_out_of_range_error(database);
            return MYLITE_ERROR;
        }
        magnitude = (magnitude * decimal_base) + digit;
    }

    if (is_negative && magnitude == int64_min_magnitude) {
        out_value->integer = INT64_MIN;
    } else if (is_negative && magnitude != 0U) {
        out_value->integer = -(int64_t)magnitude;
    } else {
        out_value->integer = (int64_t)magnitude;
    }
    return MYLITE_OK;
}

static int apply_scalar_arithmetic_operator(
    struct mylite_db *database,
    const struct scalar_arithmetic_operation *operation,
    int64_t *out_result
) {
    bool overflow = false;

    if (operation == NULL || out_result == NULL) {
        return MYLITE_MISUSE;
    }
    switch (operation->operator_kind) {
    case MYLITE_SQL_AST_OPERATOR_ADD:
        overflow = checked_int64_add(operation->left, operation->right, out_result);
        break;
    case MYLITE_SQL_AST_OPERATOR_SUBTRACT:
        overflow = checked_int64_subtract(operation->left, operation->right, out_result);
        break;
    case MYLITE_SQL_AST_OPERATOR_MULTIPLY:
        overflow = checked_int64_multiply(operation->left, operation->right, out_result);
        break;
    case MYLITE_SQL_AST_OPERATOR_MODULO:
        overflow = checked_int64_modulo(operation->left, operation->right, out_result);
        break;
    case MYLITE_SQL_AST_OPERATOR_INTEGER_DIVIDE:
        overflow = checked_int64_divide(operation->left, operation->right, out_result);
        break;
    default:
        set_scalar_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }
    if (overflow) {
        set_scalar_arithmetic_overflow_error(database);
        return MYLITE_ERROR;
    }
    return MYLITE_OK;
}

static int scalar_arithmetic_eval_stack_push(
    struct mylite_db *database,
    struct scalar_arithmetic_eval_stack *stack,
    enum scalar_arithmetic_eval_frame_kind kind,
    const struct mylite_sql_ast_node *expression,
    enum mylite_sql_ast_operator operator_kind
) {
    struct scalar_arithmetic_eval_frame *items = NULL;
    size_t capacity = 0U;

    if (stack == NULL) {
        return MYLITE_MISUSE;
    }
    if (stack->count == stack->capacity) {
        capacity = stack->capacity == 0U ? if_stack_initial_capacity : stack->capacity * 2U;
        if (capacity < stack->capacity || capacity > SIZE_MAX / sizeof(*items)) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        items = (struct scalar_arithmetic_eval_frame *)
            realloc((void *)stack->items, capacity * sizeof(*items));
        if (items == NULL) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        stack->items = items;
        stack->capacity = capacity;
    }

    stack->items[stack->count] = (struct scalar_arithmetic_eval_frame){
        .kind = kind,
        .expression = expression,
        .operator_kind = operator_kind,
    };
    ++stack->count;
    return MYLITE_OK;
}

static void scalar_arithmetic_eval_stack_deinit(struct scalar_arithmetic_eval_stack *stack) {
    if (stack == NULL) {
        return;
    }

    free((void *)stack->items);
    *stack = (struct scalar_arithmetic_eval_stack){0};
}

static int scalar_arithmetic_value_stack_push(
    struct mylite_db *database,
    struct scalar_arithmetic_value_stack *stack,
    struct scalar_arithmetic_value value
) {
    struct scalar_arithmetic_value *items = NULL;
    size_t capacity = 0U;

    if (stack == NULL) {
        return MYLITE_MISUSE;
    }
    if (stack->count == stack->capacity) {
        capacity = stack->capacity == 0U ? if_stack_initial_capacity : stack->capacity * 2U;
        if (capacity < stack->capacity || capacity > SIZE_MAX / sizeof(*items)) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        items = (struct scalar_arithmetic_value *)
            realloc((void *)stack->items, capacity * sizeof(*items));
        if (items == NULL) {
            set_nomem_error(database);
            return MYLITE_NOMEM;
        }
        stack->items = items;
        stack->capacity = capacity;
    }

    stack->items[stack->count] = value;
    ++stack->count;
    return MYLITE_OK;
}

static bool scalar_arithmetic_value_stack_pop(
    struct scalar_arithmetic_value_stack *stack,
    struct scalar_arithmetic_value *out_value
) {
    if (stack == NULL || out_value == NULL || stack->count == 0U) {
        return false;
    }

    --stack->count;
    *out_value = stack->items[stack->count];
    return true;
}

static void scalar_arithmetic_value_stack_deinit(struct scalar_arithmetic_value_stack *stack) {
    if (stack == NULL) {
        return;
    }

    free((void *)stack->items);
    *stack = (struct scalar_arithmetic_value_stack){0};
}

static bool scalar_arithmetic_node_stack_push(
    struct scalar_arithmetic_node_stack *stack,
    const struct mylite_sql_ast_node *expression
) {
    const struct mylite_sql_ast_node **items = NULL;
    size_t capacity = 0U;

    if (stack == NULL) {
        return false;
    }
    if (stack->count == stack->capacity) {
        capacity = stack->capacity == 0U ? if_stack_initial_capacity : stack->capacity * 2U;
        if (capacity < stack->capacity || capacity > SIZE_MAX / sizeof(*items)) {
            return false;
        }
        items = (const struct mylite_sql_ast_node **)
            realloc((void *)stack->items, capacity * sizeof(*items));
        if (items == NULL) {
            return false;
        }
        stack->items = items;
        stack->capacity = capacity;
    }

    stack->items[stack->count] = expression;
    ++stack->count;
    return true;
}

static void scalar_arithmetic_node_stack_deinit(struct scalar_arithmetic_node_stack *stack) {
    if (stack == NULL) {
        return;
    }

    free((void *)stack->items);
    *stack = (struct scalar_arithmetic_node_stack){0};
}

static bool checked_int64_add(int64_t left, int64_t right, int64_t *out_result) {
    if ((right > 0 && left > INT64_MAX - right) || (right < 0 && left < INT64_MIN - right)) {
        return true;
    }

    *out_result = left + right;
    return false;
}

static bool checked_int64_subtract(int64_t left, int64_t right, int64_t *out_result) {
    if ((right < 0 && left > INT64_MAX + right) || (right > 0 && left < INT64_MIN + right)) {
        return true;
    }

    *out_result = left - right;
    return false;
}

static bool checked_int64_multiply(int64_t left, int64_t right, int64_t *out_result) {
    if (left == 0 || right == 0) {
        *out_result = 0;
        return false;
    }
    if ((left == INT64_MIN && right == -1) || (right == INT64_MIN && left == -1)) {
        return true;
    }
    if (left > 0) {
        if (right > 0) {
            if (left > INT64_MAX / right) {
                return true;
            }
        } else if (right < INT64_MIN / left) {
            return true;
        }
    } else if (right > 0) {
        if (left < INT64_MIN / right) {
            return true;
        }
    } else if (left < INT64_MAX / right) {
        return true;
    }

    *out_result = left * right;
    return false;
}

static bool checked_int64_modulo(int64_t left, int64_t right, int64_t *out_result) {
    if (left == INT64_MIN && right == -1) {
        *out_result = 0;
        return false;
    }

    *out_result = left % right;
    return false;
}

static bool checked_int64_divide(int64_t left, int64_t right, int64_t *out_result) {
    if (left == INT64_MIN && (right == 1 || right == -1)) {
        return true;
    }

    *out_result = left / right;
    return false;
}

static bool checked_int64_negate(int64_t value, int64_t *out_result) {
    if (value == INT64_MIN) {
        return true;
    }

    *out_result = -value;
    return false;
}

