static int enum_type_info_for_logical_type(
    struct mylite_db *database,
    const char *logical_type,
    const char *unsupported_message,
    struct enum_type_info *out_info
) {
    size_t logical_length = logical_type == NULL ? 0U : strlen(logical_type);
    size_t index = enum_logical_prefix_length;
    int rc = MYLITE_OK;

    if (logical_type == NULL || unsupported_message == NULL || out_info == NULL ||
        logical_length <= enum_logical_syntax_overhead ||
        strncmp(logical_type, "ENUM(", enum_logical_prefix_length) != 0 ||
        logical_type[logical_length - 1U] != ')') {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }

    *out_info = (struct enum_type_info){0};
    while (rc == MYLITE_OK && index < logical_length - 1U) {
        if (out_info->label_count >= enum_label_count_capacity) {
            set_unsupported_error(database, unsupported_message);
            return MYLITE_ERROR;
        }
        rc = parse_enum_descriptor_label(
            database,
            logical_type,
            logical_length - 1U,
            &index,
            out_info
        );
        if (rc == MYLITE_OK && index < logical_length - 1U) {
            if (logical_type[index] != ',') {
                set_unsupported_error(database, unsupported_message);
                return MYLITE_ERROR;
            }
            ++index;
        }
    }
    if (rc == MYLITE_OK && out_info->label_count == 0U) {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }
    return rc;
}

static int parse_enum_descriptor_label(
    struct mylite_db *database,
    const char *logical_type,
    size_t end_index,
    size_t *index,
    struct enum_type_info *out_info
) {
    size_t label_start = out_info->decoded_length;

    if (*index >= end_index || logical_type[*index] != '\'') {
        set_unsupported_error(database, "invalid ENUM descriptor");
        return MYLITE_ERROR;
    }
    ++*index;
    while (*index < end_index) {
        char byte = logical_type[*index];

        ++*index;
        if (byte == '\'') {
            if (*index < end_index && logical_type[*index] == '\'') {
                ++*index;
                if (enum_type_info_append_byte(database, out_info, '\'') != MYLITE_OK) {
                    return MYLITE_ERROR;
                }
                continue;
            }
            return finish_parse_enum_descriptor_label(database, label_start, out_info);
        }
        if (byte == '\\') {
            if (read_enum_descriptor_escaped_byte(
                    database,
                    logical_type,
                    end_index,
                    index,
                    &byte
                ) != MYLITE_OK) {
                return MYLITE_ERROR;
            }
        }
        if (enum_type_info_append_byte(database, out_info, byte) != MYLITE_OK) {
            return MYLITE_ERROR;
        }
    }

    set_unsupported_error(database, "invalid ENUM descriptor");
    return MYLITE_ERROR;
}

static int finish_parse_enum_descriptor_label(
    struct mylite_db *database,
    size_t label_start,
    struct enum_type_info *out_info
) {
    size_t character_length = 0U;
    size_t text_length = 0U;

    if (enum_type_info_append_byte(database, out_info, '\0') != MYLITE_OK) {
        return MYLITE_ERROR;
    }
    text_length = out_info->decoded_length - label_start - 1U;
    if (validate_utf8_text(
            &out_info->decoded_storage[label_start],
            text_length,
            &character_length
        ) != MYLITE_OK) {
        set_unsupported_error(database, "invalid ENUM descriptor");
        return MYLITE_ERROR;
    }
    out_info->labels[out_info->label_count] = (struct enum_label_descriptor){
        .text = &out_info->decoded_storage[label_start],
        .text_length = text_length,
        .character_length = character_length,
    };
    if (out_info->max_label_character_length < character_length) {
        out_info->max_label_character_length = character_length;
    }
    ++out_info->label_count;
    return MYLITE_OK;
}

static int read_enum_descriptor_escaped_byte(
    struct mylite_db *database,
    const char *logical_type,
    size_t end_index,
    size_t *index,
    char *out_byte
) {
    char byte = '\0';

    if (*index >= end_index) {
        set_unsupported_error(database, "invalid ENUM descriptor");
        return MYLITE_ERROR;
    }
    byte = logical_type[*index];
    ++*index;
    if (byte == 'n') {
        byte = '\n';
    } else if (byte == 'r') {
        byte = '\r';
    } else if (byte == 't') {
        byte = '\t';
    }
    *out_byte = byte;
    return MYLITE_OK;
}

static int enum_type_info_append_byte(
    struct mylite_db *database,
    struct enum_type_info *info,
    char byte
) {
    if (info->decoded_length >= sizeof(info->decoded_storage)) {
        set_unsupported_error(database, "ENUM definition is too large for this MyLite build");
        return MYLITE_ERROR;
    }
    info->decoded_storage[info->decoded_length] = byte;
    ++info->decoded_length;
    return MYLITE_OK;
}

static bool enum_find_label(
    const struct enum_type_info *info,
    const char *text,
    size_t text_length,
    const struct enum_label_descriptor **out_label
) {
    if (out_label != NULL) {
        *out_label = NULL;
    }
    if (info == NULL || text == NULL) {
        return false;
    }
    for (size_t label_index = 0U; label_index < info->label_count; ++label_index) {
        if (enum_label_equals_ascii_case_insensitive(
                info->labels[label_index].text,
                info->labels[label_index].text_length,
                text,
                text_length
            )) {
            if (out_label != NULL) {
                *out_label = &info->labels[label_index];
            }
            return true;
        }
    }
    return false;
}

static bool enum_find_ordinal(
    const struct enum_type_info *info,
    uint64_t ordinal,
    const struct enum_label_descriptor **out_label
) {
    if (out_label != NULL) {
        *out_label = NULL;
    }
    if (info == NULL || ordinal == 0U || ordinal > info->label_count) {
        return false;
    }
    if (out_label != NULL) {
        *out_label = &info->labels[(size_t)ordinal - 1U];
    }
    return true;
}

static bool enum_text_is_unsigned_integer(
    const char *text,
    size_t text_length,
    uint64_t *out_value
) {
    uint64_t value = 0U;

    if (text == NULL || text_length == 0U || out_value == NULL) {
        return false;
    }
    for (size_t index = 0U; index < text_length; ++index) {
        uint64_t digit = 0U;

        if (text[index] < '0' || text[index] > '9') {
            return false;
        }
        digit = (uint64_t)(text[index] - '0');
        if (value > (UINT64_MAX - digit) / decimal_base) {
            return false;
        }
        value = (value * decimal_base) + digit;
    }
    *out_value = value;
    return true;
}

static int set_type_info_for_logical_type(
    struct mylite_db *database,
    const char *logical_type,
    const char *unsupported_message,
    struct set_type_info *out_info
) {
    size_t logical_length = logical_type == NULL ? 0U : strlen(logical_type);
    size_t index = set_logical_prefix_length;
    int rc = MYLITE_OK;

    if (logical_type == NULL || unsupported_message == NULL || out_info == NULL ||
        logical_length <= set_logical_syntax_overhead ||
        strncmp(logical_type, "SET(", set_logical_prefix_length) != 0 ||
        logical_type[logical_length - 1U] != ')') {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }

    *out_info = (struct set_type_info){0};
    while (rc == MYLITE_OK && index < logical_length - 1U) {
        if (out_info->member_count >= set_member_count_capacity) {
            set_unsupported_error(database, unsupported_message);
            return MYLITE_ERROR;
        }
        rc = parse_set_descriptor_member(
            database,
            logical_type,
            logical_length - 1U,
            &index,
            out_info
        );
        if (rc == MYLITE_OK && index < logical_length - 1U) {
            if (logical_type[index] != ',') {
                set_unsupported_error(database, unsupported_message);
                return MYLITE_ERROR;
            }
            ++index;
        }
    }
    if (rc == MYLITE_OK && out_info->member_count == 0U) {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }
    return rc;
}

static int parse_set_descriptor_member(
    struct mylite_db *database,
    const char *logical_type,
    size_t end_index,
    size_t *index,
    struct set_type_info *out_info
) {
    size_t member_start = out_info->decoded_length;

    if (*index >= end_index || logical_type[*index] != '\'') {
        set_unsupported_error(database, "invalid SET descriptor");
        return MYLITE_ERROR;
    }
    ++*index;
    while (*index < end_index) {
        char byte = logical_type[*index];

        ++*index;
        if (byte == '\'') {
            if (*index < end_index && logical_type[*index] == '\'') {
                ++*index;
                if (set_type_info_append_byte(database, out_info, '\'') != MYLITE_OK) {
                    return MYLITE_ERROR;
                }
                continue;
            }
            return finish_parse_set_descriptor_member(database, member_start, out_info);
        }
        if (byte == '\\') {
            if (read_set_descriptor_escaped_byte(database, logical_type, end_index, index, &byte) !=
                MYLITE_OK) {
                return MYLITE_ERROR;
            }
        }
        if (set_type_info_append_byte(database, out_info, byte) != MYLITE_OK) {
            return MYLITE_ERROR;
        }
    }

    set_unsupported_error(database, "invalid SET descriptor");
    return MYLITE_ERROR;
}

static int finish_parse_set_descriptor_member(
    struct mylite_db *database,
    size_t member_start,
    struct set_type_info *out_info
) {
    size_t character_length = 0U;
    size_t text_length = 0U;

    if (set_type_info_append_byte(database, out_info, '\0') != MYLITE_OK) {
        return MYLITE_ERROR;
    }
    text_length = out_info->decoded_length - member_start - 1U;
    if (validate_utf8_text(
            &out_info->decoded_storage[member_start],
            text_length,
            &character_length
        ) != MYLITE_OK) {
        set_unsupported_error(database, "invalid SET descriptor");
        return MYLITE_ERROR;
    }
    out_info->members[out_info->member_count] = (struct enum_label_descriptor){
        .text = &out_info->decoded_storage[member_start],
        .text_length = text_length,
        .character_length = character_length,
    };
    out_info->max_display_character_length += character_length;
    if (out_info->member_count > 0U) {
        ++out_info->max_display_character_length;
    }
    ++out_info->member_count;
    return MYLITE_OK;
}

static int read_set_descriptor_escaped_byte(
    struct mylite_db *database,
    const char *logical_type,
    size_t end_index,
    size_t *index,
    char *out_byte
) {
    char byte = '\0';

    if (*index >= end_index) {
        set_unsupported_error(database, "invalid SET descriptor");
        return MYLITE_ERROR;
    }
    byte = logical_type[*index];
    ++*index;
    if (byte == 'n') {
        byte = '\n';
    } else if (byte == 'r') {
        byte = '\r';
    } else if (byte == 't') {
        byte = '\t';
    }
    *out_byte = byte;
    return MYLITE_OK;
}

static int set_type_info_append_byte(
    struct mylite_db *database,
    struct set_type_info *info,
    char byte
) {
    if (info->decoded_length >= sizeof(info->decoded_storage)) {
        set_unsupported_error(database, "SET definition is too large for this MyLite build");
        return MYLITE_ERROR;
    }
    info->decoded_storage[info->decoded_length] = byte;
    ++info->decoded_length;
    return MYLITE_OK;
}

static bool set_find_member(
    const struct set_type_info *info,
    const char *text,
    size_t text_length,
    size_t *out_index
) {
    if (out_index != NULL) {
        *out_index = 0U;
    }
    if (info == NULL || text == NULL) {
        return false;
    }
    for (size_t member_index = 0U; member_index < info->member_count; ++member_index) {
        if (enum_label_equals_ascii_case_insensitive(
                info->members[member_index].text,
                info->members[member_index].text_length,
                text,
                text_length
            )) {
            if (out_index != NULL) {
                *out_index = member_index;
            }
            return true;
        }
    }
    return false;
}

static bool set_bitmap_is_valid(const struct set_type_info *info, uint64_t bitmap) {
    if (info == NULL || info->member_count == 0U ||
        info->member_count > set_member_count_capacity) {
        return false;
    }
    if (info->member_count == set_member_count_capacity) {
        return true;
    }
    return (bitmap >> info->member_count) == 0U;
}

static int decimal_type_info_for_logical_type(
    const char *logical_type,
    struct decimal_type_info *out_info
) {
    static const char prefix[] = "DECIMAL(";
    static const char unsigned_suffix[] = " UNSIGNED";
    struct mylite_sql_source_span span = {0};
    const char *comma = NULL;
    const char *close = NULL;
    size_t logical_length = logical_type == NULL ? 0U : strlen(logical_type);
    int rc = MYLITE_OK;

    if (logical_type == NULL || out_info == NULL || logical_length <= sizeof(prefix) ||
        strncmp(logical_type, prefix, sizeof(prefix) - 1U) != 0) {
        return MYLITE_ERROR;
    }

    comma = strchr(logical_type + sizeof(prefix) - 1U, ',');
    close = comma == NULL ? NULL : strchr(comma + 1, ')');
    if (comma == NULL || close == NULL) {
        return MYLITE_ERROR;
    }

    *out_info = (struct decimal_type_info){0};
    span = (struct mylite_sql_source_span){
        .text = logical_type + sizeof(prefix) - 1U,
        .length = (size_t)(comma - (logical_type + sizeof(prefix) - 1U)),
    };
    rc = parse_unsigned_integer_literal(&span, &out_info->precision);
    if (rc != MYLITE_OK) {
        return rc;
    }
    span = (struct mylite_sql_source_span){
        .text = comma + 1,
        .length = (size_t)(close - (comma + 1)),
    };
    rc = parse_unsigned_integer_literal(&span, &out_info->scale);
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (strcmp(close + 1, "") == 0) {
        out_info->is_unsigned = false;
        return MYLITE_OK;
    }
    if (strcmp(close + 1, unsigned_suffix) == 0) {
        out_info->is_unsigned = true;
        return MYLITE_OK;
    }

    return MYLITE_ERROR;
}

static int approximate_type_info_for_logical_type(
    const char *logical_type,
    struct approximate_type_info *out_info
) {
    if (logical_type == NULL || out_info == NULL) {
        return MYLITE_ERROR;
    }
    if (strcmp(logical_type, "FLOAT") == 0) {
        *out_info = (struct approximate_type_info){
            .type_class = APPROXIMATE_TYPE_FLOAT,
            .is_unsigned = false,
        };
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "FLOAT UNSIGNED") == 0) {
        *out_info = (struct approximate_type_info){
            .type_class = APPROXIMATE_TYPE_FLOAT,
            .is_unsigned = true,
        };
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "DOUBLE") == 0) {
        *out_info = (struct approximate_type_info){
            .type_class = APPROXIMATE_TYPE_DOUBLE,
            .is_unsigned = false,
        };
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "DOUBLE UNSIGNED") == 0) {
        *out_info = (struct approximate_type_info){
            .type_class = APPROXIMATE_TYPE_DOUBLE,
            .is_unsigned = true,
        };
        return MYLITE_OK;
    }

    return MYLITE_ERROR;
}

static const struct text_family_type_info *text_family_type_info_for_logical_type(
    const char *logical_type
) {
    static const struct text_family_type_info text_types[] = {
        {"TINYTEXT", "tinytext", tinytext_max_length},
        {"TEXT", "text", text_max_length},
        {"MEDIUMTEXT", "mediumtext", mediumtext_max_length},
        {"LONGTEXT", "longtext", longtext_max_length},
    };

    if (logical_type == NULL) {
        return NULL;
    }
    for (size_t index = 0U; index < sizeof(text_types) / sizeof(text_types[0]); ++index) {
        if (strcmp(logical_type, text_types[index].logical_type) == 0) {
            return &text_types[index];
        }
    }
    return NULL;
}

static const struct binary_string_type_info *binary_string_type_info_for_logical_type(
    const char *logical_type,
    struct binary_string_type_info *storage
) {
    static const struct binary_string_type_info blob_types[] = {
        {"TINYBLOB", "tinyblob", 255U, false, true},
        {"BLOB", "blob", 65535U, false, true},
        {"MEDIUMBLOB", "mediumblob", 16777215U, false, true},
        {"LONGBLOB", "longblob", 4294967295ULL, false, true},
    };
    size_t logical_length = logical_type == NULL ? 0U : strlen(logical_type);

    if (logical_type == NULL || storage == NULL) {
        return NULL;
    }
    if (strncmp(logical_type, "BINARY(", binary_logical_prefix_length) == 0) {
        uint64_t length = 0U;
        struct mylite_sql_source_span span = {0};

        if (logical_length <= binary_logical_syntax_overhead ||
            logical_type[logical_length - 1U] != ')') {
            return NULL;
        }
        span = (struct mylite_sql_source_span){
            .text = &logical_type[binary_logical_prefix_length],
            .length = logical_length - binary_logical_syntax_overhead,
        };
        if (parse_unsigned_integer_literal(&span, &length) != MYLITE_OK ||
            length > binary_max_length) {
            return NULL;
        }
        *storage = (struct binary_string_type_info){
            .logical_type = logical_type,
            .display_type = NULL,
            .maximum_length = length,
            .fixed_length = true,
            .blob_family = false,
        };
        return storage;
    }
    if (strncmp(logical_type, "VARBINARY(", varbinary_logical_prefix_length) == 0) {
        uint64_t length = 0U;
        struct mylite_sql_source_span span = {0};

        if (logical_length <= varbinary_logical_syntax_overhead ||
            logical_type[logical_length - 1U] != ')') {
            return NULL;
        }
        span = (struct mylite_sql_source_span){
            .text = &logical_type[varbinary_logical_prefix_length],
            .length = logical_length - varbinary_logical_syntax_overhead,
        };
        if (parse_unsigned_integer_literal(&span, &length) != MYLITE_OK ||
            length > varbinary_max_length) {
            return NULL;
        }
        *storage = (struct binary_string_type_info){
            .logical_type = logical_type,
            .display_type = NULL,
            .maximum_length = length,
            .fixed_length = false,
            .blob_family = false,
        };
        return storage;
    }
    for (size_t index = 0U; index < sizeof(blob_types) / sizeof(blob_types[0]); ++index) {
        if (strcmp(logical_type, blob_types[index].logical_type) == 0) {
            return &blob_types[index];
        }
    }
    return NULL;
}

static int parse_binary_descriptor_length(
    struct mylite_db *database,
    const char *logical_type,
    const char *unsupported_message,
    size_t *out_length
) {
    struct mylite_sql_source_span length_span = {0};
    size_t logical_length = logical_type == NULL ? 0U : strlen(logical_type);
    uint64_t length = 0U;
    int rc = MYLITE_OK;

    if (out_length == NULL || logical_type == NULL || unsupported_message == NULL ||
        logical_length <= sizeof("BINARY(") || logical_type[logical_length - 1U] != ')' ||
        strncmp(logical_type, "BINARY(", binary_logical_prefix_length) != 0) {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }

    length_span = (struct mylite_sql_source_span){
        .text = &logical_type[binary_logical_prefix_length],
        .length = logical_length - binary_logical_syntax_overhead,
    };
    rc = parse_unsigned_integer_literal(&length_span, &length);
    if (rc != MYLITE_OK || length > binary_max_length) {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }

    *out_length = (size_t)length;
    return MYLITE_OK;
}

static int parse_varbinary_descriptor_length(
    struct mylite_db *database,
    const char *logical_type,
    const char *unsupported_message,
    size_t *out_length
) {
    struct mylite_sql_source_span length_span = {0};
    size_t logical_length = logical_type == NULL ? 0U : strlen(logical_type);
    uint64_t length = 0U;
    int rc = MYLITE_OK;

    if (out_length == NULL || logical_type == NULL || unsupported_message == NULL ||
        logical_length <= sizeof("VARBINARY(") || logical_type[logical_length - 1U] != ')' ||
        strncmp(logical_type, "VARBINARY(", varbinary_logical_prefix_length) != 0) {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }

    length_span = (struct mylite_sql_source_span){
        .text = &logical_type[varbinary_logical_prefix_length],
        .length = logical_length - varbinary_logical_syntax_overhead,
    };
    rc = parse_unsigned_integer_literal(&length_span, &length);
    if (rc != MYLITE_OK || length > varbinary_max_length) {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }

    *out_length = (size_t)length;
    return MYLITE_OK;
}

static int bit_width_for_logical_type(const char *logical_type, uint64_t *out_width) {
    struct mylite_sql_source_span span = {0};
    size_t logical_length = logical_type == NULL ? 0U : strlen(logical_type);
    uint64_t width = 0U;

    if (logical_type == NULL || out_width == NULL ||
        logical_length <= bit_logical_syntax_overhead || logical_type[logical_length - 1U] != ')' ||
        strncmp(logical_type, "BIT(", bit_logical_prefix_length) != 0) {
        return MYLITE_ERROR;
    }
    span = (struct mylite_sql_source_span){
        .text = &logical_type[bit_logical_prefix_length],
        .length = logical_length - bit_logical_syntax_overhead,
    };
    if (parse_unsigned_integer_literal(&span, &width) != MYLITE_OK || width == 0U ||
        width > bit_max_length) {
        return MYLITE_ERROR;
    }

    *out_width = width;
    return MYLITE_OK;
}

static size_t bit_byte_width(uint64_t width) {
    return (size_t)((width + bit_byte_rounding_offset) / byte_bit_count);
}

static uint64_t bit_width_max_value(uint64_t width) {
    if (width >= bit_max_length) {
        return UINT64_MAX;
    }
    return (UINT64_C(1) << width) - 1U;
}

static bool column_descriptor_is_auto_increment(
    const struct mylite_catalog_column_descriptor *column
) {
    return (column != NULL && column->is_auto_increment) != 0;
}

static int validate_planned_table_row_size(
    struct mylite_db *database,
    const struct planned_column *columns,
    size_t column_count
) {
    uint64_t total = 0U;
    int rc = MYLITE_OK;

    if (columns == NULL && column_count != 0U) {
        set_runtime_error(database, "invalid planned columns");
        return MYLITE_ERROR;
    }
    for (size_t column_index = 0U; rc == MYLITE_OK && column_index < column_count; ++column_index) {
        rc = add_planned_column_row_size(database, &columns[column_index], &total);
    }

    return rc;
}

static int validate_added_column_row_size(
    struct mylite_db *database,
    const struct mylite_catalog_column_descriptor *columns,
    size_t column_count,
    const struct planned_column *added_column
) {
    uint64_t total = 0U;
    int rc = MYLITE_OK;

    if ((columns == NULL && column_count != 0U) || added_column == NULL) {
        set_runtime_error(database, "invalid add-column row-size plan");
        return MYLITE_ERROR;
    }
    for (size_t column_index = 0U; rc == MYLITE_OK && column_index < column_count; ++column_index) {
        rc = add_catalog_column_row_size(database, &columns[column_index], &total);
    }
    if (rc == MYLITE_OK) {
        rc = add_planned_column_row_size(database, added_column, &total);
    }

    return rc;
}

static int add_planned_column_row_size(
    struct mylite_db *database,
    const struct planned_column *column,
    uint64_t *total
) {
    uint64_t size = 0U;
    int rc = MYLITE_OK;

    if (column == NULL || total == NULL) {
        set_runtime_error(database, "invalid planned column row-size input");
        return MYLITE_ERROR;
    }
    rc = row_size_for_column_descriptor(
        database,
        column->logical_type,
        column->physical_type,
        "row-size validation supports only current baseline column descriptors",
        &size
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    return add_row_size_bytes(database, size, total);
}

static int add_catalog_column_row_size(
    struct mylite_db *database,
    const struct mylite_catalog_column_descriptor *column,
    uint64_t *total
) {
    uint64_t size = 0U;
    int rc = MYLITE_OK;

    if (column == NULL || total == NULL) {
        set_runtime_error(database, "invalid catalog column row-size input");
        return MYLITE_ERROR;
    }
    rc = row_size_for_column_descriptor(
        database,
        column->logical_type,
        column->physical_type,
        "row-size validation supports only current baseline column descriptors",
        &size
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    return add_row_size_bytes(database, size, total);
}

static int row_size_for_column_descriptor(
    struct mylite_db *database,
    const char *logical_type,
    const char *physical_type,
    const char *unsupported_message,
    uint64_t *out_size
) {
    struct approximate_type_info approximate_info = {
        .type_class = APPROXIMATE_TYPE_DOUBLE,
        .is_unsigned = false,
    };
    uint64_t size = 0U;
    int rc = MYLITE_OK;

    if (logical_type == NULL || physical_type == NULL || unsupported_message == NULL ||
        out_size == NULL) {
        set_runtime_error(database, "invalid row-size descriptor");
        return MYLITE_ERROR;
    }
    if (strcmp(physical_type, "INTEGER") == 0) {
        rc = integer_row_size_bytes(logical_type, &size);
        if (rc != MYLITE_OK) {
            set_unsupported_error(database, unsupported_message);
            return MYLITE_ERROR;
        }
        *out_size = size;
        return MYLITE_OK;
    }
    if (strcmp(physical_type, "REAL") == 0) {
        rc = approximate_type_info_for_logical_type(logical_type, &approximate_info);
        if (rc != MYLITE_OK) {
            set_unsupported_error(database, unsupported_message);
            return MYLITE_ERROR;
        }
        return approximate_row_size_bytes(&approximate_info, out_size);
    }
    if (strcmp(physical_type, "BLOB") == 0) {
        uint64_t bit_width = 0U;

        if (bit_width_for_logical_type(logical_type, &bit_width) == MYLITE_OK) {
            *out_size = (uint64_t)bit_byte_width(bit_width);
            return MYLITE_OK;
        }
        return binary_string_row_size_bytes(database, logical_type, out_size, unsupported_message);
    }
    if (strcmp(physical_type, "TEXT") != 0) {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }
    return text_backed_row_size_bytes(database, logical_type, out_size, unsupported_message);
}

static int binary_string_row_size_bytes(
    struct mylite_db *database,
    const char *logical_type,
    uint64_t *out_size,
    const char *unsupported_message
) {
    struct binary_string_type_info info = {0};
    const struct binary_string_type_info *resolved_info =
        binary_string_type_info_for_logical_type(logical_type, &info);

    if (resolved_info == NULL) {
        set_unsupported_error(database, unsupported_message);
        return MYLITE_ERROR;
    }
    if (resolved_info->fixed_length) {
        *out_size = resolved_info->maximum_length;
        return MYLITE_OK;
    }
    if (!resolved_info->blob_family) {
        *out_size = resolved_info->maximum_length;
        if (resolved_info->maximum_length <= varchar_one_byte_length_prefix_max) {
            *out_size += 1U;
        } else {
            *out_size += 2U;
        }
        return MYLITE_OK;
    }
    *out_size = blob_family_row_size_contribution;
    return MYLITE_OK;
}

static int text_backed_row_size_bytes(
    struct mylite_db *database,
    const char *logical_type,
    uint64_t *out_size,
    const char *unsupported_message
) {
    struct decimal_type_info decimal_info = {0};
    size_t length = 0U;
    uint64_t size = 0U;
    int rc = MYLITE_OK;

    if (logical_type_is_varchar(logical_type)) {
        rc = parse_varchar_descriptor_length(database, logical_type, unsupported_message, &length);
        if (rc != MYLITE_OK) {
            return rc;
        }
        size = (uint64_t)length * logical_type_max_bytes_per_character(logical_type);
        *out_size = size;
        if (size <= varchar_one_byte_length_prefix_max) {
            *out_size += 1U;
        } else {
            *out_size += 2U;
        }
        return MYLITE_OK;
    }
    if (logical_type_is_char(logical_type)) {
        rc = parse_char_descriptor_length(database, logical_type, unsupported_message, &length);
        if (rc != MYLITE_OK) {
            return rc;
        }
        *out_size = (uint64_t)length * logical_type_max_bytes_per_character(logical_type);
        return MYLITE_OK;
    }
    if (decimal_type_info_for_logical_type(logical_type, &decimal_info) == MYLITE_OK) {
        return decimal_row_size_bytes(&decimal_info, out_size);
    }
    if (strncmp(logical_type, "ENUM(", enum_logical_prefix_length) == 0) {
        struct enum_type_info enum_info = {0};

        rc = enum_type_info_for_logical_type(
            database,
            logical_type,
            unsupported_message,
            &enum_info
        );
        if (rc != MYLITE_OK) {
            return rc;
        }
        *out_size = enum_info.label_count <= enum_one_byte_label_count_max ? 1U : 2U;
        return MYLITE_OK;
    }
    if (strncmp(logical_type, "SET(", set_logical_prefix_length) == 0) {
        return set_row_size_bytes(database, logical_type, out_size, unsupported_message);
    }
    if (strcmp(logical_type, "YEAR") == 0) {
        *out_size = year_row_size_bytes;
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "DATE") == 0) {
        *out_size = date_row_size_bytes;
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "TIME") == 0) {
        *out_size = time_row_size_bytes;
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "DATETIME") == 0) {
        *out_size = datetime_row_size_bytes;
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "TIMESTAMP") == 0) {
        *out_size = timestamp_row_size_bytes;
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "JSON") == 0) {
        *out_size = text_family_row_size_contribution;
        return MYLITE_OK;
    }
    if (text_family_type_info_for_logical_type(logical_type) != NULL) {
        *out_size = text_family_row_size_contribution;
        return MYLITE_OK;
    }

    set_unsupported_error(database, unsupported_message);
    return MYLITE_ERROR;
}

static int set_row_size_bytes(
    struct mylite_db *database,
    const char *logical_type,
    uint64_t *out_size,
    const char *unsupported_message
) {
    struct set_type_info info = {0};
    int rc = set_type_info_for_logical_type(database, logical_type, unsupported_message, &info);

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (info.member_count <= set_one_byte_storage_member_count_max) {
        *out_size = set_one_byte_storage_size;
    } else if (info.member_count <= set_two_byte_storage_member_count_max) {
        *out_size = set_two_byte_storage_size;
    } else if (info.member_count <= set_three_byte_storage_member_count_max) {
        *out_size = set_three_byte_storage_size;
    } else if (info.member_count <= set_four_byte_storage_member_count_max) {
        *out_size = set_four_byte_storage_size;
    } else {
        *out_size = set_eight_byte_storage_size;
    }
    return MYLITE_OK;
}

static int integer_row_size_bytes(const char *logical_type, uint64_t *out_size) {
    if (logical_type == NULL || out_size == NULL) {
        return MYLITE_MISUSE;
    }
    if (strcmp(logical_type, "TINYINT") == 0 || strcmp(logical_type, "TINYINT(1)") == 0 ||
        strcmp(logical_type, "TINYINT UNSIGNED") == 0) {
        *out_size = tinyint_row_size_bytes;
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "SMALLINT") == 0 || strcmp(logical_type, "SMALLINT UNSIGNED") == 0) {
        *out_size = smallint_row_size_bytes;
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "MEDIUMINT") == 0 || strcmp(logical_type, "MEDIUMINT UNSIGNED") == 0) {
        *out_size = mediumint_row_size_bytes;
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "INT") == 0 || strcmp(logical_type, "INT UNSIGNED") == 0) {
        *out_size = int_row_size_bytes;
        return MYLITE_OK;
    }
    if (strcmp(logical_type, "BIGINT") == 0 || strcmp(logical_type, "BIGINT UNSIGNED") == 0) {
        *out_size = bigint_row_size_bytes;
        return MYLITE_OK;
    }

    return MYLITE_ERROR;
}

static int decimal_row_size_bytes(const struct decimal_type_info *info, uint64_t *out_size) {
    uint64_t integer_digits = 0U;
    uint64_t fractional_digits = 0U;

    if (info == NULL || out_size == NULL || info->scale > info->precision) {
        return MYLITE_MISUSE;
    }

    integer_digits = info->precision - info->scale;
    fractional_digits = info->scale;
    *out_size =
        decimal_digit_group_size(integer_digits) + decimal_digit_group_size(fractional_digits);
    return MYLITE_OK;
}

static int approximate_row_size_bytes(
    const struct approximate_type_info *info,
    uint64_t *out_size
) {
    if (info == NULL || out_size == NULL) {
        return MYLITE_MISUSE;
    }
    if (info->type_class == APPROXIMATE_TYPE_FLOAT) {
        *out_size = float_row_size_bytes;
        return MYLITE_OK;
    }
    if (info->type_class == APPROXIMATE_TYPE_DOUBLE) {
        *out_size = double_row_size_bytes;
        return MYLITE_OK;
    }

    return MYLITE_ERROR;
}

static uint64_t decimal_digit_group_size(uint64_t digits) {
    static const uint64_t leftover_digit_bytes[] = {0U, 1U, 1U, 2U, 2U, 3U, 3U, 4U, 4U};
    uint64_t full_groups = digits / decimal_digits_per_storage_group;
    uint64_t leftover_digits = digits % decimal_digits_per_storage_group;

    return (full_groups * 4U) + leftover_digit_bytes[leftover_digits];
}

static int add_row_size_bytes(struct mylite_db *database, uint64_t addition, uint64_t *total) {
    if (total == NULL) {
        set_runtime_error(database, "invalid row-size accumulator");
        return MYLITE_ERROR;
    }
    if (*total > UINT64_MAX - addition) {
        set_row_size_too_large_error(database);
        return MYLITE_ERROR;
    }
    *total += addition;
    if (*total > mysql_max_row_size) {
        set_row_size_too_large_error(database);
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int validate_planned_string_key_column(
    struct mylite_db *database,
    const struct planned_column *column
) {
    size_t length = 0U;
    int rc = MYLITE_OK;

    if (column == NULL || !planned_column_is_char_or_varchar(column)) {
        set_runtime_error(database, "invalid string key column");
        return MYLITE_ERROR;
    }
    if (planned_column_is_char(column)) {
        rc = parse_char_descriptor_length(
            database,
            column->logical_type,
            "string keys support only baseline CHAR descriptors",
            &length
        );
    } else {
        rc = parse_varchar_descriptor_length(
            database,
            column->logical_type,
            "string keys support only baseline VARCHAR descriptors",
            &length
        );
    }
    if (rc == MYLITE_OK && length == 0U) {
        set_storage_engine_cant_index_column_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && planned_column_is_varchar(column) &&
        length > varchar_string_key_max_length) {
        set_storage_engine_cant_index_column_error(database, column->name);
        return MYLITE_ERROR;
    }

    return rc;
}

static int validate_descriptor_string_key_column(
    struct mylite_db *database,
    const struct mylite_catalog_column_descriptor *column
) {
    size_t length = 0U;
    int rc = MYLITE_OK;

    if (column == NULL || !column_descriptor_is_char_or_varchar(column)) {
        set_runtime_error(database, "invalid string key column descriptor");
        return MYLITE_ERROR;
    }
    if (column_descriptor_is_char(column)) {
        rc = char_length_for_column(database, column, &length);
    } else {
        rc = varchar_length_for_column(database, column, &length);
    }
    if (rc == MYLITE_OK && length == 0U) {
        set_storage_engine_cant_index_column_error(database, column->name);
        return MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && column_descriptor_is_varchar(column) &&
        length > varchar_string_key_max_length) {
        set_storage_engine_cant_index_column_error(database, column->name);
        return MYLITE_ERROR;
    }

    return rc;
}

static int validate_string_key_value(
    struct mylite_db *database,
    const struct planned_value *value
) {
    if (value == NULL) {
        set_runtime_error(database, "invalid string key value");
        return MYLITE_ERROR;
    }
    if (value->is_null) {
        return MYLITE_OK;
    }
    if (!value->is_text || !text_value_is_supported_string_key(value->text, value->text_length)) {
        set_non_ascii_string_key_error(database);
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static bool loaded_index_part_requires_string_key_validation(const struct loaded_index_part *part) {
    if (part == NULL) {
        return false;
    }
    if (column_descriptor_is_char_or_varchar(&part->column)) {
        return true;
    }

    if (!part->index_column.has_prefix_length) {
        return false;
    }

    return column_descriptor_is_text_family(&part->column);
}

static bool text_value_is_supported_string_key(const char *text, size_t text_length) {
    if (text == NULL && text_length != 0U) {
        return false;
    }
    for (size_t index = 0U; index < text_length; ++index) {
        unsigned char byte = (unsigned char)text[index];

        if (byte == '\0' || byte > ascii_max_byte) {
            return false;
        }
    }

    return true;
}

static bool modify_column_integer_value_domain_matches(
    const struct mylite_catalog_column_descriptor *original_column,
    const struct planned_column *replacement_column
) {
    const char *original_logical_type = original_column->logical_type;
    const char *replacement_logical_type = replacement_column->logical_type;

    if (original_logical_type == NULL || replacement_logical_type == NULL) {
        return false;
    }
    if (strcmp(original_logical_type, "TINYINT(1)") == 0) {
        original_logical_type = "TINYINT";
    }
    if (strcmp(replacement_logical_type, "TINYINT(1)") == 0) {
        replacement_logical_type = "TINYINT";
    }

    return strcmp(original_logical_type, replacement_logical_type) == 0;
}

static bool modify_column_char_varchar_replacement_supported(
    const struct mylite_catalog_column_descriptor *original_column,
    const struct planned_column *replacement_column
) {
    return (column_descriptor_is_char_or_varchar(original_column) &&
            planned_column_is_char_or_varchar(replacement_column)) != 0;
}

static bool column_is_nullable(const struct mylite_sql_ast_node *nullability_node) {
    return mylite_sql_ast_node_nullability(nullability_node) != MYLITE_SQL_AST_NULLABILITY_NOT_NULL;
}

static int resolve_readable_base_table(
    struct mylite_db *database,
    const struct table_name_resolution *resolution,
    struct mylite_catalog_table_descriptor *out_table
) {
    int rc = mylite_catalog_read_table_by_name(
        database,
        resolution->schema.schema_id,
        resolution->table_name,
        out_table
    );

    if (rc != MYLITE_OK) {
        set_table_does_not_exist_error(database, resolution->schema.name, resolution->table_name);
        return MYLITE_ERROR;
    }
    if (out_table->kind != MYLITE_CATALOG_TABLE_KIND_BASE) {
        set_unsupported_error(database, "statement supports only persistent base tables");
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int load_table_columns(
    struct mylite_db *database,
    int64_t table_id,
    struct mylite_catalog_column_descriptor **out_columns,
    size_t *out_column_count
) {
    struct load_columns_context context = {0};
    int rc = MYLITE_OK;

    *out_columns = NULL;
    *out_column_count = 0U;
    if (table_id < 0) {
        rc = mylite_temporary_catalog_for_each_column_in_table(
            &database->session.temporary_catalog,
            table_id,
            append_loaded_column,
            &context
        );
    } else {
        rc = mylite_catalog_for_each_column_in_table(
            database,
            table_id,
            append_loaded_column,
            &context
        );
    }
    if (rc != MYLITE_OK) {
        free(context.columns);
        if (rc == MYLITE_NOMEM) {
            set_nomem_error(database);
        } else {
            set_runtime_error(database, "failed to load table columns");
        }
        return rc;
    }
    if (context.count == 0U) {
        free(context.columns);
        set_runtime_error(database, "table descriptor has no columns");
        return MYLITE_ERROR;
    }

    *out_columns = context.columns;
    *out_column_count = context.count;

    return MYLITE_OK;
}

static int append_loaded_column(
    const struct mylite_catalog_column_descriptor *column,
    void *user_data
) {
    struct load_columns_context *context = user_data;
    int rc = MYLITE_OK;

    if (column == NULL || context == NULL) {
        return MYLITE_MISUSE;
    }

    rc = load_columns_reserve(context, context->count + 1U);
    if (rc != MYLITE_OK) {
        return rc;
    }

    context->columns[context->count] = *column;
    ++context->count;

    return MYLITE_OK;
}

static struct primary_key_info primary_key_info_init(void) {
    return (struct primary_key_info){
        .has_primary_key = false,
        .index = {.is_unique = false},
        .parts = NULL,
        .part_count = 0U,
    };
}

static void primary_key_info_deinit(struct primary_key_info *info) {
    if (info == NULL) {
        return;
    }
    free(info->parts);
    *info = primary_key_info_init();
}

static int load_primary_key_info(
    struct mylite_db *database,
    int64_t table_id,
    const struct mylite_catalog_column_descriptor *columns,
    size_t column_count,
    struct primary_key_info *out_info
) {
    struct load_primary_key_column_context context = {0};
    bool found = false;
    int rc = MYLITE_OK;

    if (out_info == NULL) {
        return MYLITE_MISUSE;
    }
    *out_info = primary_key_info_init();

    if (table_id < 0) {
        rc = mylite_temporary_catalog_try_read_primary_index_by_table_id(
            &database->session.temporary_catalog,
            table_id,
            &out_info->index,
            &found
        );
    } else {
        rc = mylite_catalog_try_read_primary_index_by_table_id(
            database,
            table_id,
            &out_info->index,
            &found
        );
    }
    if (rc != MYLITE_OK) {
        set_runtime_error(database, "failed to load primary-key descriptor");
        return rc;
    }
    if (!found) {
        return MYLITE_OK;
    }

    context.database = database;
    context.columns = columns;
    context.column_count = column_count;
    if (table_id < 0) {
        rc = mylite_temporary_catalog_for_each_index_column_in_index(
            &database->session.temporary_catalog,
            out_info->index.index_id,
            append_loaded_primary_key_column,
            &context
        );
    } else {
        rc = mylite_catalog_for_each_index_column_in_index(
            database,
            out_info->index.index_id,
            append_loaded_primary_key_column,
            &context
        );
    }
    if (rc != MYLITE_OK || context.count == 0U) {
        free(context.parts);
        set_runtime_error(database, "invalid primary-key column descriptor");
        return rc == MYLITE_OK ? MYLITE_ERROR : rc;
    }

    out_info->has_primary_key = true;
    out_info->parts = context.parts;
    out_info->part_count = context.count;

    return MYLITE_OK;
}

static int load_table_index_infos(
    struct mylite_db *database,
    int64_t table_id,
    const struct mylite_catalog_column_descriptor *columns,
    size_t column_count,
    struct loaded_index_info **out_indexes,
    size_t *out_index_count
) {
    struct load_index_infos_context context = {
        .database = database,
        .columns = columns,
        .column_count = column_count,
        .indexes = NULL,
        .count = 0U,
        .capacity = 0U,
    };
    int rc = MYLITE_OK;

    if (out_indexes == NULL || out_index_count == NULL) {
        return MYLITE_MISUSE;
    }
    *out_indexes = NULL;
    *out_index_count = 0U;

    if (table_id < 0) {
        rc = mylite_temporary_catalog_for_each_index_in_table(
            &database->session.temporary_catalog,
            table_id,
            append_loaded_index_info,
            &context
        );
    } else {
        rc = mylite_catalog_for_each_index_in_table(
            database,
            table_id,
            append_loaded_index_info,
            &context
        );
    }
    if (rc != MYLITE_OK) {
        loaded_index_infos_deinit(&context.indexes, &context.count);
        if (mylite_diagnostics_errcode(mylite_connection_diagnostics(database)) == MYLITE_OK) {
            set_runtime_error(database, "failed to load index descriptors");
        }
        return rc;
    }

    *out_indexes = context.indexes;
    *out_index_count = context.count;
    return MYLITE_OK;
}

static void loaded_index_infos_deinit(struct loaded_index_info **indexes, size_t *index_count) {
    if (indexes == NULL || index_count == NULL) {
        return;
    }
    for (size_t index = 0U; index < *index_count; ++index) {
        loaded_index_info_deinit(&(*indexes)[index]);
    }
    free(*indexes);
    *indexes = NULL;
    *index_count = 0U;
}

static void loaded_index_info_deinit(struct loaded_index_info *index) {
    if (index == NULL) {
        return;
    }
    free(index->parts);
    *index = (struct loaded_index_info){0};
}

static int load_table_foreign_key_infos(
    struct mylite_db *database,
    int64_t table_id,
    const struct mylite_catalog_column_descriptor *child_columns,
    size_t child_column_count,
    struct loaded_foreign_key_info **out_foreign_keys,
    size_t *out_foreign_key_count
) {
    struct load_foreign_key_infos_context context = {
        .database = database,
        .child_columns = child_columns,
        .child_column_count = child_column_count,
        .foreign_keys = NULL,
        .count = 0U,
        .capacity = 0U,
    };
    int rc = MYLITE_OK;

    if (out_foreign_keys == NULL || out_foreign_key_count == NULL) {
        return MYLITE_MISUSE;
    }
    *out_foreign_keys = NULL;
    *out_foreign_key_count = 0U;
    if (table_id < 0) {
        return MYLITE_OK;
    }

    rc = mylite_catalog_for_each_foreign_key_in_child_table(
        database,
        table_id,
        append_loaded_foreign_key_info,
        &context
    );
    if (rc != MYLITE_OK) {
        loaded_foreign_key_infos_deinit(&context.foreign_keys, &context.count);
        if (mylite_diagnostics_errcode(mylite_connection_diagnostics(database)) == MYLITE_OK) {
            set_runtime_error(database, "failed to load foreign-key descriptors");
        }
        return rc;
    }

    *out_foreign_keys = context.foreign_keys;
    *out_foreign_key_count = context.count;
    return MYLITE_OK;
}

static void loaded_foreign_key_infos_deinit(
    struct loaded_foreign_key_info **foreign_keys,
    size_t *foreign_key_count
) {
    if (foreign_keys == NULL || foreign_key_count == NULL) {
        return;
    }
    for (size_t index = 0U; index < *foreign_key_count; ++index) {
        loaded_foreign_key_info_deinit(&(*foreign_keys)[index]);
    }
    free(*foreign_keys);
    *foreign_keys = NULL;
    *foreign_key_count = 0U;
}

static void loaded_foreign_key_info_deinit(struct loaded_foreign_key_info *foreign_key) {
    if (foreign_key == NULL) {
        return;
    }
    free(foreign_key->parts);
    *foreign_key = (struct loaded_foreign_key_info){0};
}

static int append_loaded_index_info(
    const struct mylite_catalog_index_descriptor *index,
    void *user_data
) {
    struct load_index_infos_context *context = user_data;
    struct loaded_index_info *loaded = NULL;
    struct loaded_index_part *parts = NULL;
    size_t part_count = 0U;
    int rc = MYLITE_OK;

    if (index == NULL || context == NULL || context->database == NULL) {
        return MYLITE_MISUSE;
    }

    rc = load_index_parts(
        context->database,
        index->index_id,
        context->columns,
        context->column_count,
        &parts,
        &part_count
    );
    if (rc == MYLITE_OK) {
        rc = reserve_loaded_index_infos(context, context->count + 1U);
    }
    if (rc != MYLITE_OK) {
        free(parts);
        return rc;
    }

    loaded = &context->indexes[context->count];
    *loaded = (struct loaded_index_info){
        .index = *index,
        .parts = parts,
        .part_count = part_count,
    };
    ++context->count;
    return MYLITE_OK;
}

static int load_foreign_key_info(
    struct mylite_db *database,
    const struct mylite_catalog_foreign_key_descriptor *foreign_key,
    const struct mylite_catalog_column_descriptor *provided_child_columns,
    size_t provided_child_column_count,
    struct loaded_foreign_key_info *out_info
) {
    struct mylite_catalog_column_descriptor *owned_child_columns = NULL;
    struct mylite_catalog_column_descriptor *parent_columns = NULL;
    struct loaded_index_info *parent_indexes = NULL;
    const struct mylite_catalog_column_descriptor *child_columns = provided_child_columns;
    struct loaded_foreign_key_part *parts = NULL;
    size_t child_column_count = provided_child_column_count;
    size_t parent_column_count = 0U;
    size_t parent_index_count = 0U;
    size_t part_count = 0U;
    int rc = MYLITE_OK;

    *out_info = (struct loaded_foreign_key_info){.foreign_key = *foreign_key};
    rc = mylite_catalog_read_table_by_id(
        database,
        foreign_key->child_table_id,
        &out_info->child_table
    );
    if (rc == MYLITE_OK) {
        rc = mylite_catalog_read_table_by_id(
            database,
            foreign_key->parent_table_id,
            &out_info->parent_table
        );
    }
    if (rc == MYLITE_OK && child_columns == NULL) {
        rc = load_table_columns(
            database,
            out_info->child_table.table_id,
            &owned_child_columns,
            &child_column_count
        );
        child_columns = owned_child_columns;
    }
    if (rc == MYLITE_OK) {
        rc = load_table_columns(
            database,
            out_info->parent_table.table_id,
            &parent_columns,
            &parent_column_count
        );
    }
    if (rc == MYLITE_OK) {
        bool found_parent_index = false;

        rc = load_table_index_infos(
            database,
            out_info->parent_table.table_id,
            parent_columns,
            parent_column_count,
            &parent_indexes,
            &parent_index_count
        );
        for (size_t index = 0U; rc == MYLITE_OK && index < parent_index_count; ++index) {
            if (parent_indexes[index].index.index_id == foreign_key->parent_index_id) {
                out_info->parent_index = parent_indexes[index].index;
                found_parent_index = true;
                break;
            }
        }
        if (rc == MYLITE_OK && !found_parent_index) {
            set_runtime_error(database, "foreign-key parent index descriptor is stale");
            rc = MYLITE_ERROR;
        }
    }
    if (rc == MYLITE_OK) {
        rc = load_foreign_key_parts(
            database,
            foreign_key,
            child_columns,
            child_column_count,
            parent_columns,
            parent_column_count,
            &parts,
            &part_count
        );
    }

    loaded_index_infos_deinit(&parent_indexes, &parent_index_count);
    free(parent_columns);
    free(owned_child_columns);
    if (rc != MYLITE_OK) {
        free(parts);
        *out_info = (struct loaded_foreign_key_info){0};
        return rc;
    }

    out_info->parts = parts;
    out_info->part_count = part_count;
    return MYLITE_OK;
}

static int append_loaded_foreign_key_info(
    const struct mylite_catalog_foreign_key_descriptor *foreign_key,
    void *user_data
) {
    struct load_foreign_key_infos_context *context = user_data;
    struct loaded_foreign_key_info *loaded = NULL;
    int rc = MYLITE_OK;

    if (foreign_key == NULL || context == NULL || context->database == NULL) {
        return MYLITE_MISUSE;
    }

    rc = reserve_loaded_foreign_key_infos(context, context->count + 1U);
    if (rc == MYLITE_OK) {
        loaded = &context->foreign_keys[context->count];
        *loaded = (struct loaded_foreign_key_info){0};
        rc = load_foreign_key_info(
            context->database,
            foreign_key,
            context->child_columns,
            context->child_column_count,
            loaded
        );
    }
    if (rc == MYLITE_OK) {
        ++context->count;
    } else if (loaded != NULL) {
        loaded_foreign_key_info_deinit(loaded);
    }
    return rc;
}

static int load_index_parts(
    struct mylite_db *database,
    int64_t index_id,
    const struct mylite_catalog_column_descriptor *columns,
    size_t column_count,
    struct loaded_index_part **out_parts,
    size_t *out_part_count
) {
    struct load_single_index_column_context context = {
        .database = database,
        .columns = columns,
        .column_count = column_count,
        .parts = NULL,
        .count = 0U,
        .capacity = 0U,
    };
    int rc = MYLITE_OK;

    if (out_parts == NULL || out_part_count == NULL) {
        return MYLITE_MISUSE;
    }
    *out_parts = NULL;
    *out_part_count = 0U;

    if (index_id < 0) {
        rc = mylite_temporary_catalog_for_each_index_column_in_index(
            &database->session.temporary_catalog,
            index_id,
            append_loaded_index_part,
            &context
        );
    } else {
        rc = mylite_catalog_for_each_index_column_in_index(
            database,
            index_id,
            append_loaded_index_part,
            &context
        );
    }
    if (rc != MYLITE_OK || context.count == 0U) {
        free(context.parts);
        set_runtime_error(database, "invalid index column descriptor");
        return rc == MYLITE_OK ? MYLITE_ERROR : rc;
    }

    *out_parts = context.parts;
    *out_part_count = context.count;
    return MYLITE_OK;
}

static int load_foreign_key_parts(
    struct mylite_db *database,
    const struct mylite_catalog_foreign_key_descriptor *foreign_key,
    const struct mylite_catalog_column_descriptor *child_columns,
    size_t child_column_count,
    const struct mylite_catalog_column_descriptor *parent_columns,
    size_t parent_column_count,
    struct loaded_foreign_key_part **out_parts,
    size_t *out_part_count
) {
    struct load_single_foreign_key_column_context context = {
        .database = database,
        .child_columns = child_columns,
        .child_column_count = child_column_count,
        .parent_columns = parent_columns,
        .parent_column_count = parent_column_count,
        .parts = NULL,
        .count = 0U,
        .capacity = 0U,
    };
    int rc = MYLITE_OK;

    if (out_parts == NULL || out_part_count == NULL || foreign_key == NULL) {
        return MYLITE_MISUSE;
    }
    *out_parts = NULL;
    *out_part_count = 0U;

    rc = mylite_catalog_for_each_foreign_key_column_in_foreign_key(
        database,
        foreign_key->foreign_key_id,
        append_loaded_foreign_key_part,
        &context
    );
    if (rc != MYLITE_OK || context.count == 0U) {
        free(context.parts);
        set_runtime_error(database, "invalid foreign-key column descriptor");
        return rc == MYLITE_OK ? MYLITE_ERROR : rc;
    }

    *out_parts = context.parts;
    *out_part_count = context.count;
    return MYLITE_OK;
}

static int append_loaded_index_part(
    const struct mylite_catalog_index_column_descriptor *index_column,
    void *user_data
) {
    struct load_single_index_column_context *context = user_data;
    size_t column_index = 0U;
    int rc = MYLITE_OK;

    if (index_column == NULL || context == NULL || context->database == NULL) {
        return MYLITE_MISUSE;
    }
    rc = find_column_index_by_id(
        context->columns,
        context->column_count,
        &column_index,
        index_column->column_id
    );
    if (rc != MYLITE_OK) {
        set_runtime_error(context->database, "index column descriptor is stale");
        return MYLITE_ERROR;
    }
    rc = reserve_loaded_index_parts(context, context->count + 1U);
    if (rc != MYLITE_OK) {
        return rc;
    }

    context->parts[context->count] = (struct loaded_index_part){
        .index_column = *index_column,
        .column = context->columns[column_index],
        .column_index = column_index,
    };
    ++context->count;

    return MYLITE_OK;
}

static int append_loaded_foreign_key_part(
    const struct mylite_catalog_foreign_key_column_descriptor *foreign_key_column,
    void *user_data
) {
    struct load_single_foreign_key_column_context *context = user_data;
    size_t child_column_index = 0U;
    size_t parent_column_index = 0U;
    int rc = MYLITE_OK;

    if (foreign_key_column == NULL || context == NULL || context->database == NULL) {
        return MYLITE_MISUSE;
    }
    rc = find_column_index_by_id(
        context->child_columns,
        context->child_column_count,
        &child_column_index,
        foreign_key_column->child_column_id
    );
    if (rc != MYLITE_OK) {
        set_runtime_error(context->database, "foreign-key child column descriptor is stale");
        return MYLITE_ERROR;
    }
    rc = find_column_index_by_id(
        context->parent_columns,
        context->parent_column_count,
        &parent_column_index,
        foreign_key_column->parent_column_id
    );
    if (rc != MYLITE_OK) {
        set_runtime_error(context->database, "foreign-key parent column descriptor is stale");
        return MYLITE_ERROR;
    }
    rc = reserve_loaded_foreign_key_parts(context, context->count + 1U);
    if (rc != MYLITE_OK) {
        return rc;
    }

    context->parts[context->count] = (struct loaded_foreign_key_part){
        .foreign_key_column = *foreign_key_column,
        .child_column = context->child_columns[child_column_index],
        .parent_column = context->parent_columns[parent_column_index],
        .child_column_index = child_column_index,
        .parent_column_index = parent_column_index,
    };
    ++context->count;

    return MYLITE_OK;
}

static int reserve_loaded_index_parts(
    struct load_single_index_column_context *context,
    size_t required_capacity
) {
    enum { initial_loaded_index_part_capacity = 4 };

    struct loaded_index_part *parts = NULL;
    size_t capacity = 0U;

    if (required_capacity <= context->capacity) {
        return MYLITE_OK;
    }
    capacity = context->capacity == 0U ? initial_loaded_index_part_capacity : context->capacity;
    while (capacity < required_capacity) {
        if (capacity > SIZE_MAX / 2U) {
            set_nomem_error(context->database);
            return MYLITE_NOMEM;
        }
        capacity *= 2U;
    }
    if (capacity > SIZE_MAX / sizeof(*parts)) {
        set_nomem_error(context->database);
        return MYLITE_NOMEM;
    }

    parts = realloc(context->parts, capacity * sizeof(*parts));
    if (parts == NULL) {
        set_nomem_error(context->database);
        return MYLITE_NOMEM;
    }

    context->parts = parts;
    context->capacity = capacity;
    return MYLITE_OK;
}

static int reserve_loaded_foreign_key_parts(
    struct load_single_foreign_key_column_context *context,
    size_t required_capacity
) {
    enum { initial_loaded_foreign_key_part_capacity = 4 };

    struct loaded_foreign_key_part *parts = NULL;
    size_t capacity = 0U;

    if (required_capacity <= context->capacity) {
        return MYLITE_OK;
    }
    capacity =
        context->capacity == 0U ? initial_loaded_foreign_key_part_capacity : context->capacity;
    while (capacity < required_capacity) {
        if (capacity > SIZE_MAX / 2U) {
            set_nomem_error(context->database);
            return MYLITE_NOMEM;
        }
        capacity *= 2U;
    }
    if (capacity > SIZE_MAX / sizeof(*parts)) {
        set_nomem_error(context->database);
        return MYLITE_NOMEM;
    }

    parts = realloc(context->parts, capacity * sizeof(*parts));
    if (parts == NULL) {
        set_nomem_error(context->database);
        return MYLITE_NOMEM;
    }

    context->parts = parts;
    context->capacity = capacity;
    return MYLITE_OK;
}

