static int append_predicate_work_item(
    struct mylite_db *database,
    struct predicate_work_item **items,
    size_t *item_count,
    struct predicate_work_item item
) {
    struct predicate_work_item *grown_items = NULL;
    size_t required_count = *item_count + 1U;

    if (required_count > SIZE_MAX / sizeof(*grown_items)) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    grown_items = realloc(*items, required_count * sizeof(*grown_items));
    if (grown_items == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    *items = grown_items;
    (*items)[*item_count] = item;
    *item_count = required_count;

    return MYLITE_OK;
}

static int append_predicate_result_index(
    struct mylite_db *database,
    size_t **indexes,
    size_t *index_count,
    size_t index
) {
    size_t *grown_indexes = NULL;
    size_t required_count = *index_count + 1U;

    if (required_count > SIZE_MAX / sizeof(*grown_indexes)) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    grown_indexes = realloc(*indexes, required_count * sizeof(*grown_indexes));
    if (grown_indexes == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }

    *indexes = grown_indexes;
    (*indexes)[*index_count] = index;
    *index_count = required_count;

    return MYLITE_OK;
}

static int pop_predicate_result_index(
    const size_t *indexes,
    size_t *index_count,
    size_t *out_index
) {
    if (indexes == NULL || index_count == NULL || *index_count == 0U || out_index == NULL) {
        return MYLITE_ERROR;
    }

    --(*index_count);
    *out_index = indexes[*index_count];
    return MYLITE_OK;
}

static int resolve_predicate_column_with_source_index(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    const struct select_source_context *source_context,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct mylite_catalog_column_descriptor *out_column,
    size_t *out_source_index
) {
    return resolve_descriptor_column_reference_with_source_index(
        database,
        column_node,
        source_context,
        COLUMN_REFERENCE_WHERE,
        "WHERE supports only unqualified predicate columns",
        table_columns,
        table_column_count,
        out_column,
        out_source_index
    );
}

static int convert_predicate_integer_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    const struct mylite_sql_ast_node *literal = value_node;
    bool is_negative = false;
    uint64_t magnitude = 0U;
    int rc = MYLITE_OK;

    *out_value = (struct planned_value){.is_null = false, .integer = 0};
    if (value_node == NULL || column == NULL) {
        set_unsupported_error(database, "WHERE supports only integer predicate literals");
        return MYLITE_ERROR;
    }

    if (value_node->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(value_node);

        if (operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            is_negative = true;
        } else if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE) {
            set_unsupported_error(database, "WHERE supports only integer predicate literals");
            return MYLITE_ERROR;
        }
        literal = child_at(value_node, 0U);
    }
    if (!boolean_literal_magnitude(literal, &magnitude)) {
        if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
            mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER) {
            set_unsupported_error(
                database,
                "WHERE supports only integer or boolean predicate literals"
            );
            return MYLITE_ERROR;
        }

        rc = parse_unsigned_integer_literal(&literal->span, &magnitude);
        if (rc != MYLITE_OK) {
            set_predicate_out_of_range_error(database, column->name);
            return MYLITE_ERROR;
        }
    }

    rc = convert_integer_for_predicate(
        database,
        magnitude,
        is_negative,
        column,
        &out_value->integer
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_value->is_null = false;

    return MYLITE_OK;
}

static int convert_predicate_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    if (column_descriptor_is_string_family(column)) {
        return convert_predicate_string_literal(database, value_node, out_value);
    }
    if (column_descriptor_is_enum(column)) {
        return convert_predicate_enum_literal(database, value_node, column, out_value);
    }
    if (column_descriptor_is_set(column)) {
        return convert_predicate_set_literal(database, value_node, column, out_value);
    }
    if (column_descriptor_is_bit(column)) {
        return convert_bit_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_year(column)) {
        return convert_predicate_year_literal(database, value_node, column, out_value);
    }
    if (column_descriptor_is_date(column)) {
        return convert_predicate_date_literal(database, value_node, column, out_value);
    }
    if (column_descriptor_is_time(column)) {
        return convert_predicate_time_literal(database, value_node, column, out_value);
    }
    if (column_descriptor_is_datetime(column)) {
        return convert_predicate_datetime_literal(database, value_node, column, out_value);
    }
    if (column_descriptor_is_timestamp(column)) {
        return convert_predicate_timestamp_literal(database, value_node, column, out_value);
    }
    return convert_predicate_integer_literal(database, value_node, column, out_value);
}

static int convert_predicate_enum_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    const struct mylite_sql_ast_node *literal = value_node;

    if (value_node != NULL && value_node->kind == MYLITE_SQL_AST_LITERAL &&
        mylite_sql_ast_node_literal_kind(value_node) == MYLITE_SQL_AST_LITERAL_NULL) {
        *out_value = (struct planned_value){.is_null = true, .is_text = false, .integer = 0};
        return MYLITE_OK;
    }
    if (value_node != NULL && value_node->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        literal = child_at(value_node, 0U);
    }
    if (literal != NULL && literal->kind == MYLITE_SQL_AST_LITERAL &&
        mylite_sql_ast_node_literal_kind(literal) == MYLITE_SQL_AST_LITERAL_STRING) {
        return convert_enum_string_literal(
            database,
            value_node,
            column,
            1U,
            false,
            false,
            ENUM_STRING_PRESERVE_TRAILING_SPACES,
            out_value
        );
    }
    return convert_enum_integer_literal(database, value_node, column, 1U, false, out_value);
}

static int convert_predicate_set_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    const struct mylite_sql_ast_node *literal = value_node;

    if (value_node != NULL && value_node->kind == MYLITE_SQL_AST_LITERAL &&
        mylite_sql_ast_node_literal_kind(value_node) == MYLITE_SQL_AST_LITERAL_NULL) {
        *out_value = (struct planned_value){.is_null = true, .is_text = false, .integer = 0};
        return MYLITE_OK;
    }
    if (value_node != NULL && value_node->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        literal = child_at(value_node, 0U);
    }
    if (literal != NULL && literal->kind == MYLITE_SQL_AST_LITERAL &&
        mylite_sql_ast_node_literal_kind(literal) == MYLITE_SQL_AST_LITERAL_STRING) {
        return convert_set_string_literal(
            database,
            literal,
            column,
            1U,
            false,
            false,
            false,
            out_value
        );
    }
    return convert_set_integer_literal(database, value_node, column, 1U, false, out_value);
}

static int convert_predicate_year_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    return convert_year_literal(database, value_node, column, 1U, false, out_value);
}

static int convert_predicate_string_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    struct planned_value *out_value
) {
    char *text = NULL;
    size_t text_length = 0U;
    int rc = MYLITE_OK;

    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(value_node) != MYLITE_SQL_AST_LITERAL_STRING) {
        set_unsupported_error(database, "WHERE string predicates support only string literals");
        return MYLITE_ERROR;
    }

    rc = decode_sql_string_literal(
        database,
        value_node,
        "WHERE string predicates support only string literals",
        "WHERE string predicate literals do not support NUL bytes",
        &text,
        &text_length
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (!text_value_is_supported_string_key(text, text_length)) {
        free(text);
        set_unsupported_error(database, "WHERE string predicate literals support only ASCII text");
        return MYLITE_ERROR;
    }

    return assign_text_value(database, text, text_length, out_value);
}

static int convert_predicate_string_pattern_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    struct planned_value *out_value
) {
    char *text = NULL;
    size_t text_length = 0U;
    int rc = MYLITE_OK;

    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(value_node) != MYLITE_SQL_AST_LITERAL_STRING) {
        set_unsupported_error(
            database,
            "WHERE LIKE predicates support only string pattern literals"
        );
        return MYLITE_ERROR;
    }

    rc = decode_sql_string_literal(
        database,
        value_node,
        "WHERE LIKE predicates support only string pattern literals",
        "WHERE LIKE pattern literals do not support NUL bytes",
        &text,
        &text_length
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (!text_value_is_supported_string_key(text, text_length)) {
        free(text);
        set_unsupported_error(database, "WHERE LIKE pattern literals support only ASCII text");
        return MYLITE_ERROR;
    }

    return assign_text_value(database, text, text_length, out_value);
}

static int convert_predicate_date_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    char *text = NULL;
    size_t text_length = 0U;
    int rc = MYLITE_OK;

    (void)column;
    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(value_node) != MYLITE_SQL_AST_LITERAL_STRING) {
        set_unsupported_error(database, "WHERE DATE predicates support only string literals");
        return MYLITE_ERROR;
    }

    rc = decode_sql_string_literal(
        database,
        value_node,
        "WHERE DATE predicates support only string literals",
        "WHERE DATE predicate literals do not support NUL bytes",
        &text,
        &text_length
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (!predicate_date_text_admitted(database, text, text_length)) {
        set_incorrect_date_literal_error(database, text);
        free(text);
        return MYLITE_ERROR;
    }

    return assign_text_value(database, text, text_length, out_value);
}

static int convert_predicate_time_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    char *text = NULL;
    size_t text_length = 0U;
    int64_t seconds = 0;
    int rc = MYLITE_OK;

    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(value_node) != MYLITE_SQL_AST_LITERAL_STRING) {
        set_unsupported_error(database, "WHERE TIME predicates support only string literals");
        return MYLITE_ERROR;
    }

    rc = decode_sql_string_literal(
        database,
        value_node,
        "WHERE TIME predicates support only string literals",
        "WHERE TIME predicate literals do not support NUL bytes",
        &text,
        &text_length
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (!time_text_to_seconds(text, text_length, &seconds)) {
        set_incorrect_time_value_error(database, text, column->name, 1U);
        free(text);
        return MYLITE_ERROR;
    }
    free(text);

    *out_value = (struct planned_value){.is_null = false, .is_text = false, .integer = seconds};
    return MYLITE_OK;
}

static int convert_predicate_datetime_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    char *text = NULL;
    size_t text_length = 0U;
    int rc = MYLITE_OK;

    (void)column;
    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(value_node) != MYLITE_SQL_AST_LITERAL_STRING) {
        set_unsupported_error(database, "WHERE DATETIME predicates support only string literals");
        return MYLITE_ERROR;
    }

    rc = decode_sql_string_literal(
        database,
        value_node,
        "WHERE DATETIME predicates support only string literals",
        "WHERE DATETIME predicate literals do not support NUL bytes",
        &text,
        &text_length
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (!predicate_datetime_text_admitted(database, text, text_length)) {
        set_incorrect_datetime_literal_error(database, text);
        free(text);
        return MYLITE_ERROR;
    }

    return assign_text_value(database, text, text_length, out_value);
}

static int convert_predicate_timestamp_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    char *text = NULL;
    size_t text_length = 0U;
    int rc = MYLITE_OK;

    (void)column;
    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(value_node) != MYLITE_SQL_AST_LITERAL_STRING) {
        set_unsupported_error(database, "WHERE TIMESTAMP predicates support only string literals");
        return MYLITE_ERROR;
    }

    rc = decode_sql_string_literal(
        database,
        value_node,
        "WHERE TIMESTAMP predicates support only string literals",
        "WHERE TIMESTAMP predicate literals do not support NUL bytes",
        &text,
        &text_length
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (!predicate_timestamp_text_admitted(database, text, text_length)) {
        set_incorrect_timestamp_value_error(database, text);
        free(text);
        return MYLITE_ERROR;
    }

    return assign_text_value(database, text, text_length, out_value);
}

static bool predicate_date_text_admitted(
    const struct mylite_db *database,
    const char *text,
    size_t text_length
) {
    enum temporal_text_kind kind = classify_date_text(text, text_length);

    switch (kind) {
    case TEMPORAL_TEXT_NORMAL:
        return true;
    case TEMPORAL_TEXT_FULL_ZERO:
        if (temporal_sql_mode_has_no_zero_date(database)) {
            return false;
        }
        return true;
    case TEMPORAL_TEXT_PARTIAL_ZERO:
        if (temporal_sql_mode_has_no_zero_in_date(database)) {
            return false;
        }
        return true;
    case TEMPORAL_TEXT_ALLOW_INVALID_CANDIDATE:
        return temporal_sql_mode_has_allow_invalid_dates(database);
    case TEMPORAL_TEXT_INVALID:
    case TEMPORAL_TEXT_DEFERRED:
        return false;
    }
    return false;
}

static bool predicate_datetime_text_admitted(
    const struct mylite_db *database,
    const char *text,
    size_t text_length
) {
    enum temporal_text_kind kind = classify_datetime_text(text, text_length);

    switch (kind) {
    case TEMPORAL_TEXT_NORMAL:
        return true;
    case TEMPORAL_TEXT_FULL_ZERO:
        if (temporal_sql_mode_has_no_zero_date(database)) {
            return false;
        }
        return true;
    case TEMPORAL_TEXT_PARTIAL_ZERO:
        if (temporal_sql_mode_has_no_zero_in_date(database)) {
            return false;
        }
        return true;
    case TEMPORAL_TEXT_ALLOW_INVALID_CANDIDATE:
        return temporal_sql_mode_has_allow_invalid_dates(database);
    case TEMPORAL_TEXT_INVALID:
    case TEMPORAL_TEXT_DEFERRED:
        return false;
    }
    return false;
}

static bool predicate_timestamp_text_admitted(
    const struct mylite_db *database,
    const char *text,
    size_t text_length
) {
    if (timestamp_text_is_canonical_valid(text, text_length)) {
        return true;
    }
    if (datetime_text_is_zero_datetime(text, text_length)) {
        if (temporal_sql_mode_has_no_zero_date(database)) {
            return false;
        }
        return true;
    }
    return false;
}

static int convert_integer_for_predicate(
    struct mylite_db *database,
    uint64_t magnitude,
    bool is_negative,
    const struct mylite_catalog_column_descriptor *column,
    int64_t *out_value
) {
    const uint64_t bigint_signed_negative_abs_max = 9223372036854775808ULL;
    struct integer_column_range range = {0};
    int rc = integer_range_for_column(
        database,
        column,
        "WHERE supports only baseline integer columns",
        &range
    );

    if (rc != MYLITE_OK) {
        return rc;
    }
    if (is_negative) {
        if ((range.negative_abs_max == 0U && magnitude != 0U) ||
            magnitude > range.negative_abs_max) {
            set_predicate_out_of_range_error(database, column->name);
            return MYLITE_ERROR;
        }
        if (magnitude == bigint_signed_negative_abs_max) {
            *out_value = INT64_MIN;
        } else {
            *out_value = -(int64_t)magnitude;
        }
        return MYLITE_OK;
    }
    if (magnitude > range.positive_max) {
        set_predicate_out_of_range_error(database, column->name);
        return MYLITE_ERROR;
    }

    *out_value = (int64_t)magnitude;
    return MYLITE_OK;
}

static int plan_select_order(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *order_clause,
    const struct select_source_context *source_context,
    const struct planned_select *select_plan,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct planned_select_order *out_order
) {
    const struct mylite_sql_ast_node *direction = NULL;
    bool resolved_alias = false;
    int rc = MYLITE_OK;

    out_order->has_order = false;
    out_order->column = (struct mylite_catalog_column_descriptor){0};
    out_order->column_source_index = 0U;
    out_order->direction = PLANNED_SELECT_ORDER_DEFAULT;
    out_order->qualify_column_reference = select_source_context_is_joined(source_context);
    if (order_clause == NULL) {
        return MYLITE_OK;
    }
    if (order_clause->kind != MYLITE_SQL_AST_ORDER_BY_CLAUSE) {
        set_unsupported_error(database, "SELECT supports only one descriptor ORDER BY column");
        return MYLITE_ERROR;
    }

    rc = resolve_order_alias(
        database,
        child_at(order_clause, 0U),
        select_plan,
        &out_order->column,
        &out_order->column_source_index,
        &resolved_alias
    );
    if (rc == MYLITE_OK && !resolved_alias) {
        rc = resolve_order_column(
            database,
            child_at(order_clause, 0U),
            source_context,
            table_columns,
            table_column_count,
            &out_order->column,
            &out_order->column_source_index
        );
    }
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (column_descriptor_is_set(&out_order->column)) {
        set_unsupported_error(database, "ORDER BY does not yet support SET columns");
        return MYLITE_ERROR;
    }
    if (rc == MYLITE_OK && !column_descriptor_is_date(&out_order->column) &&
        !column_descriptor_is_time(&out_order->column) &&
        !column_descriptor_is_datetime(&out_order->column) &&
        !column_descriptor_is_timestamp(&out_order->column) &&
        !column_descriptor_is_year(&out_order->column) &&
        !column_descriptor_is_bit(&out_order->column)) {
        struct integer_column_range range = {0};

        rc = integer_range_for_column(
            database,
            &out_order->column,
            "ORDER BY supports only integer, BIT, YEAR, DATE, TIME, DATETIME, or TIMESTAMP "
            "descriptor columns",
            &range
        );
    }
    if (rc != MYLITE_OK) {
        return rc;
    }

    out_order->has_order = true;
    out_order->direction = PLANNED_SELECT_ORDER_ASC;
    direction = child_at(order_clause, 1U);
    if (mylite_sql_ast_node_order_direction(direction) == MYLITE_SQL_AST_ORDER_DIRECTION_DESC) {
        out_order->direction = PLANNED_SELECT_ORDER_DESC;
    }

    return MYLITE_OK;
}

static int resolve_order_alias(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    const struct planned_select *select_plan,
    struct mylite_catalog_column_descriptor *out_column,
    size_t *out_source_index,
    bool *out_resolved
) {
    char *order_name = NULL;
    bool found = false;
    int rc = MYLITE_OK;

    *out_resolved = false;
    if (select_plan == NULL || column_node == NULL ||
        column_node->kind != MYLITE_SQL_AST_IDENTIFIER) {
        return MYLITE_OK;
    }

    rc = copy_select_item_identifier_alias_text(database, column_node, &order_name);
    if (rc != MYLITE_OK) {
        return rc;
    }

    for (size_t column_index = 0U; column_index < select_plan->column_count; ++column_index) {
        const struct mylite_sql_ast_node *alias = select_plan->column_aliases[column_index];
        char *alias_text = NULL;

        if (alias == NULL) {
            continue;
        }

        rc = copy_select_item_alias_text(database, alias, &alias_text);
        if (rc != MYLITE_OK) {
            free(order_name);
            return rc;
        }
        if (text_equals_ascii_case_insensitive(alias_text, order_name)) {
            if (found) {
                free(alias_text);
                set_ambiguous_order_column_error(database, order_name);
                free(order_name);
                return MYLITE_ERROR;
            }
            *out_column = select_plan->columns[column_index];
            if (out_source_index != NULL) {
                *out_source_index = select_plan->column_source_indexes[column_index];
            }
            found = true;
        }
        free(alias_text);
    }

    free(order_name);
    *out_resolved = found;
    return MYLITE_OK;
}

static int resolve_order_column(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *column_node,
    const struct select_source_context *source_context,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct mylite_catalog_column_descriptor *out_column,
    size_t *out_source_index
) {
    return resolve_descriptor_column_reference_with_source_index(
        database,
        column_node,
        source_context,
        COLUMN_REFERENCE_ORDER,
        "ORDER BY supports only unqualified descriptor columns",
        table_columns,
        table_column_count,
        out_column,
        out_source_index
    );
}

static int plan_select_limit(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *limit_clause,
    struct planned_select_limit *out_limit
) {
    int rc = MYLITE_OK;

    out_limit->has_limit = false;
    out_limit->row_count = 0;
    out_limit->has_offset = false;
    out_limit->offset = 0;
    if (limit_clause == NULL) {
        return MYLITE_OK;
    }
    if (limit_clause->kind != MYLITE_SQL_AST_LIMIT_CLAUSE) {
        set_unsupported_error(database, "SELECT supports only literal LIMIT clauses");
        return MYLITE_ERROR;
    }

    rc = convert_limit_integer_literal(database, child_at(limit_clause, 0U), &out_limit->row_count);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_limit->has_limit = true;

    if (child_at(limit_clause, 1U) != NULL) {
        rc =
            convert_limit_integer_literal(database, child_at(limit_clause, 1U), &out_limit->offset);
        if (rc != MYLITE_OK) {
            return rc;
        }
        out_limit->has_offset = true;
    }

    return MYLITE_OK;
}

static int plan_delete_limit(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *limit_clause,
    struct planned_select_limit *out_limit
) {
    int rc = MYLITE_OK;

    out_limit->has_limit = false;
    out_limit->row_count = 0;
    out_limit->has_offset = false;
    out_limit->offset = 0;
    if (limit_clause == NULL) {
        return MYLITE_OK;
    }
    if (limit_clause->kind != MYLITE_SQL_AST_LIMIT_CLAUSE) {
        set_unsupported_error(database, "DELETE supports only LIMIT row_count");
        return MYLITE_ERROR;
    }
    if (child_at(limit_clause, 1U) != NULL) {
        set_unsupported_error(database, "DELETE supports only LIMIT row_count");
        return MYLITE_ERROR;
    }

    rc = convert_limit_integer_literal(database, child_at(limit_clause, 0U), &out_limit->row_count);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_limit->has_limit = true;

    return MYLITE_OK;
}

static int plan_update_assignment(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *assignment_list,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct planned_update *out_plan
) {
    const struct mylite_sql_ast_node *assignment = child_at(assignment_list, 0U);
    const struct mylite_sql_ast_node *target = NULL;
    char column_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t column_index = 0U;
    int rc = MYLITE_OK;

    if (assignment_list == NULL || assignment_list->kind != MYLITE_SQL_AST_UPDATE_ASSIGNMENT_LIST) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    if (mylite_sql_ast_node_child_count(assignment_list) == 0U) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    if (mylite_sql_ast_node_child_count(assignment_list) != 1U) {
        rc = plan_update_multiple_assignments(
            database,
            assignment_list,
            table_columns,
            table_column_count,
            out_plan
        );
        if (rc == MYLITE_OK) {
            rc = validate_update_multiple_auto_update_columns(
                database,
                out_plan,
                table_columns,
                table_column_count
            );
        }
        return rc;
    }
    if (assignment == NULL || assignment->kind != MYLITE_SQL_AST_UPDATE_ASSIGNMENT) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    target = child_at(assignment, 0U);
    if (target == NULL || target->kind != MYLITE_SQL_AST_IDENTIFIER) {
        set_unsupported_error(database, "UPDATE supports only unqualified assignment columns");
        return MYLITE_ERROR;
    }
    rc = copy_identifier_text(target, column_name, sizeof(column_name), database);
    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = find_column_index(table_columns, table_column_count, column_name, &column_index);
    if (rc != MYLITE_OK) {
        set_unknown_column_error(database, column_name);
        return MYLITE_ERROR;
    }

    out_plan->assignment_column = table_columns[column_index];
    out_plan->assignment_value_node = child_at(assignment, 1U);
    if (out_plan->assignment_value_node == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    rc = plan_update_arithmetic_assignment(database, table_columns, table_column_count, out_plan);
    if (rc != MYLITE_OK ||
        out_plan->assignment_value_kind == PLANNED_UPDATE_ASSIGNMENT_SAME_COLUMN_ARITHMETIC) {
        return rc;
    }

    return plan_update_scalar_subquery_assignment(database, out_plan);
}

static int plan_update_multiple_assignments(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *assignment_list,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct planned_update *out_plan
) {
    size_t assignment_count = mylite_sql_ast_node_child_count(assignment_list);
    int rc = MYLITE_OK;

    out_plan->assignments = calloc(assignment_count, sizeof(*out_plan->assignments));
    if (out_plan->assignments == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    out_plan->assignment_count = assignment_count;

    for (size_t assignment_index = 0U; rc == MYLITE_OK && assignment_index < assignment_count;
         ++assignment_index) {
        rc = plan_update_multiple_assignment(
            database,
            child_at(assignment_list, assignment_index),
            table_columns,
            table_column_count,
            out_plan,
            assignment_index
        );
    }

    return rc;
}

static int plan_update_multiple_assignment(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *assignment,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct planned_update *out_plan,
    size_t assignment_index
) {
    const struct mylite_sql_ast_node *target = NULL;
    const struct mylite_sql_ast_node *value_node = NULL;
    char column_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t column_index = 0U;
    int rc = MYLITE_OK;

    if (assignment == NULL || assignment->kind != MYLITE_SQL_AST_UPDATE_ASSIGNMENT) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    target = child_at(assignment, 0U);
    if (target == NULL || target->kind != MYLITE_SQL_AST_IDENTIFIER) {
        set_update_multiple_assignment_unsupported_error(database);
        return MYLITE_ERROR;
    }
    rc = copy_identifier_text(target, column_name, sizeof(column_name), database);
    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = find_column_index(table_columns, table_column_count, column_name, &column_index);
    if (rc != MYLITE_OK) {
        set_unknown_column_error(database, column_name);
        return MYLITE_ERROR;
    }
    for (size_t index = 0U; index < assignment_index; ++index) {
        if (out_plan->assignments[index].column.column_id ==
            table_columns[column_index].column_id) {
            set_update_duplicate_assignment_unsupported_error(database);
            return MYLITE_ERROR;
        }
    }
    if (column_descriptor_is_auto_increment(&table_columns[column_index]) ||
        update_column_id_is_keyed(out_plan, table_columns[column_index].column_id)) {
        set_update_multiple_assignment_unsupported_error(database);
        return MYLITE_ERROR;
    }

    value_node = child_at(assignment, 1U);
    if (!update_assignment_value_is_multi_constant_supported(value_node)) {
        set_update_multiple_assignment_unsupported_error(database);
        return MYLITE_ERROR;
    }

    out_plan->assignments[assignment_index].column = table_columns[column_index];
    out_plan->assignments[assignment_index].value_node = value_node;

    return MYLITE_OK;
}

static int plan_update_arithmetic_assignment(
    struct mylite_db *database,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count,
    struct planned_update *out_plan
) {
    const struct mylite_sql_ast_node *value_node = NULL;
    const struct mylite_sql_ast_node *source = NULL;
    const struct mylite_sql_ast_node *delta = NULL;
    enum mylite_sql_ast_operator operator_kind = MYLITE_SQL_AST_OPERATOR_NONE;
    char source_name[MYLITE_CATALOG_IDENTIFIER_CAPACITY];
    size_t source_index = 0U;
    int rc = MYLITE_OK;

    value_node = unwrap_parenthesized_expression(out_plan->assignment_value_node);
    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_BINARY_EXPRESSION) {
        return MYLITE_OK;
    }

    operator_kind = mylite_sql_ast_node_operator(value_node);
    if (operator_kind != MYLITE_SQL_AST_OPERATOR_ADD &&
        operator_kind != MYLITE_SQL_AST_OPERATOR_SUBTRACT) {
        set_update_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }

    source = child_at(value_node, 0U);
    delta = child_at(value_node, 1U);
    if (source == NULL || source->kind != MYLITE_SQL_AST_IDENTIFIER || delta == NULL ||
        delta->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(delta) != MYLITE_SQL_AST_LITERAL_INTEGER) {
        set_update_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }

    rc = copy_identifier_text(source, source_name, sizeof(source_name), database);
    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = find_column_index(table_columns, table_column_count, source_name, &source_index);
    if (rc != MYLITE_OK) {
        set_unknown_column_error(database, source_name);
        return MYLITE_ERROR;
    }
    if (table_columns[source_index].column_id != out_plan->assignment_column.column_id) {
        set_update_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }

    out_plan->assignment_value_kind = PLANNED_UPDATE_ASSIGNMENT_SAME_COLUMN_ARITHMETIC;
    out_plan->arithmetic_operator = operator_kind;
    out_plan->arithmetic_delta_node = delta;

    return validate_update_arithmetic_assignment_target(database, out_plan);
}

static int validate_update_arithmetic_assignment_target(
    struct mylite_db *database,
    const struct planned_update *plan
) {
    struct integer_column_range range = {0};
    int rc = integer_range_for_column(
        database,
        &plan->assignment_column,
        "UPDATE arithmetic assignment supports only integer columns",
        &range
    );

    (void)range;
    if (rc != MYLITE_OK) {
        return rc;
    }
    if (column_descriptor_is_auto_increment(&plan->assignment_column) ||
        update_assignment_column_is_keyed(plan)) {
        set_update_arithmetic_unsupported_error(database);
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static bool update_assignment_column_is_keyed(const struct planned_update *plan) {
    if (plan == NULL) {
        return false;
    }
    return update_column_id_is_keyed(plan, plan->assignment_column.column_id);
}

static bool update_column_id_is_keyed(const struct planned_update *plan, int64_t column_id) {
    if (plan == NULL) {
        return false;
    }
    for (size_t index = 0U; index < plan->index_count; ++index) {
        const struct loaded_index_info *key = &plan->indexes[index];

        if ((key->index.kind == MYLITE_CATALOG_INDEX_KIND_PRIMARY || key->index.is_unique) &&
            loaded_index_contains_column_id(key, column_id)) {
            return true;
        }
    }

    return false;
}

static bool update_assignment_value_is_multi_constant_supported(
    const struct mylite_sql_ast_node *value_node
) {
    value_node = unwrap_parenthesized_expression(value_node);
    if (value_node == NULL) {
        return false;
    }

    switch (value_node->kind) {
    case MYLITE_SQL_AST_LITERAL:
    case MYLITE_SQL_AST_DML_DEFAULT_VALUE:
    case MYLITE_SQL_AST_CURRENT_TIMESTAMP_VALUE:
    case MYLITE_SQL_AST_CURRENT_TIMESTAMP_ARGUMENT_COUNT_ERROR:
        return true;
    case MYLITE_SQL_AST_UNARY_EXPRESSION:
        return update_assignment_unary_value_is_multi_constant_supported(value_node);
    default:
        return false;
    }
}

static bool update_assignment_unary_value_is_multi_constant_supported(
    const struct mylite_sql_ast_node *value_node
) {
    const struct mylite_sql_ast_node *operand = NULL;
    enum mylite_sql_ast_operator operator_kind = MYLITE_SQL_AST_OPERATOR_NONE;
    enum mylite_sql_ast_literal_kind literal_kind = MYLITE_SQL_AST_LITERAL_NULL;

    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_UNARY_EXPRESSION) {
        return false;
    }
    operator_kind = mylite_sql_ast_node_operator(value_node);
    if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE &&
        operator_kind != MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
        return false;
    }

    operand = child_at(value_node, 0U);
    if (operand == NULL || operand->kind != MYLITE_SQL_AST_LITERAL) {
        return false;
    }
    literal_kind = mylite_sql_ast_node_literal_kind(operand);
    if (literal_kind == MYLITE_SQL_AST_LITERAL_INTEGER ||
        literal_kind == MYLITE_SQL_AST_LITERAL_DECIMAL ||
        literal_kind == MYLITE_SQL_AST_LITERAL_FLOAT) {
        return true;
    }
    return false;
}

static int validate_update_multiple_auto_update_columns(
    struct mylite_db *database,
    const struct planned_update *plan,
    const struct mylite_catalog_column_descriptor *table_columns,
    size_t table_column_count
) {
    for (size_t column_index = 0U; column_index < table_column_count; ++column_index) {
        if (planned_update_column_has_auto_update(plan, &table_columns[column_index]) &&
            update_column_id_is_keyed(plan, table_columns[column_index].column_id)) {
            set_update_multiple_assignment_unsupported_error(database);
            return MYLITE_ERROR;
        }
    }

    return MYLITE_OK;
}

static void set_update_multiple_assignment_unsupported_error(struct mylite_db *database) {
    set_unsupported_error(
        database,
        "UPDATE multiple assignments support only distinct unqualified non-key constant "
        "assignments"
    );
}

static void set_update_duplicate_assignment_unsupported_error(struct mylite_db *database) {
    set_unsupported_error(database, "UPDATE multiple assignments do not support duplicate targets");
}

static int plan_update_scalar_subquery_assignment(
    struct mylite_db *database,
    struct planned_update *out_plan
) {
    const struct mylite_sql_ast_node *value_node = NULL;
    const struct mylite_sql_ast_node *statement = NULL;
    int rc = MYLITE_OK;

    if (out_plan == NULL) {
        return MYLITE_MISUSE;
    }

    value_node = unwrap_parenthesized_expression(out_plan->assignment_value_node);
    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_SCALAR_SUBQUERY) {
        return MYLITE_OK;
    }
    if (mylite_sql_ast_node_child_count(value_node) != 1U) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only parenthesized SELECT"
        );
        return MYLITE_ERROR;
    }

    statement = child_at(value_node, 0U);
    rc = validate_update_scalar_subquery_select(database, statement);
    if (rc == MYLITE_OK) {
        rc = plan_select(database, statement, &out_plan->assignment_subquery);
    }
    if (rc == MYLITE_OK && out_plan->assignment_subquery.column_count != 1U) {
        set_scalar_subquery_column_count_error(database);
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK &&
        out_plan->assignment_subquery.table.table_id == out_plan->table.table_id) {
        set_update_table_used_error(database, out_plan->target.table_name);
        rc = MYLITE_ERROR;
    }
    if (rc == MYLITE_OK) {
        out_plan->assignment_value_is_scalar_subquery = true;
    }

    return rc;
}

static int validate_update_scalar_subquery_select(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *statement
) {
    const struct mylite_sql_ast_node *select_list = NULL;
    const struct mylite_sql_ast_node *from_clause = NULL;

    if (statement == NULL || statement->kind != MYLITE_SQL_AST_SELECT_STATEMENT) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only parenthesized SELECT"
        );
        return MYLITE_ERROR;
    }
    if (mylite_sql_ast_node_select_modifier(statement) != MYLITE_SQL_AST_SELECT_MODIFIER_DEFAULT ||
        mylite_sql_ast_node_select_options(statement) != 0U ||
        mylite_sql_ast_node_select_calc_found_rows(statement) != 0 ||
        mylite_sql_ast_node_select_locking_clause(statement) !=
            MYLITE_SQL_AST_SELECT_LOCKING_CLAUSE_NONE) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only plain inner SELECT"
        );
        return MYLITE_ERROR;
    }

    select_list = child_at(statement, 0U);
    if (select_list == NULL || select_list->kind != MYLITE_SQL_AST_SELECT_LIST ||
        select_list_is_wildcard(select_list)) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only one explicit source column"
        );
        return MYLITE_ERROR;
    }

    from_clause = child_at(statement, 1U);
    if (from_clause == NULL || from_clause->kind != MYLITE_SQL_AST_FROM_TABLE) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only one descriptor table source"
        );
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int convert_update_value(
    struct mylite_db *database,
    const struct planned_update *plan,
    struct planned_value *out_value
) {
    const struct mylite_sql_ast_node *value_node = NULL;
    const struct mylite_catalog_column_descriptor *column = NULL;

    if (plan == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }
    value_node = unwrap_parenthesized_expression(plan->assignment_value_node);
    column = &plan->assignment_column;
    if (value_node == NULL || column == NULL || out_value == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    if (value_node->kind == MYLITE_SQL_AST_SCALAR_SUBQUERY) {
        planned_value_deinit(out_value);
        *out_value = (struct planned_value){.is_null = true, .is_text = false, .integer = 0};
        return materialize_update_scalar_subquery_value(database, plan, out_value);
    }

    return convert_update_value_for_column(database, value_node, column, out_value);
}

static int convert_update_value_for_column(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    value_node = unwrap_parenthesized_expression(value_node);
    if (value_node == NULL || column == NULL || out_value == NULL) {
        set_parse_error(database, NULL);
        return MYLITE_ERROR;
    }

    planned_value_deinit(out_value);
    *out_value = (struct planned_value){.is_null = true, .is_text = false, .integer = 0};
    if (value_node->kind == MYLITE_SQL_AST_DML_DEFAULT_VALUE) {
        return materialize_dml_default_value(database, column, false, out_value);
    }
    if (value_node->kind == MYLITE_SQL_AST_CURRENT_TIMESTAMP_VALUE) {
        if (column_descriptor_is_datetime(column) || column_descriptor_is_timestamp(column)) {
            return make_current_timestamp_value(database, out_value);
        }
        set_unsupported_error(
            database,
            "CURRENT_TIMESTAMP values are supported only for DATETIME and TIMESTAMP columns"
        );
        return MYLITE_ERROR;
    }
    if (value_node->kind == MYLITE_SQL_AST_CURRENT_TIMESTAMP_ARGUMENT_COUNT_ERROR) {
        set_native_function_parameter_count_error(database, "CURRENT_TIMESTAMP");
        return MYLITE_ERROR;
    }
    if (value_node->kind == MYLITE_SQL_AST_LITERAL &&
        mylite_sql_ast_node_literal_kind(value_node) == MYLITE_SQL_AST_LITERAL_NULL) {
        if (!column->is_nullable) {
            set_bad_null_error(database, column->name);
            return MYLITE_ERROR;
        }
        return MYLITE_OK;
    }

    return convert_update_column_value(database, value_node, column, out_value);
}

static int convert_update_column_value(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    if (column_descriptor_is_char(column)) {
        return convert_char_literal(database, value_node, column, 1U, out_value);
    }
    if (column_descriptor_is_varchar(column)) {
        return convert_varchar_literal(database, value_node, column, 1U, out_value);
    }
    if (column_descriptor_is_text_family(column)) {
        return convert_text_family_literal(database, value_node, column, 1U, out_value);
    }
    if (column_descriptor_is_json(column)) {
        return convert_json_literal(database, value_node, column, out_value);
    }
    if (column_descriptor_is_enum(column)) {
        return convert_enum_literal(database, value_node, column, 1U, out_value);
    }
    if (column_descriptor_is_set(column)) {
        return convert_set_literal(database, value_node, column, 1U, out_value);
    }
    if (column_descriptor_is_binary_string_family(column)) {
        return convert_binary_string_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_bit(column)) {
        return convert_bit_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_year(column)) {
        return convert_year_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_decimal(column)) {
        return convert_decimal_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_approximate(column)) {
        return convert_approximate_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_date(column)) {
        return convert_date_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_time(column)) {
        return convert_time_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_datetime(column)) {
        return convert_datetime_literal(database, value_node, column, 1U, false, out_value);
    }
    if (column_descriptor_is_timestamp(column)) {
        return convert_timestamp_literal(database, value_node, column, 1U, false, out_value);
    }

    return convert_update_integer_literal(database, value_node, column, out_value);
}

static int materialize_update_scalar_subquery_value(
    struct mylite_db *database,
    const struct planned_update *plan,
    struct planned_value *out_value
) {
    sqlite3_stmt *statement = NULL;
    struct planned_select scalar_plan = plan->assignment_subquery;
    char *sql = NULL;
    int rc = MYLITE_OK;

    if (!plan->assignment_value_is_scalar_subquery ||
        plan->assignment_subquery.column_count != 1U) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment supports only one descriptor source column"
        );
        return MYLITE_ERROR;
    }

    cap_update_scalar_subquery_limit(&scalar_plan.limit);
    rc = build_select_sql(&scalar_plan, &sql);
    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, sql, &statement);
    }
    if (rc == MYLITE_OK) {
        rc = bind_select_parameters(statement, &scalar_plan);
    }
    if (rc == MYLITE_OK) {
        rc = step_update_scalar_subquery_value(database, statement, plan, out_value);
    }
    rc = finalize_sqlite_statement(statement, rc);
    free(sql);

    if (rc == MYLITE_NOMEM) {
        set_nomem_error(database);
        return rc;
    }
    if (rc != MYLITE_OK &&
        mylite_diagnostics_errcode(mylite_connection_diagnostics(database)) == MYLITE_OK) {
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }

    return rc;
}

static void cap_update_scalar_subquery_limit(struct planned_select_limit *limit) {
    if (limit == NULL) {
        return;
    }
    if (!limit->has_limit) {
        *limit = (struct planned_select_limit){
            .has_limit = true,
            .row_count = 2,
            .has_offset = false,
            .offset = 0,
        };
        return;
    }
    if (limit->row_count > 2) {
        limit->row_count = 2;
    }
}

static int step_update_scalar_subquery_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct planned_update *plan,
    struct planned_value *out_value
) {
    int sqlite_rc = sqlite3_step(statement);
    int rc = MYLITE_OK;

    if (sqlite_rc == SQLITE_DONE) {
        if (!plan->assignment_column.is_nullable) {
            set_bad_null_error(database, plan->assignment_column.name);
            return MYLITE_ERROR;
        }
        *out_value = (struct planned_value){.is_null = true};
        return MYLITE_OK;
    }
    if (sqlite_rc != SQLITE_ROW) {
        return mylite_sqlite_status_to_mylite(sqlite_rc);
    }

    rc = materialize_update_scalar_subquery_sqlite_value(database, statement, plan, out_value);
    if (rc != MYLITE_OK) {
        return rc;
    }

    sqlite_rc = sqlite3_step(statement);
    if (sqlite_rc == SQLITE_ROW) {
        set_scalar_subquery_row_count_error(database);
        return MYLITE_ERROR;
    }
    if (sqlite_rc != SQLITE_DONE) {
        return mylite_sqlite_status_to_mylite(sqlite_rc);
    }

    return MYLITE_OK;
}

static int materialize_update_scalar_subquery_sqlite_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct planned_update *plan,
    struct planned_value *out_value
) {
    const struct mylite_catalog_column_descriptor *source_column =
        &plan->assignment_subquery.columns[0];
    const struct mylite_catalog_column_descriptor *target_column = &plan->assignment_column;
    int sqlite_type = sqlite3_column_type(statement, 0);

    if (sqlite_type == SQLITE_NULL) {
        if (!target_column->is_nullable) {
            set_bad_null_error(database, target_column->name);
            return MYLITE_ERROR;
        }
        *out_value = (struct planned_value){.is_null = true};
        return MYLITE_OK;
    }
    if (!update_scalar_subquery_source_target_types_are_compatible(source_column, target_column)) {
        set_unsupported_error(
            database,
            update_scalar_subquery_implicit_conversion_message(target_column)
        );
        return MYLITE_ERROR;
    }
    if (column_descriptor_is_approximate(target_column)) {
        return materialize_update_scalar_subquery_approximate_value(
            database,
            statement,
            target_column,
            out_value
        );
    }
    if (update_scalar_subquery_target_uses_text_storage(target_column)) {
        return materialize_update_scalar_subquery_text_storage_value(
            database,
            statement,
            target_column,
            out_value
        );
    }
    if (update_scalar_subquery_target_uses_blob_storage(target_column)) {
        return materialize_update_scalar_subquery_blob_storage_value(
            database,
            statement,
            target_column,
            out_value
        );
    }

    return materialize_update_scalar_subquery_integer_value(
        database,
        statement,
        sqlite_type,
        target_column,
        out_value
    );
}

static bool update_scalar_subquery_target_uses_text_storage(
    const struct mylite_catalog_column_descriptor *target_column
) {
    if (column_descriptor_is_string_family(target_column)) {
        return true;
    }
    if (column_descriptor_is_json(target_column)) {
        return true;
    }
    if (column_descriptor_is_decimal(target_column)) {
        return true;
    }
    if (column_descriptor_is_date(target_column)) {
        return true;
    }
    if (column_descriptor_is_time(target_column)) {
        return true;
    }
    if (column_descriptor_is_datetime(target_column)) {
        return true;
    }
    if (column_descriptor_is_timestamp(target_column)) {
        return true;
    }
    if (column_descriptor_is_year(target_column)) {
        return true;
    }
    return false;
}

static bool update_scalar_subquery_target_uses_blob_storage(
    const struct mylite_catalog_column_descriptor *target_column
) {
    return (column_descriptor_is_binary_string_family(target_column) ||
            column_descriptor_is_bit(target_column)) != 0;
}

static int materialize_update_scalar_subquery_text_storage_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct mylite_catalog_column_descriptor *target_column,
    struct planned_value *out_value
) {
    int rc = validate_update_scalar_subquery_text_storage_value(database, statement, target_column);

    if (rc == MYLITE_OK) {
        rc = copy_update_scalar_subquery_text_value(database, statement, 0, out_value);
    }
    return rc;
}

static int materialize_update_scalar_subquery_blob_storage_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct mylite_catalog_column_descriptor *target_column,
    struct planned_value *out_value
) {
    if (column_descriptor_is_bit(target_column)) {
        return materialize_sqlite_bit_value(database, statement, 0, target_column, 1U, out_value);
    }
    return materialize_sqlite_binary_string_value(
        database,
        statement,
        0,
        target_column,
        1U,
        out_value
    );
}

static int validate_update_scalar_subquery_text_storage_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct mylite_catalog_column_descriptor *target_column
) {
    if (column_descriptor_is_string_family(target_column)) {
        return validate_insert_select_string_value(database, statement, 0, target_column, 1U);
    }
    if (column_descriptor_is_json(target_column)) {
        return validate_insert_select_json_value(database, statement, 0, target_column);
    }
    if (column_descriptor_is_decimal(target_column)) {
        return validate_insert_select_decimal_value(database, statement, 0, target_column, 1U);
    }
    if (column_descriptor_is_date(target_column)) {
        return validate_insert_select_date_value(database, statement, 0, target_column, 1U);
    }
    if (column_descriptor_is_time(target_column)) {
        return validate_insert_select_time_value(database, statement, 0, target_column, 1U);
    }
    if (column_descriptor_is_datetime(target_column)) {
        return validate_insert_select_datetime_value(database, statement, 0, target_column, 1U);
    }
    if (column_descriptor_is_year(target_column)) {
        return validate_insert_select_year_value(database, statement, 0, target_column, 1U);
    }
    return validate_insert_select_timestamp_value(database, statement, 0, target_column, 1U);
}

static int materialize_update_scalar_subquery_approximate_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    const struct mylite_catalog_column_descriptor *target_column,
    struct planned_value *out_value
) {
    int rc = validate_insert_select_approximate_value(database, statement, 0, target_column, 1U);

    if (rc == MYLITE_OK) {
        *out_value = (struct planned_value){
            .is_null = false,
            .is_real = true,
            .real = sqlite3_column_double(statement, 0),
        };
    }
    return rc;
}

static int materialize_update_scalar_subquery_integer_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int sqlite_type,
    const struct mylite_catalog_column_descriptor *target_column,
    struct planned_value *out_value
) {
    int rc = MYLITE_OK;

    if (sqlite_type != SQLITE_INTEGER) {
        set_unsupported_error(
            database,
            "UPDATE scalar subquery assignment does not support implicit integer conversion"
        );
        return MYLITE_ERROR;
    }

    rc = validate_insert_select_integer_value(database, statement, 0, target_column, 1U);
    if (rc == MYLITE_OK) {
        *out_value = (struct planned_value){
            .is_null = false,
            .integer = (int64_t)sqlite3_column_int64(statement, 0),
        };
    }
    return rc;
}

static int copy_update_scalar_subquery_text_value(
    struct mylite_db *database,
    sqlite3_stmt *statement,
    int selected_column_index,
    struct planned_value *out_value
) {
    const unsigned char *text = sqlite3_column_text(statement, selected_column_index);
    int byte_count = sqlite3_column_bytes(statement, selected_column_index);
    char *copy = NULL;

    if (text == NULL || byte_count < 0) {
        set_physical_sqlite_row_error(database);
        return MYLITE_ERROR;
    }
    copy = malloc((size_t)byte_count + 1U);
    if (copy == NULL) {
        set_nomem_error(database);
        return MYLITE_NOMEM;
    }
    memcpy(copy, text, (size_t)byte_count);
    copy[(size_t)byte_count] = '\0';

    return assign_text_value(database, copy, (size_t)byte_count, out_value);
}

static bool update_scalar_subquery_source_target_types_are_compatible(
    const struct mylite_catalog_column_descriptor *source_column,
    const struct mylite_catalog_column_descriptor *target_column
) {
    return insert_select_source_target_types_are_compatible(source_column, target_column);
}

static const char *update_scalar_subquery_implicit_conversion_message(
    const struct mylite_catalog_column_descriptor *target_column
) {
    if (column_descriptor_is_string_family(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit string conversion";
    }
    if (column_descriptor_is_json(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit JSON conversion";
    }
    if (column_descriptor_is_enum(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit ENUM conversion";
    }
    if (column_descriptor_is_set(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit SET conversion";
    }
    if (column_descriptor_is_binary_string_family(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit binary string "
               "conversion";
    }
    if (column_descriptor_is_bit(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit BIT conversion";
    }
    if (column_descriptor_is_decimal(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit DECIMAL conversion";
    }
    if (column_descriptor_is_approximate(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit FLOAT or DOUBLE "
               "conversion";
    }
    if (column_descriptor_is_date(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit DATE conversion";
    }
    if (column_descriptor_is_time(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit TIME conversion";
    }
    if (column_descriptor_is_datetime(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit DATETIME conversion";
    }
    if (column_descriptor_is_timestamp(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit TIMESTAMP conversion";
    }
    if (column_descriptor_is_year(target_column)) {
        return "UPDATE scalar subquery assignment does not support implicit YEAR conversion";
    }

    return "UPDATE scalar subquery assignment does not support implicit integer conversion";
}

static int convert_update_integer_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    const struct mylite_catalog_column_descriptor *column,
    struct planned_value *out_value
) {
    const struct mylite_sql_ast_node *literal = value_node;
    bool is_negative = false;
    uint64_t magnitude = 0U;
    int rc = MYLITE_OK;

    if (value_node->kind == MYLITE_SQL_AST_UNARY_EXPRESSION) {
        enum mylite_sql_ast_operator operator_kind = mylite_sql_ast_node_operator(value_node);

        if (operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE) {
            is_negative = true;
        } else if (operator_kind != MYLITE_SQL_AST_OPERATOR_POSITIVE) {
            set_unsupported_error(
                database,
                "UPDATE supports only integer, boolean, NULL, and DEFAULT assignment values"
            );
            return MYLITE_ERROR;
        }
        literal = child_at(value_node, 0U);
    }
    if (!boolean_literal_magnitude(literal, &magnitude)) {
        if (literal == NULL || literal->kind != MYLITE_SQL_AST_LITERAL ||
            mylite_sql_ast_node_literal_kind(literal) != MYLITE_SQL_AST_LITERAL_INTEGER) {
            set_unsupported_error(
                database,
                "UPDATE supports only integer, boolean, NULL, and DEFAULT assignment values"
            );
            return MYLITE_ERROR;
        }

        rc = parse_unsigned_integer_literal(&literal->span, &magnitude);
        if (rc != MYLITE_OK) {
            set_out_of_range_error(database, column->name, 1U);
            return MYLITE_ERROR;
        }
    }

    out_value->is_null = false;
    rc = convert_integer_for_column(
        database,
        magnitude,
        is_negative,
        column,
        1U,
        &out_value->integer
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    return MYLITE_OK;
}

static int plan_update_limit(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *limit_clause,
    struct planned_select_limit *out_limit
) {
    int rc = MYLITE_OK;

    out_limit->has_limit = false;
    out_limit->row_count = 0;
    out_limit->has_offset = false;
    out_limit->offset = 0;
    if (limit_clause == NULL) {
        return MYLITE_OK;
    }
    if (limit_clause->kind != MYLITE_SQL_AST_LIMIT_CLAUSE) {
        set_unsupported_error(database, "UPDATE supports only LIMIT row_count");
        return MYLITE_ERROR;
    }
    if (child_at(limit_clause, 1U) != NULL) {
        set_unsupported_error(database, "UPDATE supports only LIMIT row_count");
        return MYLITE_ERROR;
    }

    rc = convert_limit_integer_literal(database, child_at(limit_clause, 0U), &out_limit->row_count);
    if (rc != MYLITE_OK) {
        return rc;
    }
    out_limit->has_limit = true;

    return MYLITE_OK;
}

static int convert_limit_integer_literal(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *value_node,
    int64_t *out_value
) {
    const uint64_t sqlite_int64_positive_max = 9223372036854775807ULL;
    uint64_t magnitude = 0U;
    int rc = MYLITE_OK;

    if (value_node == NULL || value_node->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(value_node) != MYLITE_SQL_AST_LITERAL_INTEGER) {
        set_unsupported_error(database, "LIMIT supports only unsigned decimal integer literals");
        return MYLITE_ERROR;
    }

    rc = parse_unsigned_integer_literal(&value_node->span, &magnitude);
    if (rc != MYLITE_OK || magnitude > sqlite_int64_positive_max) {
        set_limit_out_of_range_error(database);
        return MYLITE_ERROR;
    }

    *out_value = (int64_t)magnitude;
    return MYLITE_OK;
}

static int integer_range_for_column(
    struct mylite_db *database,
    const struct mylite_catalog_column_descriptor *column,
    const char *unsupported_message,
    struct integer_column_range *out_range
) {
    const uint64_t int_signed_positive_max = 2147483647ULL;
    const uint64_t int_signed_negative_abs_max = 2147483648ULL;
    const uint64_t int_unsigned_max = 4294967295ULL;
    const uint64_t mediumint_signed_positive_max = 8388607ULL;
    const uint64_t mediumint_signed_negative_abs_max = 8388608ULL;
    const uint64_t mediumint_unsigned_max = 16777215ULL;
    const uint64_t smallint_signed_positive_max = 32767ULL;
    const uint64_t smallint_signed_negative_abs_max = 32768ULL;
    const uint64_t smallint_unsigned_max = 65535ULL;
    const uint64_t tinyint_signed_positive_max = 127ULL;
    const uint64_t tinyint_signed_negative_abs_max = 128ULL;
    const uint64_t tinyint_unsigned_max = 255ULL;
    const uint64_t bigint_signed_positive_max = 9223372036854775807ULL;
    const uint64_t bigint_signed_negative_abs_max = 9223372036854775808ULL;

    if (strcmp(column->logical_type, "TINYINT") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = tinyint_signed_positive_max,
            .negative_abs_max = tinyint_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "TINYINT(1)") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = tinyint_signed_positive_max,
            .negative_abs_max = tinyint_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "TINYINT UNSIGNED") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = tinyint_unsigned_max,
            .negative_abs_max = 0U,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "SMALLINT") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = smallint_signed_positive_max,
            .negative_abs_max = smallint_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "SMALLINT UNSIGNED") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = smallint_unsigned_max,
            .negative_abs_max = 0U,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "MEDIUMINT") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = mediumint_signed_positive_max,
            .negative_abs_max = mediumint_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "MEDIUMINT UNSIGNED") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = mediumint_unsigned_max,
            .negative_abs_max = 0U,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "INT") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = int_signed_positive_max,
            .negative_abs_max = int_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "INT UNSIGNED") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = int_unsigned_max,
            .negative_abs_max = 0U,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "BIGINT") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = bigint_signed_positive_max,
            .negative_abs_max = bigint_signed_negative_abs_max,
        };
        return MYLITE_OK;
    }
    if (strcmp(column->logical_type, "BIGINT UNSIGNED") == 0) {
        *out_range = (struct integer_column_range){
            .positive_max = bigint_signed_positive_max,
            .negative_abs_max = 0U,
        };
        return MYLITE_OK;
    }

    set_unsupported_error(database, unsupported_message);
    return MYLITE_ERROR;
}

static int append_show_table(const struct mylite_catalog_table_descriptor *table, void *user_data) {
    struct show_tables_context *context = user_data;
    const char *values[1] = {NULL};

    if (table == NULL || context == NULL || context->result == NULL) {
        return MYLITE_MISUSE;
    }

    if (!show_like_filter_matches(context->filter, table->name, true)) {
        return MYLITE_OK;
    }

    values[0] = table->name;

    return mylite_result_append_text_row(context->result, values);
}

static int append_show_table_status(
    const struct mylite_catalog_table_descriptor *table,
    void *user_data
) {
    struct show_table_status_context *context = user_data;
    int64_t row_count = 0;
    int64_t average_row_length = 0;
    char row_count_text[integer_text_capacity];
    char average_row_length_text[integer_text_capacity];
    char auto_increment_text[integer_text_capacity];
    struct mylite_catalog_column_descriptor *columns = NULL;
    size_t column_count = 0U;
    bool has_auto_increment = false;
    const char *values[show_table_status_result_column_count] = {
        NULL,
        "InnoDB",
        "10",
        "Dynamic",
        row_count_text,
        average_row_length_text,
        "16384",
        "0",
        "0",
        "0",
        NULL,
        NULL,
        NULL,
        NULL,
        table->default_collation,
        NULL,
        "",
        "",
    };
    int rc = MYLITE_OK;

    if (table == NULL || context == NULL || context->database == NULL || context->result == NULL) {
        return MYLITE_MISUSE;
    }
    if (table->kind != MYLITE_CATALOG_TABLE_KIND_BASE) {
        return MYLITE_OK;
    }
    if (!show_like_filter_matches(context->filter, table->name, true)) {
        return MYLITE_OK;
    }

    rc = read_show_table_status_row_count(context->database, table, &row_count);
    if (rc == MYLITE_NOMEM) {
        set_nomem_error(context->database);
        return rc;
    }
    if (rc != MYLITE_OK) {
        set_runtime_error(context->database, "failed to read SHOW TABLE STATUS row count");
        return MYLITE_ERROR;
    }

    if (row_count > 0) {
        average_row_length = show_table_status_data_length / row_count;
    }
    rc = format_show_table_status_integer(
        context->database,
        row_count,
        row_count_text,
        sizeof(row_count_text)
    );
    if (rc == MYLITE_OK) {
        rc = format_show_table_status_integer(
            context->database,
            average_row_length,
            average_row_length_text,
            sizeof(average_row_length_text)
        );
    }
    if (rc != MYLITE_OK) {
        return rc;
    }
    rc = load_table_columns(context->database, table->table_id, &columns, &column_count);
    if (rc == MYLITE_OK) {
        for (size_t column_index = 0U; column_index < column_count; ++column_index) {
            if (column_descriptor_is_auto_increment(&columns[column_index])) {
                has_auto_increment = true;
                break;
            }
        }
    }
    free(columns);
    if (rc != MYLITE_OK) {
        set_runtime_error(context->database, "failed to read SHOW TABLE STATUS columns");
        return MYLITE_ERROR;
    }
    if (has_auto_increment) {
        rc = format_show_table_status_integer(
            context->database,
            table->auto_increment_next,
            auto_increment_text,
            sizeof(auto_increment_text)
        );
        if (rc != MYLITE_OK) {
            return rc;
        }
        values[show_table_status_auto_increment_column] = auto_increment_text;
    }

    values[0] = table->name;

    rc = mylite_result_append_text_row(context->result, values);
    if (rc == MYLITE_NOMEM) {
        set_nomem_error(context->database);
    }
    return rc;
}

static int append_show_column(
    const struct mylite_catalog_column_descriptor *column,
    void *user_data
) {
    struct show_columns_context *context = user_data;
    const char *type_text = NULL;
    char type_text_storage[MYLITE_CATALOG_TYPE_NAME_CAPACITY];
    char default_text[integer_text_capacity];
    const char *values[show_full_columns_result_column_count] = {0};
    int rc = MYLITE_OK;

    if (column == NULL || context == NULL || context->result == NULL) {
        return MYLITE_MISUSE;
    }

    if (!show_like_filter_matches(context->filter, column->name, false)) {
        return MYLITE_OK;
    }

    rc = show_column_type_text(
        context->database,
        column->logical_type,
        type_text_storage,
        sizeof(type_text_storage),
        &type_text
    );
    if (rc != MYLITE_OK) {
        return rc;
    }

    values[0] = column->name;
    values[1] = type_text;
    if (context->full) {
        values[2] = show_column_collation_text(context->table, column);
        values[3] = "NO";
        if (column->is_nullable) {
            values[3] = "YES";
        }
        values[4] = column_key_text(
            (struct loaded_index_info_span){
                .indexes = context->indexes,
                .count = context->index_count,
            },
            context->primary_key,
            column
        );
        rc = column_default_display_text(
            context->database,
            column,
            default_text,
            sizeof(default_text),
            &values[show_full_columns_default_column]
        );
        if (rc != MYLITE_OK) {
            return rc;
        }
        values[show_full_columns_extra_column] = column_extra_text(column);
        values[show_full_columns_privileges_column] = "select,insert,update,references";
        values[show_full_columns_comment_column] = "";

        return mylite_result_append_text_row(context->result, values);
    }

    values[2] = "NO";
    if (column->is_nullable) {
        values[2] = "YES";
    }
    values[3] = column_key_text(
        (struct loaded_index_info_span){
            .indexes = context->indexes,
            .count = context->index_count,
        },
        context->primary_key,
        column
    );
    rc = column_default_display_text(
        context->database,
        column,
        default_text,
        sizeof(default_text),
        &values[4]
    );
    if (rc != MYLITE_OK) {
        return rc;
    }
    values[show_columns_extra_column] = column_extra_text(column);

    return mylite_result_append_text_row(context->result, values);
}

static int append_show_index(
    struct mylite_db *database,
    mylite_result *result,
    const struct table_name_resolution *target,
    const struct loaded_index_info *index
) {
    static const char cardinality[] = "0";
    static const char non_unique[] = "1";
    static const char unique[] = "0";
    char sequence[integer_text_capacity];
    const char *non_unique_text = non_unique;
    int rc = MYLITE_OK;

    if (database == NULL || result == NULL || target == NULL || index == NULL) {
        return MYLITE_MISUSE;
    }
    if (index->index.is_unique) {
        non_unique_text = unique;
    }

    for (size_t part_index = 0U; rc == MYLITE_OK && part_index < index->part_count; ++part_index) {
        const struct loaded_index_part *part = &index->parts[part_index];
        char prefix_text[integer_text_capacity];
        const char *nullable = "";
        const char *prefix_value = NULL;

        if (part->column.is_nullable) {
            nullable = "YES";
        }
        if (part->index_column.has_prefix_length) {
            rc = information_schema_format_i64(
                database,
                part->index_column.prefix_length,
                prefix_text,
                sizeof(prefix_text)
            );
            if (rc != MYLITE_OK) {
                return rc;
            }
            prefix_value = prefix_text;
        }
        const char *values[show_index_result_column_count] = {
            target->table_name,
            non_unique_text,
            index->index.name,
            sequence,
            part->column.name,
            "A",
            cardinality,
            prefix_value,
            NULL,
            nullable,
            "BTREE",
            "",
            "",
            "YES",
            NULL,
        };

        rc = information_schema_format_i64(
            database,
            part->index_column.ordinal_position,
            sequence,
            sizeof(sequence)
        );
        if (rc == MYLITE_OK) {
            rc = mylite_result_append_text_row(result, values);
        }
    }

    return rc;
}

static int show_column_type_text(
    struct mylite_db *database,
    const char *logical_type,
    char *buffer,
    size_t buffer_size,
    const char **out_type_text
) {
    return show_descriptor_type_text(
        database,
        logical_type,
        buffer,
        buffer_size,
        "SHOW COLUMNS supports only integer, BIT, string, decimal, approximate numeric, DATE, "
        "TIME, DATETIME, and TIMESTAMP column descriptors",
        out_type_text
    );
}

static const char *show_column_collation_text(
    const struct mylite_catalog_table_descriptor *table,
    const struct mylite_catalog_column_descriptor *column
) {
    if (column_descriptor_is_string_family(column) || column_descriptor_is_enum(column) ||
        column_descriptor_is_set(column)) {
        if (column_descriptor_is_national_char_or_varchar(column)) {
            return national_collation_name;
        }
        if (table != NULL && table->default_collation[0] != '\0') {
            return table->default_collation;
        }
        return MYLITE_CATALOG_DEFAULT_TABLE_COLLATION;
    }

    return NULL;
}

static int append_show_database(
    const struct mylite_catalog_schema_descriptor *schema,
    void *user_data
) {
    struct show_databases_context *context = user_data;
    const char *values[1] = {NULL};

    if (schema == NULL || context == NULL || context->result == NULL) {
        return MYLITE_MISUSE;
    }

    if (!show_like_filter_matches(context->filter, schema->name, true)) {
        return MYLITE_OK;
    }

    values[0] = schema->name;

    return mylite_result_append_text_row(context->result, values);
}

static int make_show_like_filter(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *pattern_node,
    struct show_like_filter *out_filter
) {
    char *pattern = NULL;
    int rc = MYLITE_OK;

    if (out_filter == NULL) {
        set_runtime_error(database, "invalid SHOW LIKE filter");
        return MYLITE_ERROR;
    }
    *out_filter = (struct show_like_filter){
        .has_pattern = false,
        .pattern = NULL,
        .pattern_length = 0U,
    };
    if (pattern_node == NULL) {
        return MYLITE_OK;
    }

    rc = decode_show_like_pattern(database, pattern_node, &pattern);
    if (rc != MYLITE_OK) {
        return rc;
    }

    out_filter->has_pattern = true;
    out_filter->pattern = pattern;
    out_filter->pattern_length = strlen(pattern);
    return MYLITE_OK;
}

static void show_like_filter_deinit(struct show_like_filter *filter) {
    if (filter == NULL) {
        return;
    }

    free(filter->pattern);
    *filter = (struct show_like_filter){
        .has_pattern = false,
        .pattern = NULL,
        .pattern_length = 0U,
    };
}

static bool show_like_filter_matches(
    const struct show_like_filter *filter,
    const char *value,
    bool case_sensitive
) {
    if (filter == NULL || !filter->has_pattern) {
        return true;
    }
    if (value == NULL) {
        return false;
    }

    return show_like_pattern_matches(
        filter->pattern,
        filter->pattern_length,
        value,
        strlen(value),
        case_sensitive
    );
}

static int build_show_databases_column_name(
    const struct show_like_filter *filter,
    char **out_name
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    if (out_name == NULL) {
        return MYLITE_MISUSE;
    }
    *out_name = NULL;

    dynamic_string_init(&string);
    rc = dynamic_string_append(&string, "Database");
    if (rc == MYLITE_OK && filter != NULL && filter->has_pattern) {
        rc = dynamic_string_append(&string, " (");
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(&string, filter->pattern);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(&string, ')');
        }
    }
    if (rc == MYLITE_OK) {
        *out_name = dynamic_string_take(&string);
        if (*out_name == NULL) {
            rc = MYLITE_NOMEM;
        }
    }
    dynamic_string_deinit(&string);
    return rc;
}

static int build_show_tables_column_name(
    const char *schema_name,
    const struct show_like_filter *filter,
    char **out_name
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    if (schema_name == NULL || out_name == NULL) {
        return MYLITE_MISUSE;
    }
    *out_name = NULL;

    dynamic_string_init(&string);
    rc = dynamic_string_append(&string, "Tables_in_");
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(&string, schema_name);
    }
    if (rc == MYLITE_OK && filter != NULL && filter->has_pattern) {
        rc = dynamic_string_append(&string, " (");
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(&string, filter->pattern);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(&string, ')');
        }
    }
    if (rc == MYLITE_OK) {
        *out_name = dynamic_string_take(&string);
        if (*out_name == NULL) {
            rc = MYLITE_NOMEM;
        }
    }
    dynamic_string_deinit(&string);
    return rc;
}

static int read_show_table_status_row_count(
    struct mylite_db *database,
    const struct mylite_catalog_table_descriptor *table,
    int64_t *out_count
) {
    sqlite3_stmt *statement = NULL;
    char *sql = NULL;
    int rc = build_show_table_status_count_sql(table, &sql);

    if (rc == MYLITE_OK) {
        rc = prepare_sqlite_statement(database, sql, &statement);
    }
    if (rc == MYLITE_OK) {
        rc = step_count_statement(statement, out_count);
    }

    rc = finalize_sqlite_statement(statement, rc);
    free(sql);

    return rc;
}

static int build_show_table_status_count_sql(
    const struct mylite_catalog_table_descriptor *table,
    char **out_sql
) {
    struct dynamic_string string;
    int rc = MYLITE_OK;

    if (table == NULL || out_sql == NULL) {
        return MYLITE_MISUSE;
    }
    *out_sql = NULL;
    dynamic_string_init(&string);

    rc = dynamic_string_append(&string, "SELECT COUNT(*) FROM ");
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(&string, table->physical_name);
    }
    if (rc == MYLITE_OK) {
        *out_sql = dynamic_string_take(&string);
        if (*out_sql == NULL) {
            rc = MYLITE_NOMEM;
        }
    }

    dynamic_string_deinit(&string);

    return rc;
}

static int format_show_table_status_integer(
    struct mylite_db *database,
    int64_t value,
    char *buffer,
    size_t buffer_size
) {
    int written = snprintf(buffer, buffer_size, "%" PRId64, value);

    if (written < 0 || (size_t)written >= buffer_size) {
        set_runtime_error(database, "failed to format SHOW TABLE STATUS value");
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int decode_show_like_pattern(
    struct mylite_db *database,
    const struct mylite_sql_ast_node *pattern_node,
    char **out_pattern
) {
    struct dynamic_string string;
    const char *text = NULL;
    size_t length = 0U;
    char quote = '\0';
    int rc = MYLITE_OK;

    if (out_pattern == NULL) {
        set_runtime_error(database, "invalid SHOW LIKE pattern");
        return MYLITE_ERROR;
    }
    *out_pattern = NULL;
    if (pattern_node == NULL || pattern_node->kind != MYLITE_SQL_AST_LITERAL ||
        mylite_sql_ast_node_literal_kind(pattern_node) != MYLITE_SQL_AST_LITERAL_STRING) {
        set_unsupported_error(database, "SHOW LIKE supports only string literal patterns");
        return MYLITE_ERROR;
    }

    text = pattern_node->span.text;
    length = pattern_node->span.length;
    if (text == NULL || length < 2U) {
        set_runtime_error(database, "invalid SHOW LIKE pattern");
        return MYLITE_ERROR;
    }

    quote = text[0];
    dynamic_string_init(&string);
    for (size_t index = 1U; rc == MYLITE_OK && index + 1U < length; ++index) {
        char byte = text[index];

        if (byte == quote && index + 2U < length && text[index + 1U] == quote) {
            rc = dynamic_string_append_char(&string, quote);
            ++index;
        } else if (byte == '\\' && index + 2U < length) {
            ++index;
            rc = append_decoded_string_escape(database, &string, text[index]);
        } else {
            rc = dynamic_string_append_char(&string, byte);
        }
    }
    if (rc == MYLITE_OK && string.text == NULL) {
        rc = dynamic_string_append(&string, "");
    }
    if (rc == MYLITE_OK) {
        *out_pattern = dynamic_string_take(&string);
        if (*out_pattern == NULL) {
            rc = MYLITE_NOMEM;
        }
    }
    if (rc == MYLITE_NOMEM) {
        set_nomem_error(database);
    }
    dynamic_string_deinit(&string);
    return rc;
}

static int append_decoded_string_escape(
    struct mylite_db *database,
    struct dynamic_string *string,
    char escaped_byte
) {
    switch (escaped_byte) {
    case '0':
        set_unsupported_error(database, "SHOW LIKE does not support NUL bytes in patterns");
        return MYLITE_ERROR;
    case 'n':
        return dynamic_string_append_char(string, '\n');
    case 'r':
        return dynamic_string_append_char(string, '\r');
    case 't':
        return dynamic_string_append_char(string, '\t');
    case 'b':
        return dynamic_string_append_char(string, '\b');
    case 'Z':
        return dynamic_string_append_char(string, '\032');
    case '\\':
        return dynamic_string_append_char(string, '\\');
    case '\'':
        return dynamic_string_append_char(string, '\'');
    case '"':
        return dynamic_string_append_char(string, '"');
    case '%':
        if (dynamic_string_append_char(string, '\\') != MYLITE_OK) {
            return MYLITE_NOMEM;
        }
        return dynamic_string_append_char(string, '%');
    case '_':
        if (dynamic_string_append_char(string, '\\') != MYLITE_OK) {
            return MYLITE_NOMEM;
        }
        return dynamic_string_append_char(string, '_');
    default:
        return dynamic_string_append_char(string, escaped_byte);
    }
}

static bool show_like_pattern_matches(
    const char *pattern,
    size_t pattern_length,
    const char *value,
    size_t value_length,
    bool case_sensitive
) {
    const size_t no_retry_pattern = SIZE_MAX;
    size_t pattern_index = 0U;
    size_t value_index = 0U;
    size_t retry_pattern_index = no_retry_pattern;
    size_t retry_value_index = 0U;

    while (value_index < value_length) {
        size_t next_pattern_index = pattern_index;

        if (pattern_index < pattern_length && pattern[pattern_index] == '%') {
            pattern_index = show_like_skip_percent_run(pattern, pattern_length, pattern_index);
            if (pattern_index == pattern_length) {
                return true;
            }
            retry_pattern_index = pattern_index;
            retry_value_index = value_index;
            continue;
        }
        if (show_like_pattern_item_matches(
                (struct show_like_pattern_item_request){
                    .pattern = pattern,
                    .pattern_length = pattern_length,
                    .pattern_index = pattern_index,
                    .value_byte = value[value_index],
                    .case_sensitive = case_sensitive,
                },
                &next_pattern_index
            )) {
            pattern_index = next_pattern_index;
            ++value_index;
            continue;
        }
        if (retry_pattern_index == no_retry_pattern || retry_value_index >= value_length) {
            return false;
        }
        ++retry_value_index;
        value_index = retry_value_index;
        pattern_index = retry_pattern_index;
    }

    pattern_index = show_like_skip_percent_run(pattern, pattern_length, pattern_index);

    return pattern_index == pattern_length;
}

static size_t show_like_skip_percent_run(
    const char *pattern,
    size_t pattern_length,
    size_t pattern_index
) {
    while (pattern_index < pattern_length && pattern[pattern_index] == '%') {
        ++pattern_index;
    }
    return pattern_index;
}

static bool show_like_pattern_item_matches(
    struct show_like_pattern_item_request request,
    size_t *out_next_pattern_index
) {
    char pattern_byte = '\0';
    size_t next_pattern_index = request.pattern_index;

    if (request.pattern_index >= request.pattern_length || out_next_pattern_index == NULL) {
        return false;
    }

    pattern_byte = request.pattern[request.pattern_index];
    if (pattern_byte == '_') {
        *out_next_pattern_index = request.pattern_index + 1U;
        return true;
    }
    if (pattern_byte == '\\' && request.pattern_index + 1U < request.pattern_length) {
        ++next_pattern_index;
        pattern_byte = request.pattern[next_pattern_index];
    }
    ++next_pattern_index;
    if (!show_like_bytes_equal(pattern_byte, request.value_byte, request.case_sensitive)) {
        return false;
    }

    *out_next_pattern_index = next_pattern_index;
    return true;
}

static bool show_like_bytes_equal(char left, char right, bool case_sensitive) {
    if (case_sensitive) {
        return left == right;
    }

    return show_like_ascii_lower(left) == show_like_ascii_lower(right);
}

static char show_like_ascii_lower(char byte) {
    if (byte >= 'A' && byte <= 'Z') {
        return (char)(byte - 'A' + 'a');
    }
    return byte;
}

static int build_physical_table_name(int64_t table_id, char *destination, size_t destination_size) {
    int written = snprintf(destination, destination_size, "_mylite_user_table_%" PRId64, table_id);

    if (written < 0 || (size_t)written >= destination_size) {
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int build_physical_index_name(int64_t index_id, char *destination, size_t destination_size) {
    int written = snprintf(destination, destination_size, "_mylite_user_index_%" PRId64, index_id);

    if (written < 0 || (size_t)written >= destination_size) {
        return MYLITE_ERROR;
    }

    return MYLITE_OK;
}

static int build_create_table_sql(
    const struct planned_create_table *plan,
    const char *physical_name,
    bool temporary,
    char **out_sql
) {
    struct dynamic_string string;
    const char *create_prefix = "CREATE TABLE ";
    int rc = MYLITE_OK;

    *out_sql = NULL;
    dynamic_string_init(&string);

    if (temporary) {
        create_prefix = "CREATE TEMPORARY TABLE ";
    }
    rc = dynamic_string_append(&string, create_prefix);
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(&string, physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(&string, " (");
    }
    if (rc == MYLITE_OK) {
        rc = append_create_table_columns_sql(&string, plan);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_char(&string, ')');
    }
    if (rc == MYLITE_OK && plan->has_primary_key) {
        rc = append_create_table_primary_key_sql(&string, plan, physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = append_create_table_secondary_indexes_sql(&string, plan, physical_name);
    }
    if (rc == MYLITE_OK) {
        *out_sql = dynamic_string_take(&string);
        if (*out_sql == NULL) {
            rc = MYLITE_NOMEM;
        }
    }

    dynamic_string_deinit(&string);

    return rc;
}

static int append_create_table_columns_sql(
    struct dynamic_string *string,
    const struct planned_create_table *plan
) {
    int rc = MYLITE_OK;

    for (size_t column_index = 0U; rc == MYLITE_OK && column_index < plan->column_count;
         ++column_index) {
        const struct planned_column *column = &plan->columns[column_index];

        if (column_index != 0U) {
            rc = dynamic_string_append(string, ", ");
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_quoted_identifier(string, column->name);
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(string, ' ');
        }
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append(string, column->physical_type);
        }
        if (rc == MYLITE_OK && !column->is_nullable) {
            rc = dynamic_string_append(string, " NOT NULL");
        }
    }

    return rc;
}

static int append_create_table_primary_key_sql(
    struct dynamic_string *string,
    const struct planned_create_table *plan,
    const char *physical_name
) {
    int rc =
        append_create_table_index_sql(string, true, plan->primary_key_physical_name, physical_name);

    for (size_t part_index = 0U; rc == MYLITE_OK && part_index < plan->primary_key_part_count;
         ++part_index) {
        size_t column_index = plan->primary_key_parts[part_index].column_index;

        if (part_index != 0U) {
            rc = dynamic_string_append(string, ", ");
        }
        if (rc == MYLITE_OK) {
            rc = append_planned_key_part_sql(string, &plan->columns[column_index]);
        }
    }
    if (rc == MYLITE_OK) {
        rc = append_create_table_index_sql_close(string);
    }

    return rc;
}

static int append_create_table_secondary_indexes_sql(
    struct dynamic_string *string,
    const struct planned_create_table *plan,
    const char *physical_name
) {
    int rc = MYLITE_OK;

    for (size_t index = 0U; rc == MYLITE_OK && index < plan->secondary_index_count; ++index) {
        const struct planned_secondary_index *secondary = &plan->secondary_indexes[index];

        rc = append_create_table_index_sql(
            string,
            secondary->is_unique,
            secondary->physical_name,
            physical_name
        );
        for (size_t part_index = 0U; rc == MYLITE_OK && part_index < secondary->part_count;
             ++part_index) {
            if (part_index != 0U) {
                rc = dynamic_string_append(string, ", ");
            }
            if (rc == MYLITE_OK) {
                rc = append_planned_secondary_key_part_sql(
                    string,
                    plan,
                    &secondary->parts[part_index]
                );
            }
        }
        if (rc == MYLITE_OK) {
            rc = append_create_table_index_sql_close(string);
        }
    }

    return rc;
}

static int append_create_table_index_sql(
    struct dynamic_string *string,
    bool is_unique,
    const char *index_physical_name,
    const char *table_physical_name
) {
    int rc = dynamic_string_append(string, "; CREATE ");

    if (rc == MYLITE_OK && is_unique) {
        rc = dynamic_string_append(string, "UNIQUE ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, "INDEX ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, index_physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, " ON ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, table_physical_name);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, " (");
    }

    return rc;
}

static int append_create_table_index_sql_close(struct dynamic_string *string) {
    return dynamic_string_append_char(string, ')');
}

static int append_planned_key_part_sql(
    struct dynamic_string *string,
    const struct planned_column *column
) {
    int rc = dynamic_string_append_quoted_identifier(string, column->name);

    if (rc == MYLITE_OK && planned_column_is_char_or_varchar(column)) {
        rc = append_string_key_collation_sql(string);
    }

    return rc;
}

static int append_planned_secondary_key_part_sql(
    struct dynamic_string *string,
    const struct planned_create_table *plan,
    const struct planned_secondary_index_part *part
) {
    const struct planned_column *column = &plan->columns[part->column_index];
    char prefix_text[integer_text_capacity];
    int rc = MYLITE_OK;

    if (!part->has_prefix_length) {
        return append_planned_key_part_sql(string, column);
    }

    rc = dynamic_string_append(string, "substr(");
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, column->name);
    }
    if (rc == MYLITE_OK) {
        int written = snprintf(prefix_text, sizeof(prefix_text), "%" PRId64, part->prefix_length);

        if (written < 0 || (size_t)written >= sizeof(prefix_text)) {
            return MYLITE_NOMEM;
        }
        rc = dynamic_string_append(string, ", 1, ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, prefix_text);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_char(string, ')');
    }
    if (rc == MYLITE_OK) {
        rc = append_string_key_collation_sql(string);
    }

    return rc;
}

static int append_loaded_key_part_sql(
    struct dynamic_string *string,
    const struct loaded_index_part *part,
    const char *qualifier
) {
    int rc = MYLITE_OK;

    if (part != NULL && part->index_column.has_prefix_length) {
        return append_loaded_prefix_key_part_sql(string, part, qualifier);
    }

    if (qualifier != NULL) {
        rc = dynamic_string_append_quoted_identifier(string, qualifier);
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(string, '.');
        }
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, part->column.name);
    }
    if (rc == MYLITE_OK && column_descriptor_is_char_or_varchar(&part->column)) {
        rc = append_string_key_collation_sql(string);
    }

    return rc;
}

static int append_loaded_prefix_key_part_sql(
    struct dynamic_string *string,
    const struct loaded_index_part *part,
    const char *qualifier
) {
    char prefix_text[integer_text_capacity];
    int rc = MYLITE_OK;
    int written = 0;

    written =
        snprintf(prefix_text, sizeof(prefix_text), "%" PRId64, part->index_column.prefix_length);
    if (written < 0 || (size_t)written >= sizeof(prefix_text)) {
        return MYLITE_NOMEM;
    }

    rc = dynamic_string_append(string, "substr(");
    if (rc == MYLITE_OK && qualifier != NULL) {
        rc = dynamic_string_append_quoted_identifier(string, qualifier);
        if (rc == MYLITE_OK) {
            rc = dynamic_string_append_char(string, '.');
        }
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, part->column.name);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, ", 1, ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, prefix_text);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_char(string, ')');
    }
    if (rc == MYLITE_OK) {
        rc = append_string_key_collation_sql(string);
    }

    return rc;
}

static int append_loaded_key_part_parameter_sql(
    struct dynamic_string *string,
    const struct loaded_index_part *part,
    size_t parameter_index
) {
    char prefix_text[integer_text_capacity];
    int rc = MYLITE_OK;
    int written = 0;

    if (part == NULL || !part->index_column.has_prefix_length) {
        return append_numbered_parameter(string, parameter_index);
    }

    written =
        snprintf(prefix_text, sizeof(prefix_text), "%" PRId64, part->index_column.prefix_length);
    if (written < 0 || (size_t)written >= sizeof(prefix_text)) {
        return MYLITE_NOMEM;
    }

    rc = dynamic_string_append(string, "substr(");
    if (rc == MYLITE_OK) {
        rc = append_numbered_parameter(string, parameter_index);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, ", 1, ");
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append(string, prefix_text);
    }
    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_char(string, ')');
    }
    if (rc == MYLITE_OK) {
        rc = append_string_key_collation_sql(string);
    }

    return rc;
}

static int append_string_key_collation_sql(struct dynamic_string *string) {
    int rc = dynamic_string_append(string, " COLLATE ");

    if (rc == MYLITE_OK) {
        rc = dynamic_string_append_quoted_identifier(string, string_key_collation_name);
    }

    return rc;
}

