static int append_duplicate_key_warning(
    struct mylite_db *database,
    const char *table_name,
    const char *index_name,
    const char *value
) {
    char message[MYLITE_DIAGNOSTIC_MESSAGE_CAPACITY];
    int written = snprintf(
        message,
        sizeof(message),
        "Duplicate entry '%s' for key '%s.%s'",
        value,
        table_name,
        index_name
    );
    int rc = MYLITE_OK;

    if (written < 0) {
        message[0] = '\0';
    }
    rc = mylite_diagnostics_append_warning(
        mylite_connection_diagnostics(database),
        mysql_error_duplicate_key,
        "23000",
        message
    );
    if (rc == MYLITE_NOMEM) {
        set_nomem_error(database);
    }
    return rc;
}

static int append_no_referenced_row_warning(struct mylite_db *database) {
    int rc = mylite_diagnostics_append_warning(
        mylite_connection_diagnostics(database),
        mysql_error_no_referenced_row,
        "23000",
        "Cannot add or update a child row: a foreign key constraint fails"
    );

    if (rc == MYLITE_NOMEM) {
        set_nomem_error(database);
    }
    return rc;
}

